/**
 * Recently played holds until staff manually releases players.
 * Scoring saves stats but does not release. timeoutMs: null = never expire.
 *
 * Persistence shape (JSON-safe):
 * {
 *   epoch: number, // bumped on intentional clears / session end
 *   dismissedMatchIds: string[],
 *   releasedByMatch: { [matchId]: string[] }
 * }
 *
 * Every completed, non-dismissed match keeps its own card until released
 * (not just the latest match per court).
 *
 * Releases and dismissals are add-only within an epoch so cross-tab sync
 * cannot resurrect players by applying a stale snapshot.
 */
export const RECENT_TIMEOUT_MS = null;

export function lineupIds(match) {
  if (Array.isArray(match?.lineup) && match.lineup.length > 0) {
    return match.lineup.map((p) => (typeof p === "object" ? p.id : p)).filter((id) => id != null);
  }
  if (Array.isArray(match?.playerIds) && match.playerIds.length > 0) {
    return match.playerIds.filter((id) => id != null);
  }
  // Older / partial records may only retain team sides.
  const fromTeams = [
    ...(Array.isArray(match?.teams?.green) ? match.teams.green : []),
    ...(Array.isArray(match?.teams?.blue) ? match.teams.blue : []),
  ];
  return fromTeams.filter((id) => id != null);
}

function lineupEntry(match, playerId) {
  const key = String(playerId);
  if (Array.isArray(match?.lineup)) {
    const hit = match.lineup.find((p) => String(typeof p === "object" ? p.id : p) === key);
    if (hit && typeof hit === "object") return hit;
  }
  return null;
}

export function matchHasSavedScore(match) {
  return (
    match?.score?.green != null &&
    match?.score?.blue != null &&
    Number.isFinite(match.score.green) &&
    Number.isFinite(match.score.blue)
  );
}

function toIdList(value) {
  if (value instanceof Set) return Array.from(value).map(String).filter(Boolean);
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map(String).filter(Boolean))];
}

function releasedSetForMatch(releasedByMatch, matchId) {
  const ids = releasedByMatch?.[String(matchId)];
  return new Set(toIdList(ids));
}

/**
 * All completed matches that still have unreleased players.
 * One card per match — ending a new game adds a card; it does not replace prior ones.
 */
export function getRecentUnscoredMatches({
  matches = [],
  players = [],
  dismissedRecentMatchIds = new Set(),
  releasedByMatch = {},
  // legacy flat set — ignored (releases are per-match only)
  releasedRecentPlayerIds = null,
  now = Date.now(),
  timeoutMs = RECENT_TIMEOUT_MS,
} = {}) {
  void releasedRecentPlayerIds;

  const dismissed =
    dismissedRecentMatchIds instanceof Set
      ? dismissedRecentMatchIds
      : new Set(toIdList(dismissedRecentMatchIds));

  const completed = (matches || [])
    .filter((m) => m.status === "completed" && m.endTime)
    .filter((m) => !dismissed.has(String(m.id)))
    .filter((m) => {
      if (timeoutMs == null || !Number.isFinite(timeoutMs)) return true;
      return now - m.endTime <= timeoutMs;
    })
    .sort((a, b) => (b.endTime || 0) - (a.endTime || 0));

  const groups = [];
  for (const m of completed) {
    const mid = String(m.id);
    const released = releasedSetForMatch(releasedByMatch, mid);
    const ids = lineupIds(m);
    const groupPlayers = [];
    const seen = new Set();

    ids.forEach((id) => {
      const key = String(id);
      if (seen.has(key)) return;
      if (released.has(key)) return;
      seen.add(key);

      const player = players.find((p) => String(p.id) === key);
      if (player) {
        // Keep on the card even if they started another game — card stays until released.
        groupPlayers.push(player);
        return;
      }

      const stub = lineupEntry(m, key);
      if (stub) {
        groupPlayers.push({
          id: stub.id ?? id,
          name: stub.name || "Player",
          status: "stopped",
          level: stub.level,
          gender: stub.gender,
          teamId: stub.teamId,
        });
      }
    });

    if (groupPlayers.length === 0) continue;

    groups.push({
      match: m,
      matchId: mid,
      courtName: m.courtName || `Court ${m.courtId ?? ""}`,
      endTime: m.endTime,
      players: groupPlayers,
      isScored: matchHasSavedScore(m),
    });
  }

  return groups;
}

/** Players blocked from queueing until released from every open recent card. */
export function getRecentHeldPlayerIdSet({
  recentGroups = [],
} = {}) {
  const set = new Set();
  recentGroups.forEach((g) => {
    (g.players || []).forEach((p) => {
      // Only waiting players are blocked from re-queue; playing/queued are already busy.
      if (p.status !== "waiting") return;
      set.add(String(p.id));
    });
  });
  return set;
}

export function isPlayerInRecentHold(playerId, heldIdSet) {
  if (!heldIdSet || heldIdSet.size === 0) return false;
  return heldIdSet.has(String(playerId));
}

/** Persistable shape for recent-hold tracking (arrays/objects for JSON). */
export function normalizeRecentHold(raw = {}) {
  const epoch = Number.isFinite(Number(raw?.epoch)) ? Math.max(0, Math.floor(Number(raw.epoch))) : 0;
  const dismissedMatchIds = toIdList(raw.dismissedMatchIds);
  const releasedByMatch = {};
  const source =
    raw.releasedByMatch && typeof raw.releasedByMatch === "object"
      ? raw.releasedByMatch
      : {};
  Object.keys(source).forEach((mid) => {
    if (dismissedMatchIds.includes(String(mid))) return;
    const list = toIdList(source[mid]);
    if (list.length) releasedByMatch[String(mid)] = list;
  });
  return { epoch, dismissedMatchIds, releasedByMatch };
}

/**
 * CRDT-style merge for cross-tab sync.
 * Higher epoch wins (intentional clear / session end). Same epoch: union
 * dismissed ids + per-match released player ids (add-only).
 */
export function mergeRecentHold(local, remote) {
  const a = normalizeRecentHold(local);
  const b = normalizeRecentHold(remote);
  if (b.epoch > a.epoch) return b;
  if (a.epoch > b.epoch) return a;

  const dismissedMatchIds = toIdList([...a.dismissedMatchIds, ...b.dismissedMatchIds]);
  const releasedByMatch = {};
  const mids = new Set([
    ...Object.keys(a.releasedByMatch),
    ...Object.keys(b.releasedByMatch),
  ]);
  mids.forEach((mid) => {
    const key = String(mid);
    if (dismissedMatchIds.includes(key)) return;
    const list = toIdList([
      ...(a.releasedByMatch[key] || []),
      ...(b.releasedByMatch[key] || []),
    ]);
    if (list.length) releasedByMatch[key] = list;
  });
  return { epoch: a.epoch, dismissedMatchIds, releasedByMatch };
}

/** Bump epoch and clear holds (session end / explicit clear). */
export function clearRecentHoldState(prev = EMPTY_RECENT_HOLD) {
  const cur = normalizeRecentHold(prev);
  return {
    epoch: cur.epoch + 1,
    dismissedMatchIds: [],
    releasedByMatch: {},
  };
}

/**
 * Release one player from a recent-match card.
 * Uses match lineup ids (not the stale UI `group.players` snapshot) so
 * one-by-one closes remain correct under rapid clicks / re-renders.
 */
export function applyReleaseRecentPlayer(
  prev,
  { playerId, matchId, lineupPlayerIds } = {}
) {
  const pid = String(playerId ?? "");
  const mid = String(matchId ?? "");
  if (!pid || !mid) return normalizeRecentHold(prev);

  const next = normalizeRecentHold(prev);
  const existing = new Set(next.releasedByMatch[mid] || []);
  existing.add(pid);

  const lineup = toIdList(lineupPlayerIds);
  const everyoneReleased =
    lineup.length > 0 ? lineup.every((id) => existing.has(id)) : false;

  if (everyoneReleased) {
    if (!next.dismissedMatchIds.includes(mid)) {
      next.dismissedMatchIds = [...next.dismissedMatchIds, mid];
    }
    if (next.releasedByMatch[mid]) {
      const { [mid]: _removed, ...rest } = next.releasedByMatch;
      next.releasedByMatch = rest;
    }
    return next;
  }

  next.releasedByMatch = { ...next.releasedByMatch, [mid]: Array.from(existing) };
  return next;
}

/** Dismiss an entire recent-match card (Release all). */
export function applyReleaseRecentMatch(prev, matchId) {
  const mid = String(matchId ?? "");
  if (!mid) return normalizeRecentHold(prev);
  const next = normalizeRecentHold(prev);
  if (!next.dismissedMatchIds.includes(mid)) {
    next.dismissedMatchIds = [...next.dismissedMatchIds, mid];
  }
  if (next.releasedByMatch[mid]) {
    const { [mid]: _removed, ...rest } = next.releasedByMatch;
    next.releasedByMatch = rest;
  }
  return next;
}

export function recentHoldsEqual(a, b) {
  const x = normalizeRecentHold(a);
  const y = normalizeRecentHold(b);
  if (x.epoch !== y.epoch) return false;
  if (x.dismissedMatchIds.length !== y.dismissedMatchIds.length) return false;
  const dismissedX = new Set(x.dismissedMatchIds);
  if (y.dismissedMatchIds.some((id) => !dismissedX.has(id))) return false;
  const keysX = Object.keys(x.releasedByMatch);
  const keysY = Object.keys(y.releasedByMatch);
  if (keysX.length !== keysY.length) return false;
  for (const mid of keysX) {
    const listX = x.releasedByMatch[mid] || [];
    const listY = y.releasedByMatch[mid] || [];
    if (listX.length !== listY.length) return false;
    const setY = new Set(listY);
    if (listX.some((id) => !setY.has(id))) return false;
  }
  return true;
}

export function recentHoldViews(recentHold) {
  const norm = normalizeRecentHold(recentHold);
  return {
    dismissedRecentMatchIds: new Set(norm.dismissedMatchIds),
    releasedByMatch: norm.releasedByMatch,
  };
}

/**
 * Drop releasedByMatch entries for matches that are no longer completed/live.
 * Keep dismissedMatchIds forever within the epoch — they are tombstones.
 * Pruning dismissals when a peer briefly syncs a partial matches[] was resurrecting cards.
 */
export function pruneRecentHold(prev, matches = []) {
  const next = normalizeRecentHold(prev);
  const liveIds = new Set(
    (matches || [])
      .filter((m) => m.status === "completed" && m.endTime)
      .map((m) => String(m.id))
  );
  const prunedReleased = {};
  Object.keys(next.releasedByMatch).forEach((mid) => {
    if (!liveIds.has(String(mid))) return;
    if (next.dismissedMatchIds.includes(String(mid))) return;
    prunedReleased[mid] = next.releasedByMatch[mid];
  });
  const releasedKeys = Object.keys(prunedReleased);
  const prevKeys = Object.keys(next.releasedByMatch);
  const releasedSame =
    releasedKeys.length === prevKeys.length &&
    releasedKeys.every((k) => prevKeys.includes(k));
  if (releasedSame) return prev;
  return {
    epoch: next.epoch,
    dismissedMatchIds: next.dismissedMatchIds,
    releasedByMatch: prunedReleased,
  };
}

export const EMPTY_RECENT_HOLD = Object.freeze({
  epoch: 0,
  dismissedMatchIds: Object.freeze([]),
  releasedByMatch: Object.freeze({}),
});
