import React, { useCallback, useEffect, useMemo, useState } from "react";
import { PlayersModal } from "../queue";
import { APP_STORAGE_KEY, loadState } from "../../state/storage";
import config from "../../config";
import { computeTopTeams } from "../dashboard/utils/reports";
import { normalizeTeamsSettings } from "../../state/teamSettings";
import { resolveMatchSidesForDisplay } from "../../state/matchSides";
import {
  findCourtById,
  getPlayersOnCourt,
  listHasPlayerId,
  playerIdKey,
} from "../../state/courtPlayers";
import { normalizeDisplayRotation } from "../../common/utils/settingsDefaults";
import NormalView from "./components/NormalView";
import LeaderboardPodiumView from "./components/LeaderboardPodiumView";
import NextUpView from "./components/NextUpView";
import SponsorView from "./components/SponsorView";
import { useDisplayRotation } from "./hooks/useDisplayRotation";

function LiveClock({ compact = false }) {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);
  return (
    <div className="text-right leading-none font-body">
      <div
        className={`font-display font-extrabold italic text-white tabular-nums tracking-tight ${
          compact ? "text-2xl md:text-3xl" : "text-4xl md:text-5xl"
        }`}
      >
        {now.toLocaleTimeString("en-PH", {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hour12: true,
        })}
      </div>
      <div className={`text-white/60 uppercase tracking-[0.2em] font-body font-medium not-italic ${
        compact ? "text-[10px] mt-1" : "text-sm mt-2"
      }`}>
        {now.toLocaleDateString("en-PH", { weekday: "short", month: "short", day: "numeric" })}
      </div>
    </div>
  );
}

export default function DisplayPage() {
  const [courts, setCourts] = useState([]);
  const [players, setPlayers] = useState([]);
  const [matchQueue, setMatchQueue] = useState([]);
  const [matches, setMatches] = useState([]);
  const [settings, setSettings] = useState(() => ({}));
  const [teams, setTeams] = useState(() => []);
  const [currentOpSession, setCurrentOpSession] = useState(null);
  const [openCourtId, setOpenCourtId] = useState(null);

  const { activeView, activeSponsorIndex, forceNormal, resumeRotation } = useDisplayRotation(
    settings?.displayRotation
  );

  const rotationConfig = useMemo(
    () => normalizeDisplayRotation(settings?.displayRotation),
    [settings?.displayRotation]
  );

  const activeSponsorUrl =
    rotationConfig.sponsors?.[activeSponsorIndex]?.url ||
    rotationConfig.sponsorImageUrl ||
    "";

  const closeDisplayModal = useCallback(() => {
    if (openCourtId && typeof window !== "undefined" && "BroadcastChannel" in window) {
      const bc = new BroadcastChannel("dink_manager");
      bc.postMessage({ type: "CLOSE_MODAL", courtId: openCourtId });
      bc.close();
    }
    setOpenCourtId(null);
  }, [openCourtId]);

  useEffect(() => {
    if (!openCourtId) return undefined;
    const timer = setTimeout(() => closeDisplayModal(), 60000);
    return () => clearTimeout(timer);
  }, [openCourtId, closeDisplayModal]);

  useEffect(() => {
    const saved = loadState();
    setCourts(saved?.courts || config.getDefaultCourts());
    setPlayers(saved?.players || []);
    setMatchQueue(saved?.matchQueue || []);
    setMatches(saved?.matches || []);
    setSettings(saved?.settings || {});
    setTeams(Array.isArray(saved?.teams) ? saved.teams : []);
    setCurrentOpSession(saved?.currentOpSession || null);
  }, []);

  useEffect(() => {
    const prevZoom = document.body.style.zoom;
    return () => {
      document.body.style.zoom = prevZoom || "100%";
      document.body.style.overflowX = "auto";
    };
  }, []);

  useEffect(() => {
    const storageKey = APP_STORAGE_KEY;
    const applyIncomingState = (next) => {
      if (!next || typeof next !== "object") return;
      if (Object.prototype.hasOwnProperty.call(next, "courts")) {
        setCourts(Array.isArray(next.courts) ? next.courts : []);
      }
      if (Object.prototype.hasOwnProperty.call(next, "players")) {
        setPlayers(Array.isArray(next.players) ? next.players : []);
      }
      if (Object.prototype.hasOwnProperty.call(next, "matchQueue")) {
        setMatchQueue(Array.isArray(next.matchQueue) ? next.matchQueue : []);
      }
      if (Object.prototype.hasOwnProperty.call(next, "matches")) {
        setMatches((prev) => {
          if (!Array.isArray(next.matches)) return [];
          if (next.matches.length === 0) return [];
          const map = new Map();
          prev.forEach((m) => map.set(String(m.id), m));
          next.matches.forEach((m) => {
            const id = String(m?.id ?? "");
            if (!id) return;
            const prior = map.get(id) || {};
            map.set(id, { ...prior, ...m });
          });
          return Array.from(map.values());
        });
      }
      if (
        Object.prototype.hasOwnProperty.call(next, "settings") &&
        next.settings &&
        typeof next.settings === "object"
      ) {
        setSettings((prev) => ({
          ...prev,
          ...next.settings,
          teams: {
            ...(prev?.teams || {}),
            ...(next.settings?.teams && typeof next.settings.teams === "object"
              ? next.settings.teams
              : {}),
          },
          displayRotation: normalizeDisplayRotation({
            ...(prev?.displayRotation || {}),
            ...(next.settings?.displayRotation || {}),
          }),
        }));
      }
      if (Object.prototype.hasOwnProperty.call(next, "teams")) {
        setTeams(Array.isArray(next.teams) ? next.teams : []);
      }
      if (Object.prototype.hasOwnProperty.call(next, "currentOpSession")) {
        setCurrentOpSession(next.currentOpSession ?? null);
      }
    };

    const refreshFromStorage = () => {
      try {
        const fresh = loadState();
        if (fresh) applyIncomingState(fresh);
      } catch {
        /* ignore */
      }
    };

    const onStorage = (e) => {
      if (e.key === storageKey && e.newValue) {
        try {
          applyIncomingState(JSON.parse(e.newValue));
        } catch {
          /* ignore */
        }
      }
    };
    window.addEventListener("storage", onStorage);
    window.addEventListener("focus", refreshFromStorage);

    let bc;
    if ("BroadcastChannel" in window) {
      bc = new BroadcastChannel("dink_manager");
      bc.onmessage = (msg) => {
        const { type, courtId, payload, visible } = msg?.data || {};
        if (type === "OPEN_MODAL") {
          setOpenCourtId(courtId ?? null);
          forceNormal();
          refreshFromStorage();
        }
        if (type === "CLOSE_MODAL") setOpenCourtId(null);
        if (type === "DISPLAY_FORCE_COURT") forceNormal();
        if (type === "DISPLAY_RESUME_ROTATION") resumeRotation();
        if (type === "STATE_UPDATE" && payload) applyIncomingState(payload);
        if (type === "DISPLAY_QUEUE_VISIBILITY") {
          setSettings((prev) => ({
            ...prev,
            displayQueueVisible: visible !== false,
          }));
        }
      };
    }

    return () => {
      window.removeEventListener("storage", onStorage);
      window.removeEventListener("focus", refreshFromStorage);
      if (bc) bc.close();
    };
  }, [forceNormal, resumeRotation]);

  const teamsSettingsNorm = useMemo(
    () => normalizeTeamsSettings(settings?.teams),
    [settings?.teams]
  );

  const sessionTopTeams = useMemo(() => {
    const started = currentOpSession?.startedAt;
    if (!started || !settings?.teamsModeEnabled || teamsSettingsNorm.showTopTeamsOnDisplay === false)
      return [];
    const rows = computeTopTeams(
      matches,
      started,
      teamsSettingsNorm.topTeamsRankingMode || "winsFirst"
    );
    return rows.map((r) => ({
      ...r,
      displayName:
        teams.find((t) => String(t.id) === String(r.teamId))?.name ||
        (r.teamId === "__unassigned__"
          ? teamsSettingsNorm.unassignedLabel || "Unassigned"
          : "Team"),
      color: teams.find((t) => String(t.id) === String(r.teamId))?.color || "#94A3B8",
    }));
  }, [
    matches,
    currentOpSession?.startedAt,
    settings?.teamsModeEnabled,
    teams,
    teamsSettingsNorm,
  ]);

  const selectedCourt = findCourtById(courts, openCourtId);
  const selectedMatch =
    selectedCourt?.currentMatchId != null
      ? matches.find((m) => playerIdKey(m.id) === playerIdKey(selectedCourt.currentMatchId))
      : null;
  const selectedSides = selectedMatch ? resolveMatchSidesForDisplay(selectedMatch) : null;
  const courtTeamMeta =
    selectedMatch?.teamMeta && typeof selectedMatch.teamMeta === "object"
      ? selectedMatch.teamMeta
      : null;
  const onCourt = selectedCourt ? getPlayersOnCourt(selectedCourt, players) : [];
  const selectedPlayers = onCourt.map((p) => ({
    ...p,
    team: selectedSides?.green?.players?.some((id) => playerIdKey(id) === playerIdKey(p.id))
      ? "green"
      : selectedSides?.blue?.players?.some((id) => playerIdKey(id) === playerIdKey(p.id))
        ? "blue"
        : listHasPlayerId(selectedCourt?.teamGreen, p.id)
          ? "green"
          : listHasPlayerId(selectedCourt?.teamBlue, p.id)
            ? "blue"
            : null,
  }));

  const sharedViewProps = {
    courts,
    players,
    matchQueue,
    matches,
    settings,
    teams,
    teamsSettings: teamsSettingsNorm,
    sessionTopTeams,
  };

  const isNormalView = activeView === "normal";

  return (
    <div
      className={`h-full overflow-hidden flex flex-col font-body ${isNormalView ? "p-2" : "p-4"}`}
      style={{ background: "linear-gradient(160deg, #040B14 0%, #061525 45%, #0B1F3A 100%)" }}
    >
      <header
        className={`flex items-center justify-between px-1 gap-3 shrink-0 ${
          isNormalView ? "mb-2" : "mb-5 px-2"
        }`}
      >
        <div className="flex items-center gap-3 min-w-0">
          <div className="relative shrink-0">
            <img
              src={config.assetPath("logo.png")}
              alt={config.name}
              className={`object-cover rounded-full shadow-lg border-2 border-white/40 ${
                isNormalView ? "h-14 w-14 md:h-16 md:w-16" : "h-20 w-20 md:h-24 md:w-24"
              }`}
            />
            <div className="absolute inset-0 rounded-full ring-2 ring-[#1A4B8C]/35 ring-offset-2 ring-offset-transparent pointer-events-none" />
          </div>
          <div className="flex flex-col leading-none min-w-0">
            <span
              className={`!text-white font-display font-extrabold italic leading-[1.1] tracking-wide truncate max-w-[48vw] ${
                isNormalView
                  ? "text-[clamp(1rem,2.2vw,1.75rem)]"
                  : "text-[clamp(1.25rem,3vw,2.35rem)]"
              }`}
            >
              {config.name}
            </span>
            <span className="text-[10px] text-white/55 uppercase tracking-[0.28em] mt-1 font-body font-medium not-italic">
              {config.tagline || "Pickleball Facility"}
            </span>
          </div>
        </div>
        <LiveClock compact={isNormalView} />
      </header>

      <div
        className={`h-px bg-gradient-to-r from-transparent via-[#1A4B8C]/50 to-transparent mx-1 shrink-0 ${
          isNormalView ? "mb-2" : "mb-5 mx-2"
        }`}
      />

      <div className="flex-1 min-h-0 overflow-hidden">
        {activeView === "normal" && <NormalView {...sharedViewProps} />}
        {activeView === "leaderboard" && (
          <div className="h-full min-h-0">
            <LeaderboardPodiumView {...sharedViewProps} />
          </div>
        )}
        {activeView === "nextUp" && (
          <div className="h-full min-h-0">
            <NextUpView
              matchQueue={matchQueue}
              players={players}
              settings={settings}
              teams={teams}
              teamsSettings={teamsSettingsNorm}
            />
          </div>
        )}
        {activeView === "sponsor" && (
          <div className="h-full min-h-0">
            <SponsorView imageUrl={activeSponsorUrl} />
          </div>
        )}
      </div>

      {!isNormalView && (
        <footer className="mt-3 text-center text-[10px] text-white/25 uppercase tracking-widest shrink-0">
          Powered by Dink Manager
        </footer>
      )}

      {openCourtId && selectedCourt && (
        <PlayersModal
          open
          onClose={closeDisplayModal}
          courtName={selectedCourt.name || `Court ${selectedCourt.id}`}
          players={selectedPlayers}
          variant="display"
          teamsModeEnabled={settings?.teamsModeEnabled}
          teams={teams}
          teamsSettings={teamsSettingsNorm}
          courtTeamMeta={courtTeamMeta}
        />
      )}
    </div>
  );
}
