/**
 * Teams-mode match generation: two players from team A vs two from team B.
 * Does not import autoQueue.js (avoid circular deps when autoQueue imports this module).
 */

import { DEFAULT_TEAMS_SETTINGS, normalizeTeamsSettings, UNASSIGNED_TEAM_ID } from "../../../state/teamSettings";

const MIN_WAIT_FOR_PRIORITY = 13;
const MAX_THEORETICAL_SCORE = 107;
const MAX_GROUP_SIZE = 4;
const MAX_LATE_HANDICAP = 3;
const MATCH_INTERVAL_MS = 20 * 60 * 1000;

const LEVEL_RANK = {
  Newbie: 0,
  Beginner: 1,
  "L.Inter": 2,
  "H.Inter": 3,
  Advance: 4,
  "Low Intermediate": 2,
  "High Intermediate": 3,
};

const toId = (v) => String(v);
const normalizeStatuses = (status) => String(status || "").toLowerCase().trim();
const rank = (lvl) => LEVEL_RANK[lvl] ?? 2;
const byTimeAsc = (a, b) => (a.startTime ?? 0) - (b.startTime ?? 0);
const variance = (nums = []) => {
  if (!nums.length) return 0;
  const mean = nums.reduce((s, n) => s + n, 0) / nums.length;
  return nums.reduce((s, n) => s + (n - mean) ** 2, 0) / nums.length;
};

const pairPenalty = (matchesAgo) => {
  if (matchesAgo == null) return 0;
  if (matchesAgo === 0) return 100;
  if (matchesAgo === 1) return 70;
  if (matchesAgo === 2) return 40;
  if (matchesAgo === 3) return 20;
  return 0;
};

const buildPairMatrix = (pastMatches = []) => {
  const matrix = {};
  const ordered = [...pastMatches]
    .filter((match) => match?.status === "completed")
    .sort(byTimeAsc)
    .reverse();
  ordered.forEach((match, idx) => {
    const ids = (match?.lineup || []).map((p) => toId(p.id)).filter(Boolean);
    for (let i = 0; i < ids.length - 1; i += 1) {
      for (let j = i + 1; j < ids.length; j += 1) {
        const a = ids[i];
        const b = ids[j];
        if (!matrix[a]) matrix[a] = {};
        if (!matrix[b]) matrix[b] = {};
        if (matrix[a][b] == null || idx < matrix[a][b]) {
          matrix[a][b] = idx;
          matrix[b][a] = idx;
        }
      }
    }
  });
  return matrix;
};

const buildPairEncounterCounts = (matches = []) => {
  const counts = {};
  matches.forEach((match) => {
    if (!match || match.status !== "completed") return;
    const ids = (match?.lineup || []).map((p) => toId(p.id)).filter(Boolean);
    for (let i = 0; i < ids.length - 1; i += 1) {
      for (let j = i + 1; j < ids.length; j += 1) {
        const a = ids[i];
        const b = ids[j];
        if (!counts[a]) counts[a] = {};
        if (!counts[b]) counts[b] = {};
        counts[a][b] = (counts[a][b] || 0) + 1;
        counts[b][a] = (counts[b][a] || 0) + 1;
      }
    }
  });
  return counts;
};

function combinations2(list) {
  const out = [];
  for (let i = 0; i < list.length - 1; i += 1) {
    for (let j = i + 1; j < list.length; j += 1) {
      out.push([list[i], list[j]]);
    }
  }
  return out;
}

function shuffle(list) {
  const arr = [...list];
  for (let i = arr.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function resolveTeamPresentation(teamId, teamsList, labelFallback) {
  if (teamId === UNASSIGNED_TEAM_ID) {
    return {
      teamId: UNASSIGNED_TEAM_ID,
      name: labelFallback || "Unassigned",
      color: "#64748B",
      letter: "U",
    };
  }
  const t = (teamsList || []).find((x) => String(x.id) === String(teamId));
  return {
    teamId: String(teamId),
    name: t?.name || "Team",
    color: t?.color || "#3B82F6",
    letter: t?.letter || "?",
  };
}

function buildTeamsChecks(ctx) {
  const {
    genderOk,
    levelOk,
    repeatCheck,
    pairSoftNote,
    hasPriorityInPool,
    hasPriorityInGroup,
    fairnessValues,
    levelSpread,
    teamsRepeatNote,
  } = ctx;

  return [
    {
      id: "level",
      label: "Level (teams)",
      status: levelOk ? "pass" : "fail",
      reason: levelOk
        ? "Level rules satisfied for both sides."
        : `Level layout rejected (spread/balance ${levelSpread}).`,
    },
    {
      id: "gender",
      label: "Gender composition",
      status: genderOk ? "pass" : "fail",
      reason: genderOk
        ? "Valid composition (4M, 4F, or 2M+2F)."
        : "Composition must be 4M, 4F, or 2M+2F.",
    },
    {
      id: "repeat",
      label: "Repeat history",
      status: repeatCheck.ok ? "pass" : "fail",
      reason: repeatCheck.reason,
      ...(repeatCheck.violatingPlayers?.length ? { violatingPlayers: repeatCheck.violatingPlayers } : {}),
    },
    {
      id: "pairs",
      label: "Pair rotation (soft)",
      status: "pass",
      reason: pairSoftNote || "Pair overlap scored softly (no hard block).",
    },
    {
      id: "teams_settings",
      label: "Team settings",
      status: "pass",
      reason: teamsRepeatNote || "Session repeat rules per Team Settings.",
    },
    {
      id: "priority",
      label: "Priority waiting",
      status: hasPriorityInPool && !hasPriorityInGroup ? "fail" : "pass",
      reason: hasPriorityInPool
        ? hasPriorityInGroup
          ? "A priority waiter (13m+) is included."
          : "Priority waiter exists but was not included."
        : "No priority waiters in pool.",
    },
    {
      id: "fairness",
      label: "Fairness",
      status: "pass",
      reason: `Effective matches: ${fairnessValues.join(", ")}.`,
    },
  ];
}

export function buildTeamsAutoQueue(
  players,
  {
    pastMatches = [],
    excludeIds = [],
    sessionStartTime = null,
    sessionMatchIds = new Set(),
    excludeGroups = [],
    teams: teamsList = [],
    teamsSettings: rawTeamsSettings,
  } = {}
) {
  const teamsSettings = normalizeTeamsSettings(rawTeamsSettings ?? DEFAULT_TEAMS_SETTINGS);
  const rotationMult = teamsSettings.pairRotationStrength === "strong" ? 1.35 : 1;
  const enforceThree = teamsSettings.enforceSessionRepeatThreePlayer !== false;
  const enforceFour = teamsSettings.enforceSessionRepeatFourExact !== false;
  const levelMode = teamsSettings.levelMode === "strict" ? "strict" : "balanced";

  const now = Date.now();
  const diagnostics = {
    total: players.length,
    notWaiting: 0,
    excluded: 0,
    partnerBusy: 0,
    ok: 0,
    totalCombinationsChecked: 0,
    validCombinationsFound: 0,
    teamsMode: true,
  };

  const excludeSet = new Set((excludeIds || []).map(toId));
  const excludeGroupSet = new Set((excludeGroups || []).map((ids) => ids.map(toId).sort().join("|")));

  const arrivals = players
    .map((p) => p.arrivalTime)
    .filter((value) => typeof value === "number" && value > 0);
  const derivedSessionStart = arrivals.length ? Math.min(...arrivals) : now;
  const sessionStart = sessionStartTime ?? derivedSessionStart;

  const pool = players
    .filter((p) => {
      if (normalizeStatuses(p.status) !== "waiting") {
        diagnostics.notWaiting += 1;
        return false;
      }
      if (excludeSet.has(toId(p.id))) {
        diagnostics.excluded += 1;
        return false;
      }
      diagnostics.ok += 1;
      return true;
    })
    .map((p) => {
      const wait = p.waitStart ? Math.max(0, Math.floor((now - p.waitStart) / 60000)) : 0;
      const lateHandicap =
        typeof p.arrivalTime === "number" && p.arrivalTime > 0
          ? Math.min(
              MAX_LATE_HANDICAP,
              Math.max(0, Math.floor((p.arrivalTime - sessionStart) / MATCH_INTERVAL_MS))
            )
          : 0;
      const matches = p.matches ?? 0;
      return {
        ...p,
        _teamKey: p.teamId ? String(p.teamId) : UNASSIGNED_TEAM_ID,
        _wait: wait,
        _matches: matches,
        _lateHandicap: lateHandicap,
        _effectiveMatches: matches + lateHandicap,
      };
    });

  if (pool.length < MAX_GROUP_SIZE) {
    return {
      success: false,
      mode: "teams",
      groupIds: [],
      usedPlayers: [],
      teamMeta: null,
      confidencePct: 0,
      checks: [
        {
          id: "pool_size",
          label: "Enough players waiting",
          status: "fail",
          reason: `Only ${pool.length} eligible player(s) — need 4.`,
        },
      ],
      pairWarnings: [],
      reason: `Not enough players (${pool.length} of 4 needed)`,
      diagnostics,
    };
  }

  const byTeam = new Map();
  pool.forEach((p) => {
    const k = p._teamKey;
    if (!byTeam.has(k)) byTeam.set(k, []);
    byTeam.get(k).push(p);
  });

  const eligibleTeamKeys = shuffle(
    [...byTeam.keys()].filter((k) => byTeam.get(k).length >= 2)
  );

  const pairMatrix = buildPairMatrix(pastMatches);
  const pairEncounterCounts = buildPairEncounterCounts(pastMatches.filter((m) => m?.status === "completed"));
  const completedMatches = pastMatches.filter((match) => match?.status === "completed");
  const teamUsage = new Map();
  completedMatches.forEach((match) => {
    const sideAId = match?.teamMeta?.sideA?.teamId;
    const sideBId = match?.teamMeta?.sideB?.teamId;
    if (sideAId != null) {
      const key = String(sideAId);
      teamUsage.set(key, (teamUsage.get(key) || 0) + 1);
    }
    if (sideBId != null) {
      const key = String(sideBId);
      teamUsage.set(key, (teamUsage.get(key) || 0) + 1);
    }
  });
  const maxTeamUsage = teamUsage.size
    ? Math.max(...Array.from(teamUsage.values()))
    : 0;

  const combos = [];
  for (let i = 0; i < eligibleTeamKeys.length; i += 1) {
    for (let j = i + 1; j < eligibleTeamKeys.length; j += 1) {
      const tkLo = eligibleTeamKeys[i];
      const tkHi = eligibleTeamKeys[j];
      const listLo = byTeam.get(tkLo);
      const listHi = byTeam.get(tkHi);
      const pairsLo = combinations2(listLo);
      const pairsHi = combinations2(listHi);
      pairsLo.forEach((a) => {
        pairsHi.forEach((b) => {
          const group = [...a, ...b];
          const key = group.map((p) => toId(p.id)).sort().join("|");
          if (!excludeGroupSet.has(key)) combos.push({ group, tkLo, tkHi, sideA: a, sideB: b });
        });
      });
    }
  }

  if (!combos.length) {
    return {
      success: false,
      mode: "teams",
      groupIds: [],
      usedPlayers: [],
      teamMeta: null,
      confidencePct: 0,
      checks: [
        {
          id: "no_combos",
          label: "Team combinations",
          status: "fail",
          reason: "Need at least two teams with 2+ waiting players each.",
        },
      ],
      pairWarnings: [],
      reason: "No team-vs-team combinations available.",
      diagnostics,
    };
  }

  let bestValid = null;
  let bestAttempt = null;
  const hasPriorityInPool = pool.some((p) => p._wait >= MIN_WAIT_FOR_PRIORITY);
  const validComparator = (a, b) => {
    if (a.maxWait !== b.maxWait) return a.maxWait > b.maxWait;
    if (a.sumWait !== b.sumWait) return a.sumWait > b.sumWait;
    if (a.priorityCount !== b.priorityCount) return a.priorityCount > b.priorityCount;
    if (a.avgTeamUsage !== b.avgTeamUsage) return a.avgTeamUsage < b.avgTeamUsage;
    if (a.maxEffective !== b.maxEffective) return a.maxEffective < b.maxEffective;
    if (a.sumEffective !== b.sumEffective) return a.sumEffective < b.sumEffective;
    if (a.totalScore !== b.totalScore) return a.totalScore > b.totalScore;
    return Math.random() > 0.5;
  };

  const teamsRepeatNote = `Session repeats: 3-player ${enforceThree ? "ON" : "OFF"}, exact-4 ${enforceFour ? "ON" : "OFF"}.`;

  combos.forEach(({ group, tkLo, tkHi, sideA, sideB }) => {
    diagnostics.totalCombinationsChecked += 1;
    const ids = group.map((p) => toId(p.id));
    const namesById = new Map(group.map((p) => [toId(p.id), p.name]));

    const men = group.filter((p) => p.gender === "M").length;
    const women = group.filter((p) => p.gender === "F").length;
    const genderOk = (men === 4 && women === 0) || (men === 0 && women === 4) || (men === 2 && women === 2);

    const ranksA = sideA.map((p) => rank(p.level));
    const ranksB = sideB.map((p) => rank(p.level));
    const spreadA = Math.max(...ranksA) - Math.min(...ranksA);
    const spreadB = Math.max(...ranksB) - Math.min(...ranksB);
    const sumA = ranksA.reduce((s, n) => s + n, 0);
    const sumB = ranksB.reduce((s, n) => s + n, 0);
    const levelSpread =
      levelMode === "strict" ? Math.max(spreadA, spreadB) : Math.abs(sumA - sumB);
    const levelOk =
      levelMode === "strict"
        ? spreadA <= 1 && spreadB <= 1
        : Math.abs(sumA - sumB) <= 1;

    let repeatCheck = { ok: true, reason: "No hard repeat conflicts." };
    for (const match of completedMatches) {
      const matchIds = new Set((match?.lineup || []).map((p) => toId(p.id)));
      const overlapping = ids.filter((id) => matchIds.has(id));
      if (enforceFour && sessionMatchIds?.has?.(match.id) && overlapping.length >= 4) {
        const violators = overlapping.map((id) => namesById.get(id) || id);
        repeatCheck = {
          ok: false,
          reason: `Exact 4-player repeat in this session: ${violators.join(", ")}.`,
          violatingPlayers: violators,
        };
        break;
      }
      if (enforceThree && sessionMatchIds?.has?.(match.id) && overlapping.length >= 3) {
        const violators = overlapping.map((id) => namesById.get(id) || id);
        repeatCheck = {
          ok: false,
          reason: `Same-session 3-player overlap: ${violators.join(", ")}.`,
          violatingPlayers: violators,
        };
        break;
      }
    }

    const pairWarnings = [];
    const pairEncounters = [];
    for (let i = 0; i < ids.length - 1; i += 1) {
      for (let j = i + 1; j < ids.length; j += 1) {
        const idA = ids[i];
        const idB = ids[j];
        const encounterCount = pairEncounterCounts[idA]?.[idB] || 0;
        if (encounterCount > 0) {
          pairEncounters.push({
            idA,
            idB,
            nameA: namesById.get(idA) || idA,
            nameB: namesById.get(idB) || idB,
            encounterCount,
          });
        }
        const ago = pairMatrix[idA]?.[idB];
        if (ago == null) continue;
        const penalty = pairPenalty(ago) * rotationMult;
        pairWarnings.push({
          idA,
          idB,
          nameA: namesById.get(idA) || idA,
          nameB: namesById.get(idB) || idB,
          encounterCount,
          matchesAgo: ago,
          penalty,
        });
      }
    }

    const fairnessValues = group.map((p) => p._effectiveMatches);
    const fairnessScore = 1 / (1 + variance(fairnessValues));
    const rawWaitScore = Math.min(group.reduce((sum, p) => sum + p._wait, 0) / 60, 1);
    const hasPriorityInGroup = group.some((p) => p._wait >= MIN_WAIT_FOR_PRIORITY);
    const longWaitBonus = hasPriorityInGroup ? 0.3 : 0;
    const longWaitPenalty = hasPriorityInPool && !hasPriorityInGroup ? -0.5 : 0;
    const waitScore = rawWaitScore + longWaitBonus + longWaitPenalty;
    const pairPenaltySum = pairWarnings.reduce((sum, w) => sum + w.penalty, 0);
    const pairDiversityScore = Math.max(0, (600 - pairPenaltySum) / 600);
    const teamUsageA = teamUsage.get(String(tkLo)) || 0;
    const teamUsageB = teamUsage.get(String(tkHi)) || 0;
    const avgTeamUsage = (teamUsageA + teamUsageB) / 2;
    const teamDiversityScore =
      maxTeamUsage > 0
        ? Math.max(0, (maxTeamUsage - avgTeamUsage) / (maxTeamUsage + 1))
        : 1;
    const levelScore =
      levelMode === "strict"
        ? Math.max(0, (2 - Math.max(spreadA, spreadB)) / 2)
        : Math.max(0, (2 - Math.abs(sumA - sumB)) / 2);
    const totalScore =
      fairnessScore * 27 +
      waitScore * 25 +
      pairDiversityScore * 30 +
      levelScore * 8 +
      teamDiversityScore * 10;
    const priorityCount = group.filter((p) => p._wait >= MIN_WAIT_FOR_PRIORITY).length;
    const maxWait = Math.max(...group.map((p) => p._wait));
    const sumWait = group.reduce((sum, p) => sum + p._wait, 0);

    const metaA = resolveTeamPresentation(tkLo, teamsList, teamsSettings.unassignedLabel);
    const metaB = resolveTeamPresentation(tkHi, teamsList, teamsSettings.unassignedLabel);
    const teamMeta = {
      sideA: {
        ...metaA,
        players: sideA.map((p) => p.id),
      },
      sideB: {
        ...metaB,
        players: sideB.map((p) => p.id),
      },
    };

    const pairSoftNote =
      pairWarnings.length > 0
        ? `${pairWarnings.length} pair overlap signal(s) (soft scoring).`
        : "No recent pair overlap penalty.";

    const checks = buildTeamsChecks({
      genderOk,
      levelOk,
      repeatCheck,
      pairSoftNote,
      hasPriorityInPool,
      hasPriorityInGroup,
      fairnessValues,
      levelSpread,
      teamsRepeatNote,
    });

    const isValid = genderOk && levelOk && repeatCheck.ok;
    const candidate = {
      success: isValid,
      mode: "teams",
      groupIds: group.map((p) => p.id),
      usedPlayers: group,
      teamMeta,
      confidencePct: isValid ? Math.round(Math.min(100, (totalScore / MAX_THEORETICAL_SCORE) * 100)) : 0,
      checks,
      pairWarnings,
      reason: "",
      diagnostics: { ...diagnostics },
      totalScore,
      maxEffective: Math.max(...fairnessValues),
      sumEffective: fairnessValues.reduce((a, b) => a + b, 0),
      avgTeamUsage,
      priorityCount,
      maxWait,
      sumWait,
      teamsSettingsSnapshot: teamsSettings,
    };

    if (isValid) {
      diagnostics.validCombinationsFound += 1;
      if (!bestValid || validComparator(candidate, bestValid)) bestValid = candidate;
      return;
    }
    const failedChecksCount = checks.filter((check) => check.status === "fail").length;
    candidate.failedChecksCount = failedChecksCount;
    if (
      !bestAttempt ||
      candidate.failedChecksCount < bestAttempt.failedChecksCount ||
      (candidate.failedChecksCount === bestAttempt.failedChecksCount &&
        candidate.totalScore > bestAttempt.totalScore)
    ) {
      bestAttempt = candidate;
    }
  });

  if (bestValid) {
    return {
      success: true,
      mode: "teams",
      groupIds: bestValid.groupIds,
      usedPlayers: bestValid.usedPlayers,
      teamMeta: bestValid.teamMeta,
      confidencePct: bestValid.confidencePct,
      checks: bestValid.checks,
      pairWarnings: bestValid.pairWarnings,
      reason: `Team match found after checking ${diagnostics.totalCombinationsChecked} combinations.`,
      diagnostics,
      teamsSettingsSnapshot: bestValid.teamsSettingsSnapshot,
    };
  }

  if (bestAttempt) {
    return {
      success: false,
      mode: "teams",
      groupIds: bestAttempt.groupIds,
      usedPlayers: bestAttempt.usedPlayers,
      teamMeta: bestAttempt.teamMeta,
      confidencePct: 0,
      checks: bestAttempt.checks,
      pairWarnings: bestAttempt.pairWarnings,
      reason: `No clean team match after checking ${diagnostics.totalCombinationsChecked} combinations.`,
      diagnostics,
      teamsSettingsSnapshot: bestAttempt.teamsSettingsSnapshot,
    };
  }

  return {
    success: false,
    mode: "teams",
    groupIds: [],
    usedPlayers: [],
    teamMeta: null,
    confidencePct: 0,
    checks: [
      {
        id: "no_combos",
        label: "Combination search",
        status: "fail",
        reason: "No combinations available.",
      },
    ],
    pairWarnings: [],
    reason: "No combinations available.",
    diagnostics,
  };
}
