import React, { useMemo, useState } from "react";
import { PlayerTable } from "./index";
import PlayerManagementOverlay from "./components/PlayerManagementOverlay";
import ReclubModal from "./components/ReclubModal";
import { useAppState } from "../../app/providers";
import { DEFAULT_OPEN_PLAY_FEE } from "../../common/utils/settingsDefaults";
import { selectQueueState } from "../../state/selectors";
import {
  getRecentHeldPlayerIdSet,
  getRecentUnscoredMatches,
  recentHoldViews,
} from "./utils/recentPool";

/**
 * Standalone Manage Players window (#/manage).
 * Shares state with the main Queue tab via BroadcastChannel + localStorage sync.
 */
export default function ManagePlayersPage() {
  const [manageTab, setManageTab] = useState("players");
  const [reclubOpen, setReclubOpen] = useState(false);

  const {
    courts,
    players,
    matches,
    matchQueue,
    currentOpSession,
    settings,
    teams,
    partners,
    requestedMatches,
    recentHold,
    addPlayer,
    updateGender,
    removePlayer,
    clearAllPlayers,
    stopPlayer,
    departPlayer,
    resumePlayer,
    updateLevel,
    renamePlayer,
    addToQueue,
    updatePaymentStatus,
    updateMemberStatus,
    markPlayerArrived,
    markAllPaid,
    markAllArrived,
    completeMatch,
    clearQueue,
    closeOpSession,
    updateMatchDetails,
    assignPlayerToTeam,
    removePlayerFromTeam,
    updateTeam,
    removeTeam,
    setTeams,
    setTeamsModeEnabled,
    updateTeamsSettings,
    importReclubParticipants,
  } = useAppState(selectQueueState);

  const duplicateNames = useMemo(() => {
    const counts = {};
    const dups = [];
    players.forEach((p) => {
      const name = String(p.name || "").toUpperCase();
      counts[name] = (counts[name] || 0) + 1;
      if (counts[name] === 2) dups.push(name);
    });
    return dups;
  }, [players]);

  const { dismissedRecentMatchIds, releasedByMatch } = useMemo(
    () => recentHoldViews(recentHold),
    [recentHold]
  );

  const recentHeldPlayerIds = useMemo(() => {
    const groups = getRecentUnscoredMatches({
      matches,
      players,
      dismissedRecentMatchIds,
      releasedByMatch,
    });
    return getRecentHeldPlayerIdSet({ recentGroups: groups });
  }, [matches, players, dismissedRecentMatchIds, releasedByMatch]);

  const handleAddToQueue = (playerId, partnerId = null) => {
    if (recentHeldPlayerIds.has(String(playerId))) return;
    addToQueue(playerId, partnerId);
  };

  return (
    <div className="h-screen overflow-hidden bg-slate-100">
      <PlayerManagementOverlay
        isOpen
        onClose={() => {
          if (typeof window !== "undefined") window.close();
        }}
        courts={courts}
        players={players}
        onCompleteMatch={completeMatch}
        popoutMode
      >
        <PlayerTable
          players={players}
          matches={matches}
          currentOpSession={currentOpSession}
          onAddPlayer={addPlayer}
          onRemovePlayer={removePlayer}
          onClearAll={clearAllPlayers}
          onSaveSessionAndClear={() => {
            if (currentOpSession) closeOpSession();
            clearQueue();
            clearAllPlayers();
          }}
          onUpdateLevel={updateLevel}
          onStopPlayer={stopPlayer}
          onDepartPlayer={departPlayer}
          onResumePlayer={resumePlayer}
          onUpdateGender={updateGender}
          onUpdatePaymentStatus={updatePaymentStatus}
          onUpdateMemberStatus={updateMemberStatus}
          onMarkArrived={markPlayerArrived}
          onMarkAllPaid={markAllPaid}
          onMarkAllArrived={markAllArrived}
          disabled={!currentOpSession}
          matchQueue={matchQueue}
          onAddToQueue={handleAddToQueue}
          onRenamePlayer={renamePlayer}
          onOpenReclub={() => setReclubOpen(true)}
          onUpdateMatch={updateMatchDetails}
          duplicateNames={duplicateNames}
          requestedMatches={requestedMatches}
          partners={partners}
          teamsModeEnabled={settings?.teamsModeEnabled}
          teams={teams}
          settings={settings}
          setTeamsModeEnabled={setTeamsModeEnabled}
          updateTeamsSettings={updateTeamsSettings}
          setTeams={setTeams}
          assignPlayerToTeam={assignPlayerToTeam}
          removePlayerFromTeam={removePlayerFromTeam}
          removeTeam={removeTeam}
          updateTeam={updateTeam}
          initialTab={manageTab}
          recentHeldPlayerIds={recentHeldPlayerIds}
          defaultOpFee={settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE}
        />
      </PlayerManagementOverlay>

      <ReclubModal
        open={reclubOpen}
        onClose={() => setReclubOpen(false)}
        onImportParticipants={(payload) => {
          importReclubParticipants(payload);
          setReclubOpen(false);
          setManageTab("payments");
        }}
      />
    </div>
  );
}
