import React, { useCallback, useEffect, useMemo, useState } from "react";
import { ExternalLink, X } from "lucide-react";
import { getPlayersOnCourt } from "../../../state/courtPlayers";

const formatDuration = (ms) => {
  if (!ms || ms <= 0) return "00:00";
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, "0");
  const seconds = (totalSeconds % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
};

function LiveCourtChip({ court, players, onCompleteMatch }) {
  const timer = useMemo(() => court?.timer || {}, [court?.timer]);
  const computeElapsedMs = useCallback(() => {
    const { startTime, lastResumedAt, accumulatedMs = 0, isPaused } = timer;
    if (!startTime) return 0;
    if (!isPaused && lastResumedAt) {
      return accumulatedMs + Math.max(0, Date.now() - lastResumedAt);
    }
    if (!isPaused && !lastResumedAt) {
      return Math.max(0, Date.now() - startTime);
    }
    return accumulatedMs;
  }, [timer]);

  const [elapsedMs, setElapsedMs] = useState(() => computeElapsedMs());
  useEffect(() => {
    setElapsedMs(computeElapsedMs());
    if (!timer.startTime || timer.isPaused) return undefined;
    const id = setInterval(() => setElapsedMs(computeElapsedMs()), 1000);
    return () => clearInterval(id);
  }, [computeElapsedMs, timer.isPaused, timer.startTime]);

  const onCourt = useMemo(() => getPlayersOnCourt(court, players), [court, players]);
  const hasPlayers = onCourt.length > 0;

  return (
    <div className="shrink-0 min-w-[160px] max-w-[220px] rounded-lg border border-pt-teal/20 bg-white px-2.5 py-1.5 flex flex-col gap-1">
      <div className="flex items-center justify-between gap-2">
        <span className="text-[11px] font-bold text-pt-teal truncate">{court.name}</span>
        <span className="text-[10px] font-mono text-slate-500">{formatDuration(elapsedMs)}</span>
      </div>
      <div className="text-[9px] text-slate-500 truncate">
        {hasPlayers ? onCourt.map((p) => p.name).join(" · ") : "Empty"}
      </div>
      {hasPlayers && (
        <button
          type="button"
          onClick={() => onCompleteMatch?.(court.id)}
          className="text-[9px] font-bold uppercase tracking-wide text-red-600 hover:bg-red-50 rounded px-1 py-0.5 self-start"
        >
          End Game
        </button>
      )}
    </div>
  );
}

function openManagePopout() {
  const base = window.location.href.split("#")[0];
  const win = window.open(`${base}#/manage`, "dink_manage", "width=1100,height=800");
  if (!win) {
    // eslint-disable-next-line no-alert
    window.alert("Pop-up blocked — allow pop-ups for this site to open Manage in a new window.");
  }
  return win;
}

export { openManagePopout };

export default function PlayerManagementOverlay({
  isOpen,
  onClose,
  courts = [],
  players = [],
  onCompleteMatch,
  children,
  popoutMode = false,
}) {
  if (!isOpen) return null;

  return (
    <div
      className={`${
        popoutMode ? "h-screen overflow-hidden" : "fixed inset-0 z-[60]"
      } flex flex-col bg-black/40 backdrop-blur-sm`}
    >
      <div className="shrink-0 bg-slate-900/95 border-b border-pt-teal/30 px-3 py-2">
        <div className="flex items-center justify-between gap-3 mb-2">
          <div className="flex items-center gap-3 min-w-0">
            <div className="text-sm font-bold uppercase tracking-widest text-white">
              Manage Players
            </div>
            <div className="text-[10px] font-bold uppercase tracking-widest text-pt-teal/80 hidden sm:block">
              Live Courts
            </div>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {!popoutMode && (
              <button
                type="button"
                onClick={() => {
                  openManagePopout();
                  onClose?.();
                }}
                className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold bg-white/15 text-white hover:bg-white/25 focus:outline-none focus-visible:ring-1 focus-visible:ring-white/40 shadow-sm"
                title="Open Manage Players in a separate window"
              >
                <ExternalLink className="h-3.5 w-3.5" />
                Open in new window
              </button>
            )}
            <button
              type="button"
              onClick={onClose}
              className="inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium bg-white/10 text-white hover:bg-white/20"
            >
              <X className="h-3.5 w-3.5" />
              {popoutMode ? "Close window" : "Close"}
            </button>
          </div>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 custom-scrollbar">
          {courts.length === 0 ? (
            <div className="text-xs text-white/50 italic py-2">No courts</div>
          ) : (
            courts.map((c) => (
              <LiveCourtChip
                key={c.id}
                court={c}
                players={players}
                onCompleteMatch={onCompleteMatch}
              />
            ))
          )}
        </div>
      </div>

      <div
        className={`flex-1 min-h-0 bg-white ${
          popoutMode ? "m-0 rounded-none" : "m-2 mt-0 rounded-xl"
        } shadow-2xl border border-pt-teal/10 overflow-hidden flex flex-col`}
      >
        <div className="flex-1 min-h-0 overflow-hidden p-3">{children}</div>
      </div>
    </div>
  );
}
