import React, { useMemo, useState } from "react";
import { ChevronLeft, ChevronRight, Maximize2, Rocket } from "lucide-react";
import TeamBadge, { resolveTeamBadgeDisplay } from "./TeamBadge";
import QueueExpandModal from "./QueueExpandModal";

const LEVEL_COLORS = {
  Newbie: "#94A3B8",
  Beginner: "#F59E0B",
  "L.Inter": "#22C55E",
  "H.Inter": "#3B82F6",
  Advance: "#8B5CF6",
};

const LEVEL_LETTERS = {
  Newbie: "N",
  Beginner: "B",
  "L.Inter": "L",
  "H.Inter": "H",
  Advance: "A",
};

function QueueMatchCard({
  item,
  index,
  players,
  courts,
  isNext,
  teamsModeEnabled,
  teams,
  teamsSettings,
  onSendQueueToCourt,
  onRemoveQueue,
  onRemoveFromQueue,
  onReorder,
  disabled,
}) {
  const team = (Array.isArray(item.playerIds) ? item.playerIds : [])
    .map((id) => players.find((p) => p.id === id))
    .filter(Boolean);

  const courtChoices = useMemo(
    () =>
      courts.map((c) => ({
        id: c.id,
        name: c.name,
        free: 4 - (c.players?.length || 0),
        locked: !!c.locked,
      })),
    [courts]
  );

  return (
    <div
      className={`shrink-0 rounded-xl border p-2.5 bg-white shadow-sm flex flex-col gap-2 h-full min-h-0 overflow-hidden ${
        isNext ? "w-[280px] border-pt-teal/40 ring-1 ring-pt-teal/20" : "w-[220px] border-slate-200"
      }`}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-1.5">
          <span
            className={`w-5 h-5 rounded-md text-[10px] font-black inline-flex items-center justify-center ${
              isNext ? "bg-pt-teal text-white" : "bg-emerald-100 text-emerald-800"
            }`}
          >
            {index + 1}
          </span>
          <span className={`text-[10px] font-bold uppercase tracking-wide ${isNext ? "text-pt-teal" : "text-slate-500"}`}>
            {isNext ? "Next Game" : `Queue ${index + 1}`}
          </span>
        </div>
        {!disabled && !isNext && (
          <div className="flex items-center gap-0.5">
            <button
              type="button"
              className="p-0.5 rounded hover:bg-slate-100 text-slate-400 disabled:opacity-30"
              disabled={index <= 1}
              onClick={() => onReorder?.(item.id, "left")}
              title="Move earlier"
            >
              <ChevronLeft className="h-3.5 w-3.5" />
            </button>
            <button
              type="button"
              className="p-0.5 rounded hover:bg-slate-100 text-slate-400"
              onClick={() => onReorder?.(item.id, "right")}
              title="Move later"
            >
              <ChevronRight className="h-3.5 w-3.5" />
            </button>
          </div>
        )}
      </div>

      {item.reason && (
        <div className="text-[9px] text-slate-400 italic truncate">{item.reason}</div>
      )}

      <ul className="grid grid-cols-2 gap-1">
        {team.map((p) => {
          const tb = resolveTeamBadgeDisplay(
            p,
            item?.teamMeta,
            teamsModeEnabled,
            teams,
            teamsSettings?.unassignedLabel
          );
          return (
            <li
              key={p.id}
              className={`flex items-center gap-1 rounded-md border px-1.5 py-1 text-[10px] ${
                p.gender === "F" ? "bg-pink-50 border-pink-100" : "bg-slate-50 border-slate-100"
              }`}
            >
              {tb ? (
                <TeamBadge letter={tb.letter} color={tb.color} title={tb.title} />
              ) : (
                <span
                  className="w-3.5 h-3.5 rounded-full shrink-0 inline-flex items-center justify-center text-white font-black"
                  style={{
                    fontSize: "0.45rem",
                    backgroundColor: LEVEL_COLORS[p.level] || "#94A3B8",
                  }}
                >
                  {LEVEL_LETTERS[p.level] || "L"}
                </span>
              )}
              <span className="truncate font-medium flex-1">{p.name}</span>
              {!disabled && (
                <button
                  type="button"
                  className="text-red-400 hover:text-red-600"
                  onClick={() => onRemoveFromQueue(item.id, p.id)}
                >
                  ×
                </button>
              )}
            </li>
          );
        })}
        {Array.from({ length: Math.max(0, 4 - team.length) }).map((_, i) => (
          <li key={`e-${i}`} className="rounded-md border border-dashed border-slate-200 h-7" />
        ))}
      </ul>

      {!disabled && (
        <div className="flex items-center gap-1.5 mt-auto pt-1 border-t border-slate-50">
          {isNext && (
            <>
              <button
                type="button"
                onClick={() => onSendQueueToCourt(item.id, null)}
                className="flex-1 inline-flex items-center justify-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-pt-teal text-white hover:bg-pt-teal/90"
                title="Send to first available court"
              >
                <Rocket className="h-3 w-3" />
                Send
              </button>
              <select
                className="border border-slate-200 rounded px-1 py-1 bg-white text-[9px] max-w-[90px]"
                defaultValue=""
                onChange={(e) => {
                  const cid = Number(e.target.value);
                  if (cid) onSendQueueToCourt(item.id, cid);
                  e.target.value = "";
                }}
              >
                <option value="">Court…</option>
                {courtChoices.map((c) => (
                  <option
                    key={c.id}
                    value={c.id}
                    disabled={c.locked || c.free < (item.playerIds?.length || 0)}
                  >
                    {c.name} ({c.free})
                  </option>
                ))}
              </select>
            </>
          )}
          <button
            type="button"
            className="text-[9px] text-red-500 hover:text-red-700 underline ml-auto"
            onClick={() => onRemoveQueue(item.id)}
          >
            Remove
          </button>
        </div>
      )}
    </div>
  );
}

export default function QueueStrip({
  queue = [],
  players = [],
  courts = [],
  displayQueueVisible = true,
  onToggleDisplayQueue,
  onSendQueueToCourt,
  onRemoveQueue,
  onRemoveFromQueue,
  onReorderQueueItem,
  disabled = false,
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
}) {
  const [expandOpen, setExpandOpen] = useState(false);

  return (
    <div className="h-full min-h-0 rounded-xl border border-pt-teal/10 bg-white/80 p-2.5 flex flex-col gap-2 overflow-hidden">
      <div className="flex items-center justify-between gap-3 px-1">
        <div className="flex items-center gap-3">
          <span className="text-[10px] font-bold text-pt-teal/70 uppercase tracking-widest">
            Display Queue
          </span>
          <label className="inline-flex items-center gap-1.5 cursor-pointer select-none">
            <input
              type="checkbox"
              className="sr-only peer"
              checked={!!displayQueueVisible}
              onChange={(e) => onToggleDisplayQueue?.(e.target.checked)}
              disabled={disabled}
            />
            <span className="w-8 h-4 rounded-full bg-slate-200 peer-checked:bg-pt-teal relative transition-colors after:content-[''] after:absolute after:top-0.5 after:left-0.5 after:w-3 after:h-3 after:rounded-full after:bg-white after:transition-all peer-checked:after:translate-x-4" />
            <span className="text-[10px] text-slate-500 font-medium">
              {displayQueueVisible ? "Shown on display" : "Hidden on display"}
            </span>
          </label>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-[10px] text-slate-400 font-medium">{queue.length} match{queue.length === 1 ? "" : "es"}</span>
          {queue.length > 0 && (
            <button
              type="button"
              onClick={() => setExpandOpen(true)}
              className="p-1 rounded-md text-pt-teal/70 hover:bg-pt-teal/10 hover:text-pt-teal"
              title="Expand queue"
            >
              <Maximize2 className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
      </div>

      {!displayQueueVisible && (
        <div className="text-center text-[11px] font-semibold uppercase tracking-wider text-slate-400 py-1">
          Default message display (QUEUEING IN PROGRESS)
        </div>
      )}

      <div className="flex-1 min-h-0 overflow-x-auto overflow-y-hidden pb-1 custom-scrollbar">
        {queue.length === 0 ? (
          <div className="h-full flex items-center justify-center text-sm text-slate-400 italic border border-dashed border-slate-200 rounded-lg px-4">
            No queued matches.
          </div>
        ) : (
          <div className="h-full flex gap-2 items-stretch">
          {queue.map((item, index) => (
            <QueueMatchCard
              key={item.id}
              item={item}
              index={index}
              players={players}
              courts={courts}
              isNext={index === 0}
              teamsModeEnabled={teamsModeEnabled}
              teams={teams}
              teamsSettings={teamsSettings}
              onSendQueueToCourt={onSendQueueToCourt}
              onRemoveQueue={onRemoveQueue}
              onRemoveFromQueue={onRemoveFromQueue}
              onReorder={onReorderQueueItem}
              disabled={disabled}
            />
          ))}
          </div>
        )}
      </div>

      <QueueExpandModal
        isOpen={expandOpen}
        onClose={() => setExpandOpen(false)}
        queue={queue}
        players={players}
        courts={courts}
        teamsModeEnabled={teamsModeEnabled}
        teams={teams}
        teamsSettings={teamsSettings}
        onSendQueueToCourt={onSendQueueToCourt}
        onRemoveQueue={onRemoveQueue}
        onRemoveFromQueue={onRemoveFromQueue}
        readOnly={disabled}
      />
    </div>
  );
}
