import config from "../../config";

export const API_BASE = process.env.REACT_APP_API_URL || "";
export const FACILITY_ID = process.env.REACT_APP_FACILITY_ID || config.facilityId;

const parseJson = async (res) => {
  try {
    return await res.json();
  } catch {
    return {};
  }
};

/**
 * Throws on both transport failures and non-2xx responses. Server error codes are
 * kept on `err.code` so callers can tell "wrong password" from "server unreachable".
 */
export async function apiRequest(path, { method = "GET", body, fallbackError } = {}) {
  const res = await fetch(`${API_BASE}${path}`, {
    method,
    headers: body ? { "Content-Type": "application/json" } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await parseJson(res);
  if (!res.ok) {
    const err = new Error(data.message || data.error || fallbackError || "Request failed");
    err.code = data.error;
    err.status = res.status;
    throw err;
  }
  return data;
}
