import config from "../../config";

export const DEFAULT_OPEN_PLAY_FEE = config.pricing?.openPlayRate ?? 270;
export const DEFAULT_RENTAL_RATE = config.pricing?.rentalRate ?? 600;
export const DEFAULT_MEMBER_DISCOUNT = config.pricing?.memberDiscount ?? 0;
export const DEFAULT_PICKLECAM_FEE = config.pricing?.pickleCamFee ?? 50;
export const DEFAULT_BALL_FEE = config.pricing?.ballFee ?? 100;
export const DEFAULT_TITAN_MACHINE_FEE = config.pricing?.titanMachineFee ?? 600;
export const DEFAULT_CALENDAR_OPEN_HOUR = config.calendar?.openHour ?? 7;
export const DEFAULT_CALENDAR_CLOSE_HOUR = config.calendar?.closeHour ?? 24;
export const DEFAULT_MASTER_PASSWORD =
  config.masterPassword || "wh3pickleadmin";
export const DEFAULT_GCASH_NAME = config.pricing?.invoice?.gcashName || "";
export const DEFAULT_GCASH_NUMBER = config.pricing?.invoice?.gcashNumber || "";

/** One-time migration key: flat PHP 50/booking → PHP 25/hour/court default in settings. */
export const PICKLECAM_HOURLY_RATE_MIGRATION = "pickleCamHourlyRateV1";

/** One-time: weekday peak start 4pm → 6pm when still on legacy default. */
export const WEEKDAY_PEAK_6PM_MIGRATION = "weekdayPeak6pmV1";

export const DEFAULT_DISPLAY_ROTATION = {
  enabledViews: {
    leaderboard: true,
    nextUp: true,
    sponsor: false,
  },
  rotationSeconds: 10,
  adTransitionSeconds: 5,
  sponsors: [],
  sponsorImageUrl: "",
};

function sanitizeSponsorUrl(value) {
  const val = String(value || "").trim();
  if (!val || val.startsWith("data:")) return "";
  if (!/^https?:\/\//i.test(val)) return "";
  return val;
}

export function normalizeSponsorsList(raw = {}, legacyUrl = "") {
  const list = Array.isArray(raw.sponsors) ? raw.sponsors : [];
  const normalized = list
    .map((s, idx) => {
      const url = sanitizeSponsorUrl(s?.url);
      if (!url) return null;
      const name = String(s?.name || "").trim() || `Sponsor ${idx + 1}`;
      return {
        id: s?.id || `sp-${idx}-${url.slice(-8)}`,
        name,
        url,
      };
    })
    .filter(Boolean);

  if (normalized.length === 0) {
    const legacy = sanitizeSponsorUrl(legacyUrl || raw.sponsorImageUrl);
    if (legacy) {
      normalized.push({ id: "legacy-sponsor", name: "Sponsor", url: legacy });
    }
  }
  return normalized;
}

export const normalizeDisplayRotation = (raw = {}) => {
  const views = raw.enabledViews && typeof raw.enabledViews === "object" ? raw.enabledViews : {};
  const rotSec = Number(raw.rotationSeconds);
  const adSec = Number(raw.adTransitionSeconds);
  const sponsors = normalizeSponsorsList(raw, raw.sponsorImageUrl);
  const sponsorWanted = views.sponsor === true;

  return {
    enabledViews: {
      leaderboard: views.leaderboard !== false,
      nextUp: views.nextUp !== false,
      sponsor: sponsorWanted && sponsors.length > 0,
    },
    rotationSeconds:
      Number.isFinite(rotSec) && rotSec >= 3 ? Math.min(120, Math.round(rotSec)) : 10,
    adTransitionSeconds:
      Number.isFinite(adSec) && adSec >= 3 ? Math.min(120, Math.round(adSec)) : 5,
    sponsors,
    sponsorImageUrl: sponsors[0]?.url || "",
  };
};

/** Apply one-time persisted settings migrations after loadState(). */
export const applyPersistedStateMigrations = (state) => {
  if (!state) return null;

  const migrations = { ...(state.meta?.migrations || {}) };
  let nextSettings = { ...(state.settings || {}) };
  let changed = false;

  if (!migrations[PICKLECAM_HOURLY_RATE_MIGRATION]) {
    // Stamp hourly mode as applied, but do not overwrite pickleCamFee. Calendar
    // pricing must follow the live Neon value, not a stale local default.
    migrations[PICKLECAM_HOURLY_RATE_MIGRATION] = new Date().toISOString();
    changed = true;
  }

  if (!migrations[WEEKDAY_PEAK_6PM_MIGRATION]) {
    const rates = nextSettings.rentalRates || {};
    const peak = Number(rates.highStartHour);
    // Migrate only when still on the legacy 4pm default. Do not rewrite
    // calendar open/close — live hours (7–24) differ from rental-window hours.
    if (!Number.isFinite(peak) || peak === 16) {
      nextSettings = {
        ...nextSettings,
        rentalRates: {
          ...rates,
          highStartHour: config.pricing?.rentalRates?.highStartHour ?? 18,
        },
      };
    }
    migrations[WEEKDAY_PEAK_6PM_MIGRATION] = new Date().toISOString();
    changed = true;
  }

  if (!changed) return state;

  return {
    ...state,
    settings: nextSettings,
    meta: {
      ...(state.meta || {}),
      migrations,
    },
  };
};
