const commitAllFields = (baseSettings, draft, fields) => {
  let next = { ...baseSettings };
  fields.forEach((field) => {
    const raw = draft[field.key];
    let parsed;
    if (field.type === "number") {
      if (raw === "" || raw === null || raw === undefined) return;
      parsed = Number(raw);
      if (!Number.isFinite(parsed)) return;
      if (typeof field.min === "number" && parsed < field.min) parsed = field.min;
      if (typeof field.max === "number" && parsed > field.max) parsed = field.max;
    } else {
      parsed = raw ?? "";
    }
    next = typeof field.applyValue === "function"
      ? field.applyValue(next, parsed)
      : { ...next, [field.key]: parsed };
  });
  return next;
};

/** Prefer the values currently in the inputs over React state, so Apply and Save
 *  still picks up the field the admin has focused (or last typed). */
const collectLiveDraft = (form, fields, fallback = {}) => {
  const draft = { ...fallback };
  if (!form) return draft;
  fields.forEach((field) => {
    const el = form.elements?.namedItem(field.key);
    if (el && typeof el.value === "string") draft[field.key] = el.value;
  });
  return draft;
};

/**
 * Loads the facility settings record once, and saves the whole record on demand.
 * Every save is built from local settings, so a save triggered from one card can
 * never publish stale values for another.
 */
function useNeonSettings({ setSettings }) {
  const [remote, setRemote] = React.useState(null);
  const [initialized, setInitialized] = React.useState(false);
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);
  const [offline, setOffline] = React.useState(false);

  React.useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const [data, invoice] = await Promise.all([
          fetchFacilitySettings(),
          fetchInvoiceSettings().catch(() => null),
        ]);
        if (cancelled) return;
        const cs = data.calendar_settings || {};
        setRemote(cs);
        setInitialized(Boolean(data.initialized));
        const mapped = {
          ...calendarSettingsToLocal(cs),
          ...(invoice?.gcashName !== undefined ? { gcashName: invoice.gcashName } : {}),
          ...(invoice?.gcashNumber !== undefined ? { gcashNumber: invoice.gcashNumber } : {}),
        };
        if (data.initialized || invoice) {
          setSettings((prev) => mergeOnlineSettings(prev, mapped));
        }
      } catch (err) {
        if (cancelled) return;
        setOffline(true);
        toast.error(err.message || "Could not load settings");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [setSettings]);

  const save = React.useCallback(
    async (localSettings, successMessage = "Settings saved") => {
      setSaving(true);
      try {
        const payload = localToCalendarSettings(localSettings, remote || {});
        const data = await saveFacilitySettings(payload);
        const saved = data.calendar_settings || payload;
        setRemote(saved);
        setInitialized(true);
        setOffline(false);
        setSettings((prev) =>
          mergeOnlineSettings(prev, calendarSettingsToLocal(saved, { allowEmpty: true }))
        );
        toast.success(successMessage);
        return true;
      } catch (err) {
        toast.error(err.message || "Could not save settings");
        return false;
      } finally {
        setSaving(false);
      }
    },
    [remote, setSettings]
  );

  const saveInvoice = React.useCallback(
    async (localSettings, successMessage = "GCash settings saved") => {
      setSaving(true);
      try {
        const saved = await saveInvoiceSettings({
          gcashName: localSettings.gcashName,
          gcashNumber: localSettings.gcashNumber,
        });
        setRemote((prev) => ({
          ...(prev || {}),
          pricing: {
            ...((prev && prev.pricing) || {}),
            invoice: {
              ...((prev && prev.pricing && prev.pricing.invoice) || {}),
              gcashName: saved.gcashName,
              gcashNumber: saved.gcashNumber,
            },
          },
        }));
        setSettings((prev) => ({
          ...prev,
          gcashName: saved.gcashName,
          gcashNumber: saved.gcashNumber,
        }));
        setOffline(false);
        toast.success(successMessage);
        return true;
      } catch (err) {
        toast.error(err.message || "Could not save GCash settings");
        return false;
      } finally {
        setSaving(false);
      }
    },
    [setSettings]
  );

  return { remote, initialized, loading, saving, offline, save, saveInvoice };
}

function ProtectedSettingsBlock({ settings, setSettings, fields, layout = "stack", autoSave = true, draftRef }) {
  const getFieldValue = React.useCallback(
    (field) => (typeof field.getValue === "function" ? field.getValue(settings) : settings[field.key]),
    [settings]
  );

  const buildDraft = React.useCallback(() => {
    const initial = {};
    fields.forEach((f) => {
      const value = getFieldValue(f);
      initial[f.key] = value === null || value === undefined ? "" : String(value);
    });
    return initial;
  }, [fields, getFieldValue]);

  const [draft, setDraft] = React.useState(buildDraft);
  const [fieldErrors, setFieldErrors] = React.useState({});

  React.useEffect(() => {
    setDraft(buildDraft());
    setFieldErrors({});
  }, [buildDraft]);

  React.useEffect(() => {
    if (draftRef) draftRef.current = draft;
  }, [draft, draftRef]);

  const revertField = React.useCallback(
    (key) => {
      const field = fields.find((f) => f.key === key);
      const value = field ? getFieldValue(field) : settings[key];
      setDraft((prev) => ({
        ...prev,
        [key]: value === null || value === undefined ? "" : String(value),
      }));
    },
    [fields, getFieldValue, settings]
  );

  const parseFieldValue = React.useCallback((field, rawValue) => {
    if (field.type === "number") {
      if (rawValue === "" || rawValue === null || rawValue === undefined) {
        throw new Error("Please enter a value.");
      }
      let numeric = Number(rawValue);
      if (!Number.isFinite(numeric)) {
        throw new Error("Please enter a valid number.");
      }
      if (typeof field.min === "number" && numeric < field.min) {
        numeric = field.min;
      }
      if (typeof field.max === "number" && numeric > field.max) {
        numeric = field.max;
      }
      return numeric;
    }
    return rawValue ?? "";
  }, []);

  const commitField = React.useCallback(
    async (field) => {
      const { key } = field;
      try {
        const parsedValue = parseFieldValue(field, draft[key]);
        if (typeof field.onCommit === "function") {
          await field.onCommit(parsedValue, { previousValue: getFieldValue(field) });
        }
        if (typeof field.applyValue === "function") {
          setSettings((prev) => field.applyValue(prev, parsedValue));
        } else {
          setSettings((prev) => ({ ...prev, [key]: parsedValue }));
        }
        setFieldErrors((prev) => ({ ...prev, [key]: null }));
      } catch (error) {
        setFieldErrors((prev) => ({
          ...prev,
          [key]: error?.message || "Unable to save this value. Please try again.",
        }));
        revertField(key);
      }
    },
    [draft, getFieldValue, parseFieldValue, revertField, setSettings]
  );

  const containerClass =
    layout === "grid"
      ? "grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-x-4 gap-y-3 text-xs text-slate-700"
      : "space-y-3 text-xs text-slate-700 max-w-md";

  const hint = autoSave
    ? "Changes save automatically when you leave a field."
    : "Click Apply and Save to store these values for every device.";

  return (
    <div className={containerClass}>
      {fields.map((f) => (
        <div key={f.key}>
          <label className="block">
            <span className="block mb-1 font-medium">{f.label}</span>
            <input
              name={f.key}
              type={f.type || "text"}
              min={f.min}
              max={f.max}
              step={f.step}
              className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
              value={draft[f.key] ?? ""}
              onChange={(e) => {
                const { value } = e.target;
                setDraft((prev) => {
                  const next = { ...prev, [f.key]: value };
                  if (draftRef) draftRef.current = next;
                  return next;
                });
                setFieldErrors((prev) => ({ ...prev, [f.key]: null }));
              }}
              onBlur={() => {
                if (autoSave) void commitField(f);
              }}
            />
            {fieldErrors[f.key] && (
              <p className="mt-1 text-[11px] text-rose-600">{fieldErrors[f.key]}</p>
            )}
          </label>
        </div>
      ))}
      {layout === "grid" ? (
        <p className="sm:col-span-2 xl:col-span-3 text-[11px] text-slate-500">{hint}</p>
      ) : (
        <p className="text-[11px] text-slate-500">{hint}</p>
      )}
    </div>
  );
}

function NeonOperationalSettingsBlock({ settings, setSettings, fields, neon }) {
  const [draftSettings, setDraftSettings] = React.useState(settings);
  const flatDraftRef = React.useRef({});
  const settingsRef = React.useRef(settings);
  settingsRef.current = settings;

  // Resync only when the stored record changes, so edits elsewhere on the page
  // cannot discard values typed here but not yet saved.
  React.useEffect(() => {
    if (neon.initialized) setDraftSettings(settingsRef.current);
  }, [neon.initialized, neon.remote]);

  const handleSubmit = (event) => {
    event.preventDefault();
    const liveDraft = collectLiveDraft(event.currentTarget, fields, flatDraftRef.current);
    // Latest app settings (staff list, etc.) plus what is on screen right now.
    const committed = commitAllFields(
      { ...settingsRef.current, ...draftSettings },
      liveDraft,
      fields
    );
    setDraftSettings(committed);
    void neon.save(committed, "Settings saved");
  };

  if (neon.loading) {
    return <p className="text-xs text-slate-500">Loading settings…</p>;
  }

  // Nothing published yet: keep editing locally and offer to publish the values
  // this admin already uses, rather than pulling defaults down over them.
  if (!neon.initialized) {
    return (
      <form onSubmit={handleSubmit}>
        <ProtectedSettingsBlock
          layout="grid"
          settings={settings}
          setSettings={setSettings}
          fields={fields}
          autoSave
          draftRef={flatDraftRef}
        />
        <div className="mt-4 flex flex-wrap items-center gap-3">
          <button
            type="submit"
            disabled={neon.saving || neon.offline}
            className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
          >
            {neon.saving ? "Saving…" : "Apply and Save"}
          </button>
          <span className="text-[11px] text-slate-500">
            {neon.offline
              ? "Could not reach the server, so these values stay on this device only."
              : "These values are still local to this device. Apply and save them to share them with every device."}
          </span>
        </div>
      </form>
    );
  }

  return (
    <form onSubmit={handleSubmit}>
      <ProtectedSettingsBlock
        layout="grid"
        settings={draftSettings}
        setSettings={setDraftSettings}
        fields={fields}
        autoSave={false}
        draftRef={flatDraftRef}
      />
      <div className="mt-4 flex flex-wrap items-center gap-3">
        <button
          type="submit"
          disabled={neon.saving}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {neon.saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          Every device reads pricing and hours from these values.
        </span>
      </div>
    </form>
  );
}

function GcashInvoiceSettingsBlock({ settings, neon }) {
  const fields = GCASH_INVOICE_FIELDS;
  const [draftSettings, setDraftSettings] = React.useState(settings);
  const flatDraftRef = React.useRef({});
  const settingsRef = React.useRef(settings);
  settingsRef.current = settings;

  React.useEffect(() => {
    setDraftSettings(settingsRef.current);
  }, [neon.remote]);

  const handleSubmit = (event) => {
    event.preventDefault();
    const liveDraft = collectLiveDraft(event.currentTarget, fields, flatDraftRef.current);
    const committed = commitAllFields(
      { ...settingsRef.current, ...draftSettings },
      liveDraft,
      fields
    );
    setDraftSettings(committed);
    void neon.saveInvoice(committed, "GCash settings saved");
  };

  if (neon.loading) {
    return <p className="text-xs text-slate-500">Loading settings…</p>;
  }

  return (
    <form onSubmit={handleSubmit}>
      <ProtectedSettingsBlock
        layout="grid"
        settings={draftSettings}
        setSettings={setDraftSettings}
        fields={fields}
        autoSave={false}
        draftRef={flatDraftRef}
      />
      <div className="mt-4 flex flex-wrap items-center gap-3">
        <button
          type="submit"
          disabled={neon.saving || neon.offline}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {neon.saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          {neon.offline
            ? "Could not reach the server, so these values stay on this device only."
            : "Unpaid invoices show this GCash name and number. The QR payment view is unchanged."}
        </span>
      </div>
    </form>
  );
}

function StaffListBlock({ settings, addStaff, renameStaff, removeStaff, neon }) {
  const roster = normalizeStaffRoster(settings.staffList);
  const [newName, setNewName] = React.useState("");
  const [error, setError] = React.useState("");
  const [editingId, setEditingId] = React.useState(null);
  const [editingName, setEditingName] = React.useState("");

  const handleAdd = (event) => {
    event.preventDefault();
    try {
      addStaff(newName);
      setNewName("");
      setError("");
    } catch (err) {
      setError(err.message || "Could not add that name.");
    }
  };

  const handleRename = () => {
    try {
      renameStaff(editingId, editingName);
      setEditingId(null);
      setEditingName("");
      setError("");
    } catch (err) {
      setError(err.message || "Could not rename that staff member.");
    }
  };

  return (
    <div className="space-y-4 text-xs text-slate-700 max-w-md">
      <form onSubmit={handleAdd} className="flex gap-2">
        <input
          type="text"
          value={newName}
          onChange={(e) => {
            setNewName(e.target.value);
            setError("");
          }}
          placeholder="Staff name"
          className="flex-1 border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
        />
        <button
          type="submit"
          className="px-3 py-1 rounded-full text-xs font-semibold text-white bg-pt-navy hover:bg-pt-navy/90 shadow-sm"
        >
          Add
        </button>
      </form>

      {roster.length === 0 ? (
        <p className="text-[11px] text-slate-500">
          No staff yet. Staff cannot sign in until at least one name is on this list.
        </p>
      ) : (
        <ul className="divide-y divide-slate-100 border border-slate-100 rounded-lg">
          {roster.map((member) => (
            <li key={member.id} className="flex items-center gap-2 px-3 py-2">
              {editingId === member.id ? (
                <>
                  <input
                    type="text"
                    autoFocus
                    value={editingName}
                    onChange={(e) => setEditingName(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        handleRename();
                      }
                      if (e.key === "Escape") setEditingId(null);
                    }}
                    className="flex-1 border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
                  />
                  <button
                    type="button"
                    onClick={handleRename}
                    className="text-[11px] font-semibold text-pt-teal hover:underline"
                  >
                    Save
                  </button>
                  <button
                    type="button"
                    onClick={() => setEditingId(null)}
                    className="text-[11px] text-slate-400 hover:underline"
                  >
                    Cancel
                  </button>
                </>
              ) : (
                <>
                  <span className="flex-1 font-medium">{member.name}</span>
                  <button
                    type="button"
                    onClick={() => {
                      setEditingId(member.id);
                      setEditingName(member.name);
                      setError("");
                    }}
                    className="text-[11px] font-semibold text-slate-500 hover:text-slate-700 hover:underline"
                  >
                    Rename
                  </button>
                  <button
                    type="button"
                    onClick={() => removeStaff(member.id)}
                    className="text-[11px] font-semibold text-rose-600 hover:underline"
                  >
                    Remove
                  </button>
                </>
              )}
            </li>
          ))}
        </ul>
      )}

      {error && <p className="text-[11px] text-rose-600">{error}</p>}

      <div className="flex flex-wrap items-center gap-3">
        <button
          type="button"
          disabled={neon.saving || neon.loading}
          onClick={() => {
            try {
              let roster = normalizeStaffRoster(settings.staffList);
              if (editingId) {
                roster = renameStaffMember(roster, editingId, editingName);
                renameStaff(editingId, editingName);
                setEditingId(null);
                setEditingName("");
              }
              const pendingName = newName.trim();
              if (pendingName) {
                roster = addStaffMember(roster, pendingName);
                addStaff(pendingName);
                setNewName("");
              }
              setError("");
              void neon.save({ ...settings, staffList: roster }, "Staff list saved");
            } catch (err) {
              setError(err.message || "Could not save the staff list.");
            }
          }}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {neon.saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          Staff pick from this list at sign-in, so it has to be saved online.
        </span>
      </div>
    </div>
  );
}

function NeonAdminPasswordBlock() {
  const [oldPassword, setOldPassword] = React.useState("");
  const [newPassword, setNewPassword] = React.useState("");
  const [confirmPassword, setConfirmPassword] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState("");

  const handleSave = async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const current = String(form.elements.namedItem("oldPassword")?.value ?? oldPassword);
    const next = String(form.elements.namedItem("newPassword")?.value ?? newPassword);
    const confirmValue = String(
      form.elements.namedItem("confirmPassword")?.value ?? confirmPassword
    );
    setError("");
    if (!current) {
      setError("Enter the current password.");
      return;
    }
    if (!next || next.length < 4) {
      setError("New password must be at least 4 characters.");
      return;
    }
    if (next !== confirmValue) {
      setError("New password and confirmation do not match.");
      return;
    }
    setSaving(true);
    try {
      await changeAdminPassword({
        oldPassword: current,
        newPassword: next,
        confirmPassword: confirmValue,
      });
      setOldPassword("");
      setNewPassword("");
      setConfirmPassword("");
      toast.success("Password saved");
    } catch (err) {
      setError(err.message || "Could not save password");
      toast.error(err.message || "Could not save password");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSave} className="space-y-3 text-xs text-slate-700 max-w-md">
      <label className="block">
        <span className="block mb-1 font-medium">Current password</span>
        <input
          name="oldPassword"
          type="password"
          autoComplete="current-password"
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={oldPassword}
          onChange={(e) => setOldPassword(e.target.value)}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">New password</span>
        <input
          name="newPassword"
          type="password"
          autoComplete="new-password"
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">Confirm new password</span>
        <input
          name="confirmPassword"
          type="password"
          autoComplete="new-password"
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={confirmPassword}
          onChange={(e) => setConfirmPassword(e.target.value)}
        />
      </label>
      {error && <p className="text-[11px] text-rose-600">{error}</p>}
      <div className="flex items-center gap-3">
        <button
          type="submit"
          disabled={saving}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          Login checks this password on the server, not the copy in this browser.
        </span>
      </div>
    </form>
  );
}

function NeonLockPinBlock() {
  const [oldPin, setOldPin] = React.useState("");
  const [newPin, setNewPin] = React.useState("");
  const [confirmPin, setConfirmPin] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState("");

  const handleSave = async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const current = String(form.elements.namedItem("oldPin")?.value ?? oldPin).replace(/\D/g, "");
    const next = String(form.elements.namedItem("newPin")?.value ?? newPin).replace(/\D/g, "");
    const confirmValue = String(
      form.elements.namedItem("confirmPin")?.value ?? confirmPin
    ).replace(/\D/g, "");
    setError("");
    if (!current) {
      setError("Enter the current PIN.");
      return;
    }
    if (!/^\d{6}$/.test(next)) {
      setError("New PIN must be 6 digits.");
      return;
    }
    if (next !== confirmValue) {
      setError("New PIN and confirmation do not match.");
      return;
    }
    setSaving(true);
    try {
      await changeLockPin({
        oldPin: current,
        newPin: next,
        confirmPin: confirmValue,
      });
      setOldPin("");
      setNewPin("");
      setConfirmPin("");
      toast.success("PIN saved");
    } catch (err) {
      setError(err.message || "Could not save PIN");
      toast.error(err.message || "Could not save PIN");
    } finally {
      setSaving(false);
    }
  };

  return (
    <form onSubmit={handleSave} className="space-y-3 text-xs text-slate-700 max-w-md">
      <label className="block">
        <span className="block mb-1 font-medium">Current PIN</span>
        <input
          name="oldPin"
          type="password"
          inputMode="numeric"
          autoComplete="off"
          maxLength={6}
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={oldPin}
          onChange={(e) => setOldPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">New PIN</span>
        <input
          name="newPin"
          type="password"
          inputMode="numeric"
          autoComplete="off"
          maxLength={6}
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={newPin}
          onChange={(e) => setNewPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
        />
      </label>
      <label className="block">
        <span className="block mb-1 font-medium">Confirm new PIN</span>
        <input
          name="confirmPin"
          type="password"
          inputMode="numeric"
          autoComplete="off"
          maxLength={6}
          className="w-full border border-slate-200 rounded-lg px-2 py-1 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-200"
          value={confirmPin}
          onChange={(e) => setConfirmPin(e.target.value.replace(/\D/g, "").slice(0, 6))}
        />
      </label>
      {error && <p className="text-[11px] text-rose-600">{error}</p>}
      <div className="flex items-center gap-3">
        <button
          type="submit"
          disabled={saving}
          className="inline-flex items-center justify-center px-4 py-2 rounded-full text-xs font-semibold text-white bg-pt-teal hover:bg-pt-teal/90 shadow-sm disabled:opacity-60"
        >
          {saving ? "Saving…" : "Apply and Save"}
        </button>
        <span className="text-[11px] text-slate-500">
          Required after every refresh or reload. Separate from the admin password.
        </span>
      </div>
    </form>
  );
}

