import React, { useCallback, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAppState } from "../../app/providers";
import { selectQueueState } from "../../state/selectors";
import config from "../../config";
import { verifyAdminPassword } from "../../common/api/adminPassword";
import { fetchStaffMembers } from "../../common/api/facilitySettings";
import { normalizeStaffRoster } from "../../state/staffRoster";

export default function LandingPage() {
    const navigate = useNavigate();
    const { setUserRole, setStaffName, setStaffList, settings } = useAppState(selectQueueState);

    const [isAdminPromptOpen, setIsAdminPromptOpen] = useState(false);
    const [isStaffPromptOpen, setIsStaffPromptOpen] = useState(false);
    const [selectedStaffId, setSelectedStaffId] = useState("");
    const [staffError, setStaffError] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");
    const [isVerifying, setIsVerifying] = useState(false);

    // The roster lives in Neon so every device sees the same names. The copy cached
    // in local settings keeps sign-in working when the API is unreachable.
    const [roster, setRoster] = useState(() => normalizeStaffRoster(settings?.staffList));
    const [isLoadingRoster, setIsLoadingRoster] = useState(false);
    const [rosterOffline, setRosterOffline] = useState(false);

    const loadRoster = useCallback(async () => {
        setIsLoadingRoster(true);
        setRosterOffline(false);
        try {
            const members = normalizeStaffRoster(await fetchStaffMembers());
            if (members.length > 0) {
                setRoster(members);
                setStaffList?.(members);
            } else {
                // Empty Neon roster is "not published yet". Keep any names already
                // cached on this device so staff are not locked out before Save.
                setRoster((prev) => (prev.length > 0 ? prev : []));
            }
        } catch {
            setRosterOffline(true);
        } finally {
            setIsLoadingRoster(false);
        }
    }, [setStaffList]);

    useEffect(() => {
        if (isStaffPromptOpen) void loadRoster();
    }, [isStaffPromptOpen, loadRoster]);

    const handleStaffLogin = () => {
        const member = roster.find((m) => m.id === selectedStaffId);
        if (!member) {
            setStaffError("Select your name to continue.");
            return;
        }
        setStaffName(member.name);
        setUserRole("staff");
        setIsStaffPromptOpen(false);
        setStaffError("");
        navigate("/calendar-v2");
    };

    const handleAdminLogin = async () => {
        if (!password) {
            setError("Enter the master password.");
            return;
        }
        setIsVerifying(true);
        setError("");
        try {
            await verifyAdminPassword(password);
            setStaffName("");
            setUserRole("admin");
            navigate("/dashboard");
        } catch (err) {
            setError(err.message || "Incorrect password");
        } finally {
            setIsVerifying(false);
        }
    };

    return (
        <div className="min-h-screen w-full bg-pt-canvas flex items-center justify-center p-4 font-body text-pt-navy">
            <div className="w-full max-w-4xl bg-white rounded-3xl shadow-2xl border border-pt-slate-500/10 overflow-hidden flex flex-col md:flex-row min-h-[28rem]">

                {/* Left Side: Branding */}
                <div className="bg-pt-navy text-white px-8 py-10 md:px-10 md:py-12 flex flex-col justify-center items-center md:w-[42%] text-center shrink-0">
                    <div className="w-24 h-24 md:w-28 md:h-28 bg-white rounded-full flex items-center justify-center mb-5 shadow-lg overflow-hidden border-4 border-white/30">
                        <img src={config.assetPath("logo.png")} alt={config.name} className="w-full h-full object-cover" />
                    </div>
                    <h1 className="!text-white font-display font-extrabold italic text-[clamp(1.15rem,2.4vw,1.75rem)] leading-[1.15] tracking-wide mb-3 max-w-[16ch] mx-auto">
                        {config.name}
                    </h1>
                    <p className="text-white/70 text-sm font-body normal-case tracking-normal font-normal not-italic">
                        {config.tagline || "Pickleball Facility"}
                    </p>
                </div>

                {/* Right Side: Selection */}
                <div className="p-8 md:p-12 md:w-[58%] flex flex-col justify-center">

                    {!isAdminPromptOpen && !isStaffPromptOpen ? (
                        <>
                            <h2 className="text-xl md:text-2xl font-display font-extrabold italic mb-8 text-center uppercase tracking-wide text-pt-navy">
                                Select User Role
                            </h2>
                            <div className="space-y-4">
                                <button
                                    type="button"
                                    onClick={() => {
                                        setSelectedStaffId("");
                                        setStaffError("");
                                        setIsStaffPromptOpen(true);
                                    }}
                                    className="w-full group relative p-6 border-2 border-pt-slate-500/10 rounded-2xl hover:border-pt-orange hover:bg-pt-orange/5 transition-all text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <span className="text-3xl p-3 bg-pt-orange/10 rounded-full group-hover:bg-pt-orange group-hover:text-white transition-colors">👋</span>
                                        <div>
                                            <h3 className="text-lg font-bold text-pt-navy">Staff</h3>
                                            <p className="text-xs text-slate-500">Operations, Queue, Calendar</p>
                                        </div>
                                    </div>
                                </button>

                                <button
                                    type="button"
                                    onClick={() => setIsAdminPromptOpen(true)}
                                    className="w-full group relative p-6 border-2 border-pt-slate-500/10 rounded-2xl hover:border-pt-green hover:bg-pt-green/5 transition-all text-left"
                                >
                                    <div className="flex items-center gap-4">
                                        <span className="text-3xl p-3 bg-pt-green/10 text-pt-green-dark rounded-full group-hover:bg-pt-green group-hover:text-white transition-colors">🔒</span>
                                        <div>
                                            <h3 className="text-lg font-bold text-pt-navy">Admin / Owner</h3>
                                            <p className="text-xs text-slate-500">Full Access to All Modules</p>
                                        </div>
                                    </div>
                                </button>
                            </div>
                        </>
                    ) : isStaffPromptOpen ? (
                        <div className="animate-in slide-in-from-right fade-in duration-300">
                            <button
                                type="button"
                                onClick={() => {
                                    setIsStaffPromptOpen(false);
                                    setStaffError("");
                                    setSelectedStaffId("");
                                }}
                                className="text-xs font-bold text-slate-400 hover:text-pt-navy mb-6 flex items-center gap-1"
                            >
                                ← BACK
                            </button>
                            <h2 className="text-xl font-bold mb-2">Staff sign-in</h2>
                            <p className="text-xs text-slate-500 mb-6">Select your name. It is recorded on session and booking history.</p>

                            <form onSubmit={(e) => { e.preventDefault(); handleStaffLogin(); }}>
                                {isLoadingRoster && roster.length === 0 ? (
                                    <p className="text-sm text-slate-500 py-6 text-center">Loading staff list…</p>
                                ) : roster.length === 0 ? (
                                    <div className="rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center">
                                        <p className="text-sm font-bold text-pt-navy mb-1">No staff has been added yet</p>
                                        <p className="text-xs text-slate-500">
                                            Ask an admin to add staff in Settings, then try again.
                                        </p>
                                        <button
                                            type="button"
                                            onClick={() => void loadRoster()}
                                            className="mt-4 text-xs font-bold text-pt-orange hover:underline"
                                        >
                                            Retry
                                        </button>
                                    </div>
                                ) : (
                                    <div className="max-h-64 overflow-y-auto space-y-2 mb-2">
                                        {roster.map((member) => (
                                            <button
                                                key={member.id}
                                                type="button"
                                                onClick={() => {
                                                    setSelectedStaffId(member.id);
                                                    setStaffError("");
                                                }}
                                                className={`w-full text-left px-4 py-3 rounded-xl border-2 transition-all ${
                                                    selectedStaffId === member.id
                                                        ? "border-pt-orange bg-pt-orange/5 font-bold text-pt-navy"
                                                        : "border-slate-200 hover:border-pt-orange/60 text-slate-700"
                                                }`}
                                            >
                                                {member.name}
                                            </button>
                                        ))}
                                    </div>
                                )}

                                {rosterOffline && roster.length > 0 && (
                                    <p className="text-amber-600 text-xs font-bold mb-2">
                                        Showing the last known staff list — could not reach the server.
                                    </p>
                                )}
                                {staffError && <p className="text-red-500 text-xs font-bold mb-4">{staffError}</p>}

                                <button
                                    type="submit"
                                    disabled={roster.length === 0}
                                    className="w-full bg-pt-orange text-white py-4 rounded-xl font-bold hover:bg-pt-orange-dark transition-transform active:scale-95 shadow-lg mt-2 disabled:opacity-50 disabled:cursor-not-allowed disabled:active:scale-100"
                                >
                                    Continue to Calendar
                                </button>
                            </form>
                        </div>
                    ) : (
                        <div className="animate-in slide-in-from-right fade-in duration-300">
                            <button
                                type="button"
                                onClick={() => {
                                    setIsAdminPromptOpen(false);
                                    setError("");
                                    setPassword("");
                                }}
                                className="text-xs font-bold text-slate-400 hover:text-pt-navy mb-6 flex items-center gap-1"
                            >
                                ← BACK
                            </button>
                            <h2 className="text-xl font-bold mb-2">Admin Access</h2>
                            <p className="text-xs text-slate-500 mb-6">Enter the master password to continue.</p>

                            <form onSubmit={(e) => { e.preventDefault(); if (!isVerifying) void handleAdminLogin(); }}>
                                <input
                                    type="password"
                                    autoFocus
                                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl focus:border-pt-orange focus:ring-pt-orange outline-none transition-all mb-4 font-mono text-lg"
                                    placeholder="Password"
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                />
                                {error && <p className="text-red-500 text-xs font-bold mb-4">{error}</p>}

                                <button
                                    type="submit"
                                    disabled={isVerifying}
                                    className="w-full bg-pt-orange text-white py-4 rounded-xl font-bold hover:bg-pt-orange-dark transition-transform active:scale-95 shadow-lg disabled:opacity-60"
                                >
                                    {isVerifying ? "Checking…" : "Unlock Dashboard"}
                                </button>
                            </form>
                        </div>
                    )}

                </div>
            </div>

            <div className="absolute bottom-4 text-center w-full text-pt-navy/20 text-[10px] font-mono pointer-events-none">
                POWERED BY DINK MANAGER
            </div>
        </div>
    );
}
