/**
 * Staff roster (settings.staffList). The admin maintains it in Settings, it is
 * stored in Neon so every device sees the same names, and staff pick from it at
 * sign-in instead of typing a name.
 */

const makeId = (name, index) => {
  const slug = String(name || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return `staff-${slug || "member"}-${index}`;
};

/** Trims, drops blanks and keeps the first of any case-insensitive duplicate. */
export function normalizeStaffRoster(raw) {
  const list = Array.isArray(raw) ? raw : [];
  const seen = new Set();
  const members = [];
  list.forEach((entry, idx) => {
    const name = String(typeof entry === "string" ? entry : entry?.name || "").trim();
    if (!name) return;
    const dedupeKey = name.toLowerCase();
    if (seen.has(dedupeKey)) return;
    seen.add(dedupeKey);
    const id = String(entry?.id || "").trim() || makeId(name, idx);
    members.push({ id, name });
  });
  return members;
}

export function addStaffMember(roster, name) {
  const trimmed = String(name || "").trim();
  if (!trimmed) throw new Error("Enter a staff name.");
  const current = normalizeStaffRoster(roster);
  if (current.some((m) => m.name.toLowerCase() === trimmed.toLowerCase())) {
    throw new Error(`${trimmed} is already on the list.`);
  }
  return [...current, { id: makeId(trimmed, current.length), name: trimmed }];
}

export function renameStaffMember(roster, id, name) {
  const trimmed = String(name || "").trim();
  if (!trimmed) throw new Error("Enter a staff name.");
  const current = normalizeStaffRoster(roster);
  if (current.some((m) => m.id !== id && m.name.toLowerCase() === trimmed.toLowerCase())) {
    throw new Error(`${trimmed} is already on the list.`);
  }
  return current.map((m) => (m.id === id ? { ...m, name: trimmed } : m));
}

export function removeStaffMember(roster, id) {
  return normalizeStaffRoster(roster).filter((m) => m.id !== id);
}

/**
 * Map a Neon `staff.members` array onto local `settings.staffList`.
 *
 * An empty remote list is treated as "not published yet" on load, so a device
 * that already has names is not wiped before the admin hits Save. After a save
 * the caller passes `{ allowEmpty: true }` so an intentionally cleared roster
 * does stick.
 */
export function staffListPatchFromRemote(members, { allowEmpty = false } = {}) {
  const list = normalizeStaffRoster(members);
  if (list.length > 0) return { staffList: list };
  if (allowEmpty) return { staffList: [] };
  return {};
}
