import React from "react";

export default function SettlePaymentModal({ isOpen, onClose, onSettle, title = "Settle Payment", amount }) {
    if (!isOpen) return null;

    const options = [
        { id: "cash", label: "Cash", icon: "💵", color: "bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100" },
        { id: "gcash", label: "GCash", icon: "📱", color: "bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100" },
        { id: "gotyme", label: "GoTyme", icon: "💳", color: "bg-purple-50 text-purple-700 border-purple-200 hover:bg-purple-100" },
        { id: "bank", label: "Bank", icon: "🏦", color: "bg-teal-50 text-teal-700 border-teal-200 hover:bg-teal-100" },
        { id: "free", label: "Free / Waived", icon: "🎉", color: "bg-slate-50 text-slate-700 border-slate-200 hover:bg-slate-100" },
        { id: "cancelled", label: "Cancelled", icon: "🚫", color: "bg-rose-50 text-rose-700 border-rose-200 hover:bg-rose-100" },
    ];

    const formatCurrency = (val) => new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP", maximumFractionDigits: 0 }).format(val || 0);

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4 animate-in fade-in duration-200">
            <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full overflow-hidden flex flex-col">
                <div className="p-5 border-b border-gray-100 bg-white">
                    <div className="flex justify-between items-center mb-1">
                        <h2 className="text-lg font-bold text-slate-900">{title}</h2>
                        <button onClick={onClose} className="p-2 rounded-full hover:bg-slate-100 text-slate-500 transition-colors">✕</button>
                    </div>
                    {amount !== undefined && (
                        <p className="text-sm text-slate-500">Amount Due: <span className="font-bold text-slate-900">{formatCurrency(amount)}</span></p>
                    )}
                </div>

                <div className="p-4 grid grid-cols-1 gap-3">
                    {options.map((opt) => (
                        <button
                            key={opt.id}
                            onClick={() => onSettle(opt.id)}
                            className={`flex items-center gap-3 p-3 rounded-xl border transition-all active:scale-95 ${opt.color}`}
                        >
                            <span className="text-2xl">{opt.icon}</span>
                            <span className="font-bold text-sm">{opt.label}</span>
                        </button>
                    ))}
                    <button
                        onClick={() => onSettle("unpaid")}
                        className="flex items-center gap-3 p-3 rounded-xl border border-dashed border-slate-300 text-slate-400 hover:bg-slate-50 hover:text-slate-600 transition-all font-medium text-sm justify-center mt-2"
                    >
                        Mark as Unpaid
                    </button>
                </div>
            </div>
        </div>
    );
}
