import React, { useEffect, useMemo, useState } from "react";
import {
  looksLikeDirectImageUrl,
  resolveSponsorImageUrl,
} from "../../../common/utils/sponsorImage";

export default function SponsorView({ imageUrl }) {
  const [failed, setFailed] = useState(false);
  const src = useMemo(() => resolveSponsorImageUrl(imageUrl), [imageUrl]);
  const maybeNotDirect = src && /^https?:\/\//i.test(src) && !looksLikeDirectImageUrl(src);

  useEffect(() => {
    setFailed(false);
  }, [src]);

  if (!imageUrl || !src) {
    return (
      <div className="h-full flex items-center justify-center text-white/40 uppercase tracking-widest text-sm">
        No sponsor image configured
      </div>
    );
  }

  if (failed) {
    return (
      <div className="h-full flex flex-col items-center justify-center gap-3 px-8 text-center max-w-2xl mx-auto">
        <p className="text-white/70 uppercase tracking-widest text-sm font-display font-extrabold italic">
          Sponsor image could not load
        </p>
        <p className="text-white/45 text-xs leading-relaxed">
          Use a <strong className="text-white/60">direct image URL</strong> ending in .png, .jpg, or
          .webp (right-click image → Copy image address) — not a gallery page link.
        </p>
        <p className="text-[10px] text-white/30 truncate w-full font-mono">{imageUrl}</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col items-center justify-center gap-4 px-6">
      <p className="text-[11px] text-white/45 uppercase tracking-[0.35em]">Presented by</p>
      {maybeNotDirect && (
        <p className="text-[10px] text-amber-300/80 text-center max-w-lg">
          This URL may not be a direct image file — if it does not appear, use a direct .jpg/.png
          link.
        </p>
      )}
      <img
        key={src}
        src={src}
        alt="Sponsor"
        referrerPolicy="no-referrer"
        onError={() => setFailed(true)}
        onLoad={() => setFailed(false)}
        className="max-h-[70vh] max-w-full object-contain rounded-2xl shadow-2xl border border-white/10 bg-white/5 p-4"
      />
    </div>
  );
}
