/**
 * Session stats for display leaderboard (from completed matches + player PD).
 */
export function computeSessionPlayerStats(players = [], matches = []) {
  const byId = new Map();
  players.forEach((p) => {
    byId.set(String(p.id), {
      id: p.id,
      name: p.name,
      level: p.level,
      player: p,
      wins: 0,
      losses: 0,
      matches: 0,
      totalPoints: 0,
      pointDifferential:
        typeof p.pointDifferential === "number" ? p.pointDifferential : 0,
    });
  });

  matches
    .filter((m) => m && m.status === "completed")
    .forEach((m) => {
      const green = (m.teams?.green || []).map(String);
      const blue = (m.teams?.blue || []).map(String);
      const gScore = Number(m.score?.green);
      const bScore = Number(m.score?.blue);
      const all = [...new Set([...green, ...blue])];

      all.forEach((pid) => {
        if (!byId.has(pid)) return;
        const row = byId.get(pid);
        row.matches += 1;
        const onGreen = green.includes(pid);
        const teamScore = onGreen ? gScore : bScore;
        if (Number.isFinite(teamScore)) row.totalPoints += teamScore;
        const won =
          (m.winner === "green" && onGreen) || (m.winner === "blue" && !onGreen);
        const lost =
          (m.winner === "green" && !onGreen) || (m.winner === "blue" && onGreen);
        if (won) row.wins += 1;
        else if (lost) row.losses += 1;
      });
    });

  return [...byId.values()].map((row) => {
    const wr = row.matches > 0 ? Math.round((100 * row.wins) / row.matches) : 0;
    const avg =
      row.matches > 0
        ? Math.round((row.pointDifferential / row.matches) * 10) / 10
        : 0;
    return { ...row, winRate: wr, avgPointDiff: avg };
  });
}

export function rankSessionPlayers(stats = []) {
  return [...stats]
    .filter((e) => e.matches >= 1 || e.pointDifferential !== 0)
    .sort(
      (a, b) =>
        b.wins - a.wins ||
        b.pointDifferential - a.pointDifferential ||
        b.totalPoints - a.totalPoints
    );
}
