import React, { useMemo } from "react";
import { createPortal } from "react-dom";

export default function TeamRosterModal({
  isOpen,
  onClose,
  team,
  players = [],
  teamsSettings,
  unassignedLabel = "Unassigned",
  onAssignPlayer,
  onRemovePlayer,
}) {
  const teamId = team?.id;

  const openPlayers = useMemo(
    () => players.filter((p) => !p.teamId || p.teamId === null),
    [players]
  );

  const roster = useMemo(
    () =>
      players.filter((p) => teamId != null && String(p.teamId) === String(teamId)),
    [players, teamId]
  );

  if (!isOpen || !team) return null;

  return createPortal(
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
      <div className="bg-white rounded-2xl shadow-xl max-w-md w-full max-h-[85vh] overflow-hidden flex flex-col border border-slate-200">
        <div className="px-5 py-4 border-b flex justify-between items-center">
          <div className="flex items-center gap-2">
            <span
              className="w-10 h-10 rounded-xl shrink-0 border border-slate-100 shadow-sm"
              style={{ backgroundColor: team.color }}
            />
            <div>
              <h2 className="text-lg font-display font-semibold text-slate-900">{team.name}</h2>
              <p className="text-[11px] text-slate-500">Roster</p>
            </div>
          </div>
          <button type="button" className="text-slate-400 hover:text-slate-700 text-xl" onClick={onClose}>
            ×
          </button>
        </div>
        <div className="px-5 py-4 overflow-y-auto flex-1 space-y-4 text-xs">
          <div>
            <h3 className="font-semibold text-slate-800 mb-2">On this team</h3>
            <ul className="space-y-2">
              {roster.length === 0 && <li className="text-slate-400">No players yet.</li>}
              {roster.map((p) => (
                <li
                  key={p.id}
                  className="flex items-center justify-between gap-2 border border-slate-100 rounded-lg px-3 py-2 bg-slate-50/80"
                >
                  <span className="font-medium text-slate-800">{p.name}</span>
                  <button
                    type="button"
                    className="text-[11px] text-amber-700 font-semibold hover:underline"
                    onClick={() => onRemovePlayer?.(p.id)}
                  >
                    Remove
                  </button>
                </li>
              ))}
            </ul>
          </div>
          <div>
            <h3 className="font-semibold text-slate-800 mb-2">{unassignedLabel} (add to team)</h3>
            <ul className="space-y-2 max-h-48 overflow-y-auto">
              {openPlayers.length === 0 && <li className="text-slate-400">No open players.</li>}
              {openPlayers.map((p) => (
                <li
                  key={p.id}
                  className="flex items-center justify-between gap-2 border border-slate-100 rounded-lg px-3 py-2"
                >
                  <span>{p.name}</span>
                  <button
                    type="button"
                    className="text-[11px] text-pt-teal font-semibold hover:underline"
                    onClick={() => onAssignPlayer?.(p.id, teamId)}
                  >
                    Add
                  </button>
                </li>
              ))}
            </ul>
          </div>
        </div>
        <div className="px-5 py-3 border-t bg-slate-50 flex justify-end">
          <button
            type="button"
            className="px-4 py-2 rounded-full text-xs bg-slate-800 text-white font-semibold"
            onClick={onClose}
          >
            Done
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}
