import React, { useCallback, useEffect, useState } from "react";
import CompactCourtCard from "./CompactCourtCard";
import { playerIdKey } from "../../../state/courtPlayers";

export default function CourtsRow({
  courts = [],
  players = [],
  matches = [],
  onAssign,
  onRemove,
  onUnlockCourt,
  onUpdateCourtName,
  onRemoveCourt,
  onCompleteMatch,
  onRequestMove,
  onReturnToQueue,
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
}) {
  const [activeDisplayCourtId, setActiveDisplayCourtId] = useState(null);

  const postMessage = useCallback((type, courtId) => {
    if (typeof window === "undefined" || !("BroadcastChannel" in window)) return;
    const bc = new BroadcastChannel("dink_manager");
    bc.postMessage({ type, courtId });
    bc.close();
  }, []);

  const openDisplayModal = useCallback(
    (courtId) => {
      if (!courtId) return;
      setActiveDisplayCourtId((prev) => {
        if (prev && prev !== courtId) postMessage("CLOSE_MODAL", prev);
        postMessage("OPEN_MODAL", courtId);
        postMessage("DISPLAY_FORCE_COURT");
        return courtId;
      });
    },
    [postMessage]
  );

  const closeDisplayModal = useCallback(
    (courtId) => {
      if (!courtId) return;
      postMessage("CLOSE_MODAL", courtId);
      setActiveDisplayCourtId((prev) => (prev === courtId ? null : prev));
    },
    [postMessage]
  );

  useEffect(() => {
    if (typeof window === "undefined" || !("BroadcastChannel" in window)) return;
    const bc = new BroadcastChannel("dink_manager");
    bc.onmessage = (event) => {
      const { type, courtId } = event?.data || {};
      if (type === "OPEN_MODAL") setActiveDisplayCourtId(courtId || null);
      if (type === "CLOSE_MODAL") {
        setActiveDisplayCourtId((prev) => (prev === courtId ? null : prev));
      }
    };
    return () => bc.close();
  }, []);

  if (!courts.length) {
    return (
      <div className="rounded-xl border border-dashed border-slate-200 bg-white/70 px-4 py-6 text-center text-sm text-slate-400">
        No courts yet. Use + Add Court to create one.
      </div>
    );
  }

  return (
    <div className="flex gap-3 overflow-x-auto pb-1 custom-scrollbar flex-wrap xl:flex-nowrap">
      {courts.map((court, index) => (
        <CompactCourtCard
          key={court.id}
          court={court}
          players={players}
          matches={matches}
          onAssign={onAssign}
          onRemove={onRemove}
          onUnlockCourt={onUnlockCourt}
          onUpdateCourtName={onUpdateCourtName}
          onRemoveCourt={onRemoveCourt}
          onCompleteMatch={onCompleteMatch}
          isDefault={index === 0}
          isDisplayOpen={playerIdKey(activeDisplayCourtId) === playerIdKey(court.id)}
          onDisplayOpen={openDisplayModal}
          onDisplayClose={closeDisplayModal}
          onRequestMove={onRequestMove}
          onReturnToQueue={onReturnToQueue}
          teamsModeEnabled={teamsModeEnabled}
          teams={teams}
          teamsSettings={teamsSettings}
        />
      ))}
    </div>
  );
}
