import { FACILITY_ID, apiRequest } from "./client";

export function verifyLockPin(pin) {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/verify-pin`, {
    method: "POST",
    body: { pin },
    fallbackError: "Could not verify PIN",
  });
}

export function changeLockPin({ oldPin, newPin, confirmPin }) {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/pin`, {
    method: "PUT",
    body: { oldPin, newPin, confirmPin },
    fallbackError: "Could not change PIN",
  });
}
