import { buildTeamsAutoQueue } from "./teamsAutoQueue";

export const MIN_WAIT_FOR_PRIORITY = 13;
export const MAX_GROUP_SIZE = 4;
export const MATCH_INTERVAL_MS = 20 * 60 * 1000;
export const MAX_THEORETICAL_SCORE = 107;
export const MAX_LATE_HANDICAP = 3;

const LEVEL_RANK = {
  Newbie: 0,
  Beginner: 1,
  "L.Inter": 2,
  "H.Inter": 3,
  Advance: 4,
  "Low Intermediate": 2,
  "High Intermediate": 3,
};

const PAIR_CHECK_LABEL = "Recent pair history";
const toId = (v) => String(v);
const byTimeAsc = (a, b) => (a.startTime ?? 0) - (b.startTime ?? 0);

const normalizeStatuses = (status) => String(status || "").toLowerCase().trim();
const rank = (lvl) => LEVEL_RANK[lvl] ?? 2;
const variance = (nums = []) => {
  if (!nums.length) return 0;
  const mean = nums.reduce((s, n) => s + n, 0) / nums.length;
  return nums.reduce((s, n) => s + (n - mean) ** 2, 0) / nums.length;
};

const combinations4 = (list) => {
  const out = [];
  for (let i = 0; i < list.length - 3; i += 1) {
    for (let j = i + 1; j < list.length - 2; j += 1) {
      for (let k = j + 1; k < list.length - 1; k += 1) {
        for (let l = k + 1; l < list.length; l += 1) {
          out.push([list[i], list[j], list[k], list[l]]);
        }
      }
    }
  }
  return out;
};

const pairPenalty = (matchesAgo) => {
  if (matchesAgo == null) return 0;
  if (matchesAgo === 0) return 100;
  if (matchesAgo === 1) return 70;
  if (matchesAgo === 2) return 40;
  if (matchesAgo === 3) return 20;
  // 4+ matches ago should be treated as green / no warning.
  return 0;
};

const buildPairMatrix = (pastMatches = []) => {
  const matrix = {};
  const ordered = [...pastMatches]
    .filter((match) => match?.status === "completed")
    .sort(byTimeAsc)
    .reverse();
  ordered.forEach((match, idx) => {
    const ids = (match?.lineup || []).map((p) => toId(p.id)).filter(Boolean);
    for (let i = 0; i < ids.length - 1; i += 1) {
      for (let j = i + 1; j < ids.length; j += 1) {
        const a = ids[i];
        const b = ids[j];
        if (!matrix[a]) matrix[a] = {};
        if (!matrix[b]) matrix[b] = {};
        if (matrix[a][b] == null || idx < matrix[a][b]) {
          matrix[a][b] = idx;
          matrix[b][a] = idx;
        }
      }
    }
  });
  return matrix;
};

const buildPairEncounterCounts = (matches = []) => {
  const counts = {};
  matches.forEach((match) => {
    if (!match || match.status !== "completed") return;
    const ids = (match?.lineup || []).map((p) => toId(p.id)).filter(Boolean);
    for (let i = 0; i < ids.length - 1; i += 1) {
      for (let j = i + 1; j < ids.length; j += 1) {
        const a = ids[i];
        const b = ids[j];
        if (!counts[a]) counts[a] = {};
        if (!counts[b]) counts[b] = {};
        counts[a][b] = (counts[a][b] || 0) + 1;
        counts[b][a] = (counts[b][a] || 0) + 1;
      }
    }
  });
  return counts;
};

const describeAgo = (matchesAgo) => {
  if (matchesAgo === 0) return "last match";
  if (matchesAgo === 1) return "1 match ago";
  return `${matchesAgo} matches ago`;
};

export const buildChecks = (ctx) => {
  const {
    genderOk,
    levelOk,
    repeatCheck,
    pairHardBlock,
    pairWarnings,
    pairEncounters,
    hasPriorityInPool,
    hasPriorityInGroup,
    fairnessValues,
    levelSpread,
  } = ctx;

  return [
    {
      id: "level",
      label: "Level spread",
      status: levelOk ? "pass" : "fail",
      reason: levelOk
        ? `Level spread is within tolerance (${levelSpread}).`
        : `Level spread is too wide (${levelSpread}).`,
    },
    {
      id: "gender",
      label: "Gender composition",
      status: genderOk ? "pass" : "fail",
      reason: genderOk
        ? "Valid composition (4M, 4F, or 2M+2F)."
        : "Composition must be 4M, 4F, or 2M+2F.",
    },
    {
      id: "repeat",
      label: "Repeat history",
      status: repeatCheck.ok ? "pass" : "fail",
      reason: repeatCheck.reason,
      ...(repeatCheck.violatingPlayers?.length ? { violatingPlayers: repeatCheck.violatingPlayers } : {}),
    },
    {
      id: "pairs",
      label: PAIR_CHECK_LABEL,
      status: pairHardBlock ? "fail" : pairWarnings.length ? "warn" : "pass",
      reason: pairHardBlock
        ? pairHardBlock.reason
        : pairWarnings.length
          ? `${pairWarnings.length} recent pair overlap warning(s).`
          : "No problematic recent pair overlap.",
      ...(pairHardBlock?.violatingPair ? { violatingPair: pairHardBlock.violatingPair } : {}),
      ...(pairWarnings.length ? { pairWarnings } : {}),
      ...(pairEncounters.length ? { pairEncounters } : {}),
    },
    {
      id: "priority",
      label: "Priority waiting",
      status: hasPriorityInPool && !hasPriorityInGroup ? "fail" : "pass",
      reason: hasPriorityInPool
        ? hasPriorityInGroup
          ? "A priority waiter (13m+) is included."
          : "Priority waiter exists but was not included."
        : "No priority waiters in pool.",
    },
    {
      id: "fairness",
      label: "Fairness",
      status: "pass",
      reason: `Effective matches: ${fairnessValues.join(", ")} (late-arrival handicap included).`,
    },
  ];
};

export function buildAutoQueue(
  players,
  {
    mode = "open",
    maxGroupSize = MAX_GROUP_SIZE,
    pastMatches = [],
    excludeIds = [],
    partners = [],
    sessionStartTime = null,
    sessionMatchIds = new Set(),
    excludeGroups = [],
    teams = [],
    teamsSettings,
  } = {}
) {
  if (mode === "teams") {
    return buildTeamsAutoQueue(players, {
      pastMatches,
      excludeIds,
      sessionStartTime,
      sessionMatchIds,
      excludeGroups,
      teams,
      teamsSettings,
    });
  }

  const now = Date.now();
  const diagnostics = {
    total: players.length,
    notWaiting: 0,
    excluded: 0,
    partnerBusy: 0,
    ok: 0,
    totalCombinationsChecked: 0,
    validCombinationsFound: 0,
  };

  const excludeSet = new Set((excludeIds || []).map(toId));
  const excludeGroupSet = new Set((excludeGroups || []).map((ids) => ids.map(toId).sort().join("|")));
  const playersById = new Map(players.map((p) => [toId(p.id), p]));
  const activePartners = new Map();
  (partners || []).forEach((rel) => {
    if (!rel?.isActive) return;
    activePartners.set(toId(rel.player1Id), toId(rel.player2Id));
    activePartners.set(toId(rel.player2Id), toId(rel.player1Id));
  });

  const arrivals = players
    .map((p) => p.arrivalTime)
    .filter((value) => typeof value === "number" && value > 0);
  const derivedSessionStart = arrivals.length ? Math.min(...arrivals) : now;
  const sessionStart = sessionStartTime ?? derivedSessionStart;

  const pool = players
    .filter((p) => {
      if (normalizeStatuses(p.status) !== "waiting") {
        diagnostics.notWaiting += 1;
        return false;
      }
      if (excludeSet.has(toId(p.id))) {
        diagnostics.excluded += 1;
        return false;
      }
      const partnerId = activePartners.get(toId(p.id));
      if (partnerId) {
        const partner = playersById.get(partnerId);
        if (!partner || normalizeStatuses(partner.status) !== "waiting") {
          diagnostics.partnerBusy += 1;
          return false;
        }
      }
      diagnostics.ok += 1;
      return true;
    })
    .map((p) => {
      const wait = p.waitStart ? Math.max(0, Math.floor((now - p.waitStart) / 60000)) : 0;
      const lateHandicap =
        typeof p.arrivalTime === "number" && p.arrivalTime > 0
          ? Math.min(
              MAX_LATE_HANDICAP,
              Math.max(0, Math.floor((p.arrivalTime - sessionStart) / MATCH_INTERVAL_MS))
            )
          : 0;
      const matches = p.matches ?? 0;
      return {
        ...p,
        _wait: wait,
        _matches: matches,
        _lateHandicap: lateHandicap,
        _effectiveMatches: matches + lateHandicap,
      };
    });
  const poolIdSet = new Set(pool.map((p) => toId(p.id)));

  if (pool.length < maxGroupSize) {
    return {
      success: false,
      groupIds: [],
      usedPlayers: [],
      confidencePct: 0,
      checks: [{
        id: "pool_size",
        label: "Enough players waiting",
        status: "fail",
        reason: `Only ${pool.length} eligible player(s) - need at least 4.`,
      }],
      pairWarnings: [],
      reason: `Not enough players (${pool.length} of 4 needed)`,
      diagnostics,
    };
  }

  const pairMatrix = buildPairMatrix(pastMatches);
  const pairEncounterCounts = buildPairEncounterCounts(pastMatches);
  const completedMatches = pastMatches.filter((match) => match?.status === "completed");
  const combos = combinations4(pool).filter((group) => {
    const key = group.map((p) => toId(p.id)).sort().join("|");
    return !excludeGroupSet.has(key);
  });

  if (!combos.length) {
    return {
      success: false,
      groupIds: [],
      usedPlayers: [],
      confidencePct: 0,
      checks: [{
        id: "no_combos",
        label: "Combination search",
        status: "fail",
        reason: "No unseen 4-player combinations available.",
      }],
      pairWarnings: [],
      reason: "No combinations available after exclusions.",
      diagnostics,
    };
  }

  let bestValid = null;
  let bestAttempt = null;
  const hasPriorityInPool = pool.some((p) => p._wait >= MIN_WAIT_FOR_PRIORITY);
  const validComparator = (a, b) => {
    // Hybrid wait priority:
    // 1) Always reward longer waits (continuous).
    // 2) Reward count of 13m+ priority waiters as an additional boost.
    if (a.maxWait !== b.maxWait) return a.maxWait > b.maxWait;
    if (a.sumWait !== b.sumWait) return a.sumWait > b.sumWait;
    if (a.priorityCount !== b.priorityCount) return a.priorityCount > b.priorityCount;

    // Keep match-count fairness as secondary tie-breakers.
    if (a.maxEffective !== b.maxEffective) return a.maxEffective < b.maxEffective;
    if (a.sumEffective !== b.sumEffective) return a.sumEffective < b.sumEffective;
    return a.totalScore > b.totalScore;
  };

  combos.forEach((group) => {
    diagnostics.totalCombinationsChecked += 1;
    const ids = group.map((p) => toId(p.id));
    const idSet = new Set(ids);
    const namesById = new Map(group.map((p) => [toId(p.id), p.name]));
    const hasPartnerMismatch = ids.some((id) => {
      const partnerId = activePartners.get(id);
      if (!partnerId) return false;
      // If partner is in eligible pool, they must be in the same group.
      return poolIdSet.has(partnerId) && !idSet.has(partnerId);
    });

    const men = group.filter((p) => p.gender === "M").length;
    const women = group.filter((p) => p.gender === "F").length;
    const genderOk = (men === 4 && women === 0) || (men === 0 && women === 4) || (men === 2 && women === 2);

    const levelRanks = group.map((p) => rank(p.level));
    const levelSpread = Math.max(...levelRanks) - Math.min(...levelRanks);
    const levelOk = levelSpread <= 1;

    let repeatCheck = { ok: true, reason: "No hard repeat conflicts." };
    for (const match of completedMatches) {
      const matchIds = new Set((match?.lineup || []).map((p) => toId(p.id)));
      const overlapping = ids.filter((id) => matchIds.has(id));
      if (sessionMatchIds?.has?.(match.id) && overlapping.length >= 4) {
        const violators = overlapping.map((id) => namesById.get(id) || id);
        repeatCheck = {
          ok: false,
          reason: `Exact 4-player repeat detected in this session: ${violators.join(", ")}.`,
          violatingPlayers: violators,
        };
        break;
      }
      if (sessionMatchIds?.has?.(match.id) && overlapping.length >= 3) {
        const violators = overlapping.map((id) => namesById.get(id) || id);
        repeatCheck = {
          ok: false,
          reason: `Same-session 3-player overlap: ${violators.join(", ")}.`,
          violatingPlayers: violators,
        };
        break;
      }
    }

    let pairHardBlock = null;
    const pairWarnings = [];
    const pairEncounters = [];
    if (hasPartnerMismatch) {
      const mismatchPlayer = ids.find((id) => {
        const partnerId = activePartners.get(id);
        return partnerId && poolIdSet.has(partnerId) && !idSet.has(partnerId);
      });
      const mismatchPartnerId = activePartners.get(mismatchPlayer);
      pairHardBlock = {
        violatingPair: [namesById.get(mismatchPlayer) || mismatchPlayer, namesById.get(mismatchPartnerId) || mismatchPartnerId],
        reason: `Fixed partners must be queued together: ${(namesById.get(mismatchPlayer) || mismatchPlayer)} and ${(namesById.get(mismatchPartnerId) || mismatchPartnerId)}.`,
      };
    }
    for (let i = 0; i < ids.length - 1; i += 1) {
      for (let j = i + 1; j < ids.length; j += 1) {
        const idA = ids[i];
        const idB = ids[j];
        const isFixedPartnerPair = activePartners.get(idA) === idB && activePartners.get(idB) === idA;
        if (isFixedPartnerPair) {
          // Fixed partners are exempt from pair-repeat cooldown and penalties.
          continue;
        }
        const encounterCount = pairEncounterCounts[idA]?.[idB] || 0;
        if (encounterCount > 0) {
          pairEncounters.push({
            idA,
            idB,
            nameA: namesById.get(idA) || idA,
            nameB: namesById.get(idB) || idB,
            encounterCount,
          });
        }

        // Maximum allowed pairings is 2. Third encounter is blocked.
        if (encounterCount >= 2 && !pairHardBlock) {
          pairHardBlock = {
            violatingPair: [namesById.get(idA) || idA, namesById.get(idB) || idB],
            reason: `${namesById.get(idA) || idA} and ${namesById.get(idB) || idB} already played together ${encounterCount} times (max 2).`,
          };
        }
        const ago = pairMatrix[idA]?.[idB];
        if (ago == null) continue;
        const penalty = pairPenalty(ago);
        const warning = {
          idA,
          idB,
          nameA: namesById.get(idA) || idA,
          nameB: namesById.get(idB) || idB,
          encounterCount,
          matchesAgo: ago,
          penalty,
        };
        if (ago <= 2 && !pairHardBlock) {
          pairHardBlock = {
            violatingPair: [warning.nameA, warning.nameB],
            reason: `${warning.nameA} and ${warning.nameB} played together ${describeAgo(ago)}.`,
          };
        }
        if (penalty > 0) pairWarnings.push(warning);
      }
    }

    const fairnessValues = group.map((p) => p._effectiveMatches);
    const fairnessScore = 1 / (1 + variance(fairnessValues));
    const rawWaitScore = Math.min(group.reduce((sum, p) => sum + p._wait, 0) / 60, 1);
    const hasPriorityInGroup = group.some((p) => p._wait >= MIN_WAIT_FOR_PRIORITY);
    const longWaitBonus = hasPriorityInGroup ? 0.3 : 0;
    const longWaitPenalty = hasPriorityInPool && !hasPriorityInGroup ? -0.5 : 0;
    const waitScore = rawWaitScore + longWaitBonus + longWaitPenalty;
    const pairPenaltySum = pairWarnings.reduce((sum, w) => sum + w.penalty, 0);
    const pairDiversityScore = Math.max(0, (600 - pairPenaltySum) / 600);
    const levelScore = Math.max(0, (2 - levelSpread) / 2);
    const totalScore = fairnessScore * 30 + waitScore * 25 + pairDiversityScore * 35 + levelScore * 10;
    const priorityCount = group.filter((p) => p._wait >= MIN_WAIT_FOR_PRIORITY).length;
    const maxWait = Math.max(...group.map((p) => p._wait));
    const sumWait = group.reduce((sum, p) => sum + p._wait, 0);

    const checks = buildChecks({
      genderOk,
      levelOk,
      repeatCheck,
      pairHardBlock,
      pairWarnings,
      pairEncounters,
      hasPriorityInPool,
      hasPriorityInGroup,
      fairnessValues,
      levelSpread,
    });

    const isValid = genderOk && levelOk && repeatCheck.ok && !pairHardBlock;
    const candidate = {
      success: isValid,
      groupIds: group.map((p) => p.id),
      usedPlayers: group,
      confidencePct: isValid ? Math.round(Math.min(100, (totalScore / MAX_THEORETICAL_SCORE) * 100)) : 0,
      checks,
      pairWarnings,
      reason: "",
      diagnostics: {
        ...diagnostics,
      },
      totalScore,
      maxEffective: Math.max(...fairnessValues),
      sumEffective: fairnessValues.reduce((a, b) => a + b, 0),
      priorityCount,
      maxWait,
      sumWait,
      idSet,
    };

    if (isValid) {
      diagnostics.validCombinationsFound += 1;
      if (!bestValid || validComparator(candidate, bestValid)) bestValid = candidate;
      return;
    }
    const failedChecksCount = checks.filter((check) => check.status === "fail").length;
    candidate.failedChecksCount = failedChecksCount;

    if (
      !bestAttempt ||
      candidate.failedChecksCount < bestAttempt.failedChecksCount ||
      (candidate.failedChecksCount === bestAttempt.failedChecksCount &&
        candidate.totalScore > bestAttempt.totalScore)
    ) {
      bestAttempt = candidate;
    }
  });

  if (bestValid) {
    return {
      success: true,
      groupIds: bestValid.groupIds,
      usedPlayers: bestValid.usedPlayers,
      confidencePct: bestValid.confidencePct,
      checks: bestValid.checks,
      pairWarnings: bestValid.pairWarnings,
      reason: `Match found after checking ${diagnostics.totalCombinationsChecked} combinations.`,
      diagnostics,
    };
  }

  if (bestAttempt) {
    return {
      success: false,
      groupIds: bestAttempt.groupIds,
      usedPlayers: bestAttempt.usedPlayers,
      confidencePct: 0,
      checks: bestAttempt.checks,
      pairWarnings: bestAttempt.pairWarnings,
      reason: `No clean match found after checking ${diagnostics.totalCombinationsChecked} combinations. Showing best available conflicted group.`,
      diagnostics,
    };
  }

  return {
    success: false,
    groupIds: [],
    usedPlayers: [],
    confidencePct: 0,
    checks: [{
      id: "no_combos",
      label: "Combination search",
      status: "fail",
      reason: "No combinations available.",
    }],
    pairWarnings: [],
    reason: "No combinations available.",
    diagnostics,
  };
}
