import { APP_STORAGE_KEY } from "./storage";
import config from "../config";

const buildCourts = () => (config.calendar?.courts || ["Court 1", "Court 2", "Court 3", "Court 4", "Court 5"]).map((name, idx) => ({
    id: idx + 1,
    name,
    players: [],
    teamGreen: [],
    teamBlue: [],
    timer: { startTime: null, accumulatedMs: 0, isPaused: false },
    currentMatchId: null,
    locked: false,
}));

export const seedDemoData = () => {
    const now = Date.now();

    // Create 12 Demo Players
    const players = Array.from({ length: 12 }, (_, i) => ({
        id: `demo-player-${i + 1}`,
        name: `Player ${i + 1}`,
        level: i % 4 === 0 ? "Advance" : i % 3 === 0 ? "Intermediate" : i % 2 === 0 ? "Beginner" : "Newbie",
        gender: i % 2 === 0 ? "M" : "F",
        status: "waiting", // Default to waiting
        paymentStatus: "paid",
        paymentMethod: "cash",
        isMember: false,
        price: config.pricing?.openPlayRate || 200,
        createdAt: now,
        arrivalTime: now - Math.floor(Math.random() * 60 * 60 * 1000), // Arrived 0-60 mins ago
        matches: Math.floor(Math.random() * 3), // 0-2 matches already played
        longestWaitTimeMs: 0,
    }));

    const courts = buildCourts();
    const calendarCourts = buildCourts();

    return {
        players,
        courts,
        calendarCourts,
        matchQueue: [],
        matches: [],
        opSessions: [],
        bookings: [],
        currentOpSession: {
            id: `demo-session-${now}`,
            name: "Demo Session",
            startedAt: now,
            status: "active"
        }
    };
};

export const resetDemoData = () => {
    return seedDemoData();
};
export const seedIfEmpty = () => {
    try {
        const stored = localStorage.getItem(APP_STORAGE_KEY);
        if (!stored) {
            console.log("No state found. Initializing with default defaults...");

            // CLEAN STATE
            const cleanState = {
                players: [],
                matchQueue: [],
                matches: [],
                opSessions: [],
                bookings: [],
                currentOpSession: null,
                isDemoMode: false, // Default OFF

                courts: buildCourts(),
                calendarCourts: buildCourts(),

                meta: { seededAt: Date.now(), seedLabel: "Clean Init" }
            };

            localStorage.setItem(APP_STORAGE_KEY, JSON.stringify(cleanState));
        }
    } catch (e) {
        console.error("Failed to seedIfEmpty:", e);
    }
};

