/**
 * Shared schema utilities for the persisted application state.
 *
 * Keep additions backwards compatible by bumping the CURRENT_STATE_VERSION
 * and documenting the change in docs/schema-history.md.
 */

export const CURRENT_STATE_VERSION = 4;

export function normalizeStateMeta(meta = {}) {
  return {
    stateVersion: meta.stateVersion || CURRENT_STATE_VERSION,
    seededAt: meta.seededAt || null,
    seedSource: meta.seedSource || null,
    seedLabel: meta.seedLabel || null,
    lastSavedAt: meta.lastSavedAt || null,
    revision:
      typeof meta.revision === "number" && Number.isFinite(meta.revision)
        ? meta.revision
        : 0,
    migrations:
      meta.migrations && typeof meta.migrations === "object"
        ? { ...meta.migrations }
        : {},
  };
}

export function buildStateMeta(overrides = {}) {
  const timestamp = overrides.lastSavedAt || new Date().toISOString();
  return normalizeStateMeta({
    ...overrides,
    lastSavedAt: timestamp,
    stateVersion: overrides.stateVersion || CURRENT_STATE_VERSION,
  });
}

export function withStateEnvelope(state = {}, overrides = {}) {
  const meta = buildStateMeta({
    ...(state.meta || {}),
    ...overrides,
  });

  return {
    ...state,
    meta,
    version: CURRENT_STATE_VERSION,
  };
}

export const STATE_SHAPE = {
  settings: "ClubSettings",
  courts: "Court[]",
  players: "Player[]",
  matchQueue: "MatchQueueEntry[]",
  matches: "Match[]",
  currentOpSession: "OpSession | null",
  opSessions: "OpSession[]",
  recentHold: "{ epoch: number, dismissedMatchIds: string[], releasedByMatch: { [matchId]: string[] } }",
  bookings: "Booking[]",
  calendarCourts: "CalendarCourt[]",
};

export function describeStateSchema() {
  return Object.entries(STATE_SHAPE).map(([key, type]) => `${key}: ${type}`);
}
