import React, { useState } from "react";
import toast from "react-hot-toast";
import {
  DEFAULT_DISPLAY_ROTATION,
  normalizeDisplayRotation,
} from "../../../common/utils/settingsDefaults";

const VIEW_OPTIONS = [
  { key: "nextUp", label: "Next Up" },
  { key: "leaderboard", label: "Podium" },
  { key: "sponsor", label: "Ad" },
];

function isHttpUrl(value) {
  return /^https?:\/\//i.test(String(value || "").trim());
}

function AddSponsorsModal({ open, onClose, sponsors, onSave, disabled }) {
  const [name, setName] = useState("");
  const [url, setUrl] = useState("");

  if (!open) return null;

  const handleAdd = () => {
    const trimmedUrl = url.trim();
    const trimmedName = name.trim() || "Sponsor";
    if (!isHttpUrl(trimmedUrl)) {
      toast.error("Use a public http(s) image URL (JPG, PNG, WebP, etc.)");
      return;
    }
    onSave([
      ...sponsors,
      { id: `sp-${Date.now()}`, name: trimmedName, url: trimmedUrl },
    ]);
    setName("");
    setUrl("");
    toast.success("Sponsor added");
  };

  return (
    <div className="fixed inset-0 z-[250] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-xl max-w-md w-full max-h-[85vh] flex flex-col border border-slate-200">
        <div className="px-4 py-3 border-b border-slate-100 flex justify-between items-center">
          <h2 className="text-sm font-bold text-slate-900">Sponsors</h2>
          <button type="button" className="text-slate-400 hover:text-slate-600" onClick={onClose}>
            ×
          </button>
        </div>
        <div className="p-4 space-y-3 overflow-y-auto flex-1">
          <p className="text-[10px] text-slate-500 leading-snug">
            Image URL must be a public link starting with http:// or https:// (e.g. .jpg or .png hosted
            online).
          </p>
          <input
            type="text"
            disabled={disabled}
            placeholder="Display name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="w-full border border-slate-200 rounded-md px-2 py-1.5 text-xs"
          />
          <input
            type="url"
            disabled={disabled}
            placeholder="https://…/image.jpg"
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            className="w-full border border-slate-200 rounded-md px-2 py-1.5 text-xs"
          />
          <button
            type="button"
            disabled={disabled}
            onClick={handleAdd}
            className="w-full py-1.5 rounded-md text-xs font-bold bg-pt-teal text-white hover:bg-pt-teal/90 disabled:opacity-40"
          >
            Add to list
          </button>
          {sponsors.length > 0 && (
            <table className="w-full text-[10px]">
              <thead>
                <tr className="text-left text-slate-400 uppercase">
                  <th className="pb-1">Name</th>
                  <th className="pb-1">URL</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {sponsors.map((s) => (
                  <tr key={s.id} className="border-t border-slate-100">
                    <td className="py-1.5 pr-2 font-medium text-slate-800 max-w-[80px] truncate">
                      {s.name}
                    </td>
                    <td className="py-1.5 pr-2 text-slate-500 truncate max-w-[140px]" title={s.url}>
                      {s.url}
                    </td>
                    <td className="py-1.5 text-right">
                      <button
                        type="button"
                        disabled={disabled}
                        className="text-rose-600 font-bold hover:underline"
                        onClick={() =>
                          onSave(sponsors.filter((x) => x.id !== s.id))
                        }
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
        <div className="px-4 py-3 border-t border-slate-100">
          <button
            type="button"
            onClick={onClose}
            className="w-full py-1.5 rounded-md text-xs font-bold bg-slate-100 text-slate-700 hover:bg-slate-200"
          >
            Done
          </button>
        </div>
      </div>
    </div>
  );
}

export default function DisplayControlsPanel({
  displayRotation,
  onUpdate,
  onResumeRotation,
  disabled = false,
}) {
  const rot = normalizeDisplayRotation(displayRotation || DEFAULT_DISPLAY_ROTATION);
  const [sponsorsOpen, setSponsorsOpen] = useState(false);
  const sponsorCount = (rot.sponsors || []).length;

  const patch = (partial) => {
    onUpdate?.(partial);
  };

  const toggleView = (key) => {
    if (key === "sponsor") {
      const next = !rot.enabledViews.sponsor;
      if (next && sponsorCount === 0) {
        setSponsorsOpen(true);
        toast("Add at least one sponsor image", { icon: "ℹ️" });
        return;
      }
      patch({
        enabledViews: { ...rot.enabledViews, sponsor: next && sponsorCount > 0 },
      });
      return;
    }
    patch({
      enabledViews: {
        ...rot.enabledViews,
        [key]: !rot.enabledViews[key],
      },
    });
  };

  const saveSponsors = (list) => {
    patch({
      sponsors: list,
      enabledViews: {
        ...rot.enabledViews,
        sponsor: list.length > 0 && rot.enabledViews.sponsor,
      },
    });
  };

  return (
    <>
      <div className="h-full min-h-0 flex flex-col gap-1">
        <button
          type="button"
          disabled={disabled}
          onClick={() => {
            onResumeRotation?.();
            toast.success("Display rotation resumed");
          }}
          className="w-full px-2 py-1.5 rounded-md text-[11px] font-bold bg-pt-teal text-white hover:bg-pt-teal/90 disabled:opacity-40 shrink-0"
        >
          Resume Transition
        </button>

        <div className="grid grid-cols-3 gap-1 shrink-0">
          {VIEW_OPTIONS.map((opt) => (
            <label
              key={opt.key}
              className="flex items-center justify-center gap-1 rounded-md border border-slate-200 bg-slate-50 px-1 py-1 cursor-pointer hover:border-pt-teal/40 min-w-0"
              title={opt.key === "sponsor" ? "Sponsor ads" : opt.label}
            >
              <input
                type="checkbox"
                checked={!!rot.enabledViews[opt.key]}
                disabled={disabled}
                onChange={() => toggleView(opt.key)}
                className="rounded border-slate-300 text-pt-teal focus:ring-pt-teal h-3 w-3 shrink-0"
              />
              <span className="font-bold text-slate-800 truncate text-[10px]">{opt.label}</span>
            </label>
          ))}
        </div>

        <div className="grid grid-cols-2 gap-1 shrink-0">
          <label
            className="flex flex-col gap-0 rounded-md border border-slate-200 bg-white px-1.5 py-0.5"
            title="Seconds for Normal, Podium, Next Up"
          >
            <span className="text-[8px] font-bold uppercase tracking-wide text-slate-400">View sec</span>
            <input
              type="number"
              min={3}
              max={120}
              disabled={disabled}
              value={rot.rotationSeconds}
              onChange={(e) => patch({ rotationSeconds: Number(e.target.value) || 10 })}
              className="w-full border-0 bg-transparent px-0 py-0 text-[12px] font-mono font-bold text-slate-800 outline-none leading-tight"
            />
          </label>
          <label
            className="flex flex-col gap-0 rounded-md border border-slate-200 bg-white px-1.5 py-0.5"
            title="Seconds per sponsor image"
          >
            <span className="text-[8px] font-bold uppercase tracking-wide text-slate-400">Ad sec</span>
            <input
              type="number"
              min={3}
              max={120}
              disabled={disabled}
              value={rot.adTransitionSeconds}
              onChange={(e) => patch({ adTransitionSeconds: Number(e.target.value) || 5 })}
              className="w-full border-0 bg-transparent px-0 py-0 text-[12px] font-mono font-bold text-slate-800 outline-none leading-tight"
            />
          </label>
        </div>

        <button
          type="button"
          disabled={disabled}
          onClick={() => setSponsorsOpen(true)}
          className="w-full px-2 py-1 rounded-md text-[10px] font-bold border border-slate-200 text-slate-700 hover:bg-slate-50 shrink-0"
        >
          Add Sponsors{sponsorCount > 0 ? ` (${sponsorCount})` : ""}
        </button>
      </div>

      <AddSponsorsModal
        open={sponsorsOpen}
        onClose={() => setSponsorsOpen(false)}
        sponsors={rot.sponsors || []}
        onSave={saveSponsors}
        disabled={disabled}
      />
    </>
  );
}
