import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  DEFAULT_DISPLAY_ROTATION,
  normalizeDisplayRotation,
} from "../../../common/utils/settingsDefaults";

/** Cycle: Live Courts (normal) → Next Up → Leaderboards → Ads */
const OPTIONAL_VIEW_KEYS = ["nextUp", "leaderboard", "sponsor"];

/** Build flat rotation steps with per-step duration (View sec vs Ad sec). */
function buildRotationSteps(rot) {
  const viewMs = Math.max(3, rot.rotationSeconds || 10) * 1000;
  const adMs = Math.max(3, rot.adTransitionSeconds || 5) * 1000;
  const steps = [{ view: "normal", durationMs: viewMs }];

  OPTIONAL_VIEW_KEYS.forEach((key) => {
    if (!rot.enabledViews[key]) return;
    if (key === "sponsor") {
      (rot.sponsors || []).forEach((_, sponsorIndex) => {
        steps.push({ view: "sponsor", sponsorIndex, durationMs: adMs });
      });
      return;
    }
    steps.push({ view: key, durationMs: viewMs });
  });

  return steps.length ? steps : [{ view: "normal", durationMs: viewMs }];
}

/** Stable key so playlist rebuilds only when rotation settings actually change. */
function rotationSettingsKey(raw) {
  const rot = normalizeDisplayRotation(raw || DEFAULT_DISPLAY_ROTATION);
  const sponsorKey = (rot.sponsors || []).map((s) => `${s.id}:${s.url}`).join("|");
  return [
    rot.rotationSeconds,
    rot.adTransitionSeconds,
    rot.enabledViews.leaderboard ? 1 : 0,
    rot.enabledViews.nextUp ? 1 : 0,
    rot.enabledViews.sponsor ? 1 : 0,
    sponsorKey,
  ].join(";");
}

export function useDisplayRotation(displayRotation) {
  const settingsKey = rotationSettingsKey(displayRotation);

  const rot = useMemo(
    () => normalizeDisplayRotation(displayRotation || DEFAULT_DISPLAY_ROTATION),
    [settingsKey]
  );

  const steps = useMemo(() => buildRotationSteps(rot), [settingsKey, rot]);

  const [stepIndex, setStepIndex] = useState(0);
  const stepsRef = useRef(steps);
  const stepIndexRef = useRef(0);
  const prevSettingsKeyRef = useRef(settingsKey);

  useEffect(() => {
    stepsRef.current = steps;
    stepIndexRef.current = stepIndex;
  }, [steps, stepIndex]);

  // Reset index when playlist definition changes (not on every state sync object identity).
  useEffect(() => {
    if (prevSettingsKeyRef.current !== settingsKey) {
      prevSettingsKeyRef.current = settingsKey;
      setStepIndex(0);
      stepIndexRef.current = 0;
    } else if (stepIndex >= steps.length) {
      setStepIndex(0);
      stepIndexRef.current = 0;
    }
  }, [settingsKey, stepIndex, steps.length]);

  const currentStep = steps[stepIndex] || steps[0] || { view: "normal", durationMs: 10000 };
  const activeView = currentStep.view;
  const activeSponsorIndex = currentStep.sponsorIndex ?? 0;

  const advanceStep = useCallback(() => {
    const pl = stepsRef.current;
    if (pl.length <= 1) {
      setStepIndex(0);
      return;
    }
    setStepIndex((i) => (i + 1) % pl.length);
  }, []);

  const forceNormal = useCallback(() => {
    setStepIndex(0);
    stepIndexRef.current = 0;
  }, []);

  /** Resume: jump to next view and restart auto-rotation from there. */
  const resumeRotation = useCallback(() => {
    advanceStep();
  }, [advanceStep]);

  const forceCourt = forceNormal;

  // Auto-advance — depend on stepIndex + settingsKey only (not steps array identity).
  useEffect(() => {
    const idx = stepIndexRef.current;
    const step = stepsRef.current[idx] ?? stepsRef.current[0];
    if (!step) return undefined;

    const id = setTimeout(() => {
      const pl = stepsRef.current;
      if (pl.length <= 1) return;
      setStepIndex((i) => (i + 1) % pl.length);
    }, step.durationMs);

    return () => clearTimeout(id);
  }, [stepIndex, settingsKey]);

  const playlist = useMemo(() => steps.map((s) => s.view), [settingsKey, steps]);

  return {
    activeView,
    activeSponsorIndex,
    forceNormal,
    forceCourt,
    resumeRotation,
    playlist,
    rotation: rot,
    isPriority: false,
  };
}
