import React, { useCallback, useEffect, useMemo, useState } from "react";
import Select from "react-select";
import { MoreVertical, ArrowRightLeft, Undo2, Monitor, UserPlus, Megaphone } from "lucide-react";
import TeamBadge, { resolveTeamBadgeDisplay } from "./TeamBadge";
import { getPlayersOnCourt } from "../../../state/courtPlayers";
import { speak } from "../../../common/utils/tts";

const formatDuration = (ms) => {
  if (!ms || ms <= 0) return "00:00";
  const totalSeconds = Math.floor(ms / 1000);
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, "0");
  const seconds = (totalSeconds % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
};

const LEVEL_COLORS = {
  Newbie: "#94A3B8",
  Beginner: "#F59E0B",
  "L.Inter": "#22C55E",
  "H.Inter": "#3B82F6",
  Advance: "#8B5CF6",
  Intermediate: "#3B82F6",
};

const LEVEL_LETTERS = {
  Newbie: "N",
  Beginner: "B",
  "L.Inter": "L",
  "H.Inter": "H",
  Advance: "A",
  Intermediate: "H",
};

export default function CompactCourtCard({
  court,
  players,
  onAssign,
  onRemove,
  onUnlockCourt,
  onUpdateCourtName,
  onRemoveCourt,
  onCompleteMatch = () => {},
  isDisplayOpen = false,
  onDisplayOpen = () => {},
  onDisplayClose = () => {},
  isDefault = false,
  onRequestMove = () => {},
  onReturnToQueue = () => {},
  matches = [],
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
}) {
  const [changeOpen, setChangeOpen] = useState(false);
  const [selectedPlayer, setSelectedPlayer] = useState(null);
  const [optionsTick, setOptionsTick] = useState(0);

  const timer = useMemo(() => court?.timer || {}, [court.timer]);

  useEffect(() => {
    const id = setInterval(() => setOptionsTick((t) => t + 1), 30000);
    return () => clearInterval(id);
  }, []);

  const playersOnCourt = useMemo(
    () => getPlayersOnCourt(court, players),
    [court, players]
  );

  const courtTeamMeta = useMemo(() => {
    if (!court?.currentMatchId || !Array.isArray(matches)) return null;
    const m = matches.find((x) => x.id === court.currentMatchId);
    return m?.teamMeta && typeof m.teamMeta === "object" ? m.teamMeta : null;
  }, [court?.currentMatchId, matches]);

  const unassignedLabel = teamsSettings?.unassignedLabel ?? "Unassigned";

  const computeElapsedMs = useCallback(() => {
    const { startTime, lastResumedAt, accumulatedMs = 0, isPaused } = timer;
    if (!startTime) return 0;
    if (!isPaused && lastResumedAt) {
      return accumulatedMs + Math.max(0, Date.now() - lastResumedAt);
    }
    if (!isPaused && !lastResumedAt) {
      return Math.max(0, Date.now() - startTime);
    }
    return accumulatedMs;
  }, [timer]);

  const [elapsedMs, setElapsedMs] = useState(() => computeElapsedMs());

  useEffect(() => {
    setElapsedMs(computeElapsedMs());
    if (!timer.startTime || timer.isPaused) return undefined;
    const id = setInterval(() => setElapsedMs(computeElapsedMs()), 1000);
    return () => clearInterval(id);
  }, [computeElapsedMs, timer.isPaused, timer.startTime]);

  const waitMinutes = (player) => {
    if ((player.status === "waiting" || player.status === "queued") && player.waitStart) {
      return Math.floor((Date.now() - player.waitStart) / 60000);
    }
    return 0;
  };

  const waitingOptions = useMemo(() => {
    const refreshKey = optionsTick;
    return players
      .filter((p) => p.status === "waiting")
      .sort((a, b) => {
        const aWait = waitMinutes(a) + refreshKey * 0;
        const bWait = waitMinutes(b) + refreshKey * 0;
        if (aWait !== bWait) return bWait - aWait;
        if (a.matches !== b.matches) return a.matches - b.matches;
        return a.name.localeCompare(b.name);
      })
      .map((p) => ({
        value: p.id,
        label: p.name,
        level: p.level,
        matches: p.matches,
        wait: waitMinutes(p),
      }));
  }, [players, optionsTick]);

  const isFull = playersOnCourt.length >= 4;
  const isLocked = !!court.locked;
  const hasPlayers = playersOnCourt.length > 0;

  const handleAssign = useCallback(
    (option) => {
      if (!option || court.locked) return;
      onAssign(court.id, option.value);
      setSelectedPlayer(null);
    },
    [court.id, court.locked, onAssign]
  );

  const speakCourt = useCallback(
    (message) => {
      let text = message || "";
      if (!text) {
        if (playersOnCourt.length === 0) text = `${court.name} has no players.`;
        else text = `${court.name}. Players are: ${playersOnCourt.map((p) => p.name).join(", ")}.`;
      }
      const voiceName = localStorage.getItem("dm_voiceName") || "";
      const rate = Number(localStorage.getItem("dm_rate") || 0.9);
      const pitch = Number(localStorage.getItem("dm_pitch") || 1.0);
      speak(text, { voiceName, rate, pitch });
    },
    [court.name, playersOnCourt]
  );

  const handleEndGame = () => {
    speakCourt(`Game finished on ${court.name}`);
    onCompleteMatch(court.id);
  };

  return (
    <div
      className={`shrink-0 w-[260px] min-h-[168px] border rounded-xl p-2.5 bg-white shadow-sm flex flex-col gap-2 ${
        isLocked ? "border-amber-300 bg-amber-50/40" : "border-pt-teal/15"
      }`}
    >
      <div className="flex items-start justify-between gap-1">
        <div className="min-w-0">
          <input
            type="text"
            value={court.name}
            onChange={(e) => onUpdateCourtName(court.id, e.target.value)}
            onBlur={(e) => {
              if (!e.target.value.trim()) onUpdateCourtName(court.id, `Court ${court.id}`);
            }}
            className="font-bold text-sm text-pt-teal bg-transparent border-b border-transparent hover:border-pt-teal/20 focus:border-pt-teal focus:outline-none w-full max-w-[140px]"
          />
          <div className="text-[10px] font-mono text-slate-500 flex items-center gap-1.5 mt-0.5">
            <span>{formatDuration(elapsedMs)}</span>
            <span className="uppercase tracking-wide">
              {timer.startTime ? (timer.isPaused ? "Paused" : "Playing") : hasPlayers ? "Ready" : "Idle"}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-0.5 shrink-0">
          {hasPlayers && (
            <button
              type="button"
              onClick={() => speakCourt()}
              className="p-1 rounded-full text-slate-400 hover:text-pt-teal hover:bg-pt-teal/10 transition-colors"
              title="Call players on this court"
              aria-label="Call players"
            >
              <Megaphone className="h-3.5 w-3.5" />
            </button>
          )}
          <div className="relative group">
            <button
              type="button"
              className="p-1 rounded-full hover:bg-slate-100 text-slate-400 hover:text-slate-600"
              title="Court options"
            >
              <MoreVertical className="h-3.5 w-3.5" />
            </button>
            <div className="absolute right-0 top-full pt-1 z-20 hidden group-hover:block hover:block">
              <div className="w-40 bg-white rounded-lg shadow-lg border border-slate-100 overflow-hidden text-xs">
                {isLocked && (
                  <button
                    type="button"
                    onClick={() => onUnlockCourt?.(court.id)}
                    className="w-full text-left px-3 py-2 text-amber-700 hover:bg-amber-50"
                  >
                    Unlock court
                  </button>
                )}
                {!isDefault && (
                  <button
                    type="button"
                    onClick={() => {
                      if (isDisplayOpen) onDisplayClose(court.id);
                      onRemoveCourt(court.id);
                    }}
                    className="w-full text-left px-3 py-2 text-red-500 hover:bg-red-50 border-t border-slate-50"
                  >
                    Remove Court
                  </button>
                )}
                {!isLocked && isDefault && (
                  <div className="px-3 py-2 text-slate-400 italic">Default court</div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <ul className="grid grid-cols-2 gap-1 flex-1 min-h-0">
        {[0, 1, 2, 3].map((i) => {
          const p = playersOnCourt[i];
          if (!p) {
            return (
              <li
                key={`empty-${i}`}
                className="border border-dashed border-slate-200 rounded-md h-7 bg-slate-50/60"
              />
            );
          }
          const tb = resolveTeamBadgeDisplay(
            p,
            courtTeamMeta,
            teamsModeEnabled,
            teams,
            unassignedLabel
          );
          return (
            <li
              key={p.id}
              className={`flex items-center gap-1 rounded-md border px-1.5 h-7 text-[10px] ${
                p.gender === "F" ? "bg-pink-50 border-pink-100" : "bg-white border-slate-100"
              }`}
            >
              {tb ? (
                <TeamBadge letter={tb.letter} color={tb.color} title={tb.title} />
              ) : (
                <span
                  className="w-3.5 h-3.5 rounded-full shrink-0 inline-flex items-center justify-center text-white font-black"
                  style={{
                    fontSize: "0.45rem",
                    backgroundColor: LEVEL_COLORS[p.level] || "#94A3B8",
                  }}
                >
                  {LEVEL_LETTERS[p.level] || "L"}
                </span>
              )}
              <span className="truncate font-medium flex-1">{p.name}</span>
              {changeOpen && (
                <button
                  type="button"
                  className="text-red-400 hover:text-red-600 font-bold"
                  onClick={() => onRemove(court.id, p.id)}
                  title={`Remove ${p.name}`}
                >
                  ×
                </button>
              )}
            </li>
          );
        })}
      </ul>

      {changeOpen && !isFull && !isLocked && (
        <Select
          className="text-xs"
          isSearchable
          placeholder="+ Add waiting player"
          value={selectedPlayer}
          options={waitingOptions}
          onChange={handleAssign}
          menuPortalTarget={document.body}
          styles={{ menuPortal: (base) => ({ ...base, zIndex: 9999 }) }}
          classNames={{
            control: () => "!min-h-[28px] !rounded-md !text-xs !border-slate-200",
          }}
        />
      )}

      <div className="flex flex-col gap-1.5 mt-auto">
        <div className="flex gap-1.5">
          <button
            type="button"
            disabled={isLocked}
            onClick={() => setChangeOpen((v) => !v)}
            className={`flex-1 inline-flex items-center justify-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold ${
              changeOpen
                ? "bg-pt-teal text-white"
                : "bg-pt-teal/10 text-pt-teal hover:bg-pt-teal/20"
            } disabled:opacity-40`}
          >
            <UserPlus className="h-3 w-3" />
            Change Player
          </button>
          <button
            type="button"
            onClick={() => {
              if (isDisplayOpen) onDisplayClose(court.id);
              else onDisplayOpen(court.id);
            }}
            className={`flex-1 inline-flex items-center justify-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold ${
              isDisplayOpen
                ? "bg-emerald-600 text-white"
                : "bg-emerald-50 text-emerald-700 hover:bg-emerald-100"
            }`}
          >
            <Monitor className="h-3 w-3" />
            Display
          </button>
        </div>
        <div className="flex gap-1.5">
          <button
            type="button"
            disabled={!hasPlayers}
            onClick={() => onReturnToQueue(court.id)}
            className="flex-1 inline-flex items-center justify-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-blue-50 text-blue-700 hover:bg-blue-100 disabled:opacity-40"
          >
            <Undo2 className="h-3 w-3" />
            Back to Queue
          </button>
          <button
            type="button"
            disabled={!hasPlayers}
            onClick={() => onRequestMove(court.id)}
            className="flex-1 inline-flex items-center justify-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold bg-sky-50 text-sky-700 hover:bg-sky-100 disabled:opacity-40"
          >
            <ArrowRightLeft className="h-3 w-3" />
            Move Court
          </button>
          <button
            type="button"
            disabled={!hasPlayers}
            onClick={handleEndGame}
            className="flex-1 px-2 py-1 rounded-md text-[10px] font-bold bg-red-50 text-red-600 hover:bg-red-100 disabled:opacity-40"
          >
            End Game
          </button>
        </div>
      </div>
    </div>
  );
}
