/** Grid layout for display court cards — one column per court when possible. */
export function getDisplayCourtGrid(courtCount) {
  const n = Math.max(0, courtCount);
  if (n <= 0) return { cols: 1, rows: 1 };
  // Prefer a single horizontal row of court columns (matches TV wireframe).
  if (n <= 6) return { cols: n, rows: 1 };
  if (n <= 8) return { cols: Math.ceil(n / 2), rows: 2 };
  if (n <= 12) return { cols: 4, rows: Math.ceil(n / 4) };
  return { cols: 4, rows: Math.ceil(n / 4) };
}

/** Optional per-card grid placement (no special spans for equal columns). */
export function getDisplayCourtSpan(_courtCount, _index) {
  return null;
}
