import React, { useState } from "react";
import DisplayControlsPanel from "./DisplayControlsPanel";
import { openManagePopout } from "./PlayerManagementOverlay";

/**
 * Compact control card — same footprint as CompactCourtCard (260×~court height).
 */
export default function QueueSidePanel({
  quickAddName,
  setQuickAddName,
  quickAddGender,
  setQuickAddGender,
  onQuickAdd,
  onOpenReclub,
  onCloseDisplayModal,
  onAddCourt,
  sessionLocked = false,
  displayRotation,
  onUpdateDisplayRotation,
  onResumeDisplayRotation,
}) {
  const [tab, setTab] = useState("session");

  return (
    <div
      className="shrink-0 w-[260px] min-h-[168px] max-h-[220px] border border-pt-teal/15 rounded-xl p-2.5 bg-white shadow-sm flex flex-col gap-1.5 overflow-hidden"
    >
      <div className="flex rounded-md bg-slate-100 p-0.5 shrink-0">
        <button
          type="button"
          onClick={() => setTab("session")}
          className={`flex-1 px-1.5 py-1 rounded text-[10px] font-bold uppercase tracking-wide ${
            tab === "session" ? "bg-white text-pt-teal shadow-sm" : "text-slate-500 hover:text-slate-700"
          }`}
        >
          Session
        </button>
        <button
          type="button"
          onClick={() => setTab("display")}
          className={`flex-1 px-1.5 py-1 rounded text-[10px] font-bold uppercase tracking-wide ${
            tab === "display" ? "bg-white text-pt-teal shadow-sm" : "text-slate-500 hover:text-slate-700"
          }`}
        >
          Display
        </button>
      </div>

      <div className={`flex-1 min-h-0 ${tab === "display" ? "overflow-hidden" : "overflow-y-auto custom-scrollbar pr-0.5"}`}>
        {tab === "session" ? (
          <div className="flex flex-col gap-1.5">
            <input
              type="text"
              value={quickAddName}
              onChange={(e) => setQuickAddName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") onQuickAdd?.();
              }}
              disabled={sessionLocked}
              placeholder="Quick add…"
              className="border border-slate-200 rounded-md px-1.5 py-1 text-[10px] w-full focus:border-pt-teal focus:ring-1 focus:ring-pt-teal outline-none disabled:opacity-40"
            />
            <div className="flex gap-1">
              <select
                value={quickAddGender}
                onChange={(e) => setQuickAddGender(e.target.value)}
                disabled={sessionLocked}
                className="border border-slate-200 rounded-md px-1 py-1 text-[10px] flex-1 disabled:opacity-40"
              >
                <option value="M">M</option>
                <option value="F">F</option>
              </select>
              <button
                type="button"
                onClick={onQuickAdd}
                disabled={sessionLocked || !quickAddName?.trim()}
                className="flex-1 px-2 py-1 rounded-md text-[10px] font-bold bg-pt-teal text-white hover:bg-pt-teal/90 disabled:opacity-40"
              >
                + Add
              </button>
            </div>
            <div className="grid grid-cols-2 gap-1">
              <button
                type="button"
                disabled={sessionLocked}
                onClick={onOpenReclub}
                className="px-2 py-1 rounded-md text-[10px] font-bold bg-amber-700 text-white hover:bg-amber-800 disabled:opacity-40"
              >
                Reclub
              </button>
              <button
                type="button"
                disabled={sessionLocked}
                onClick={() => openManagePopout()}
                className="px-2 py-1 rounded-md text-[10px] font-bold border border-pt-teal/30 text-pt-teal hover:bg-pt-teal/5 disabled:opacity-40"
                title="Open Manage Players"
              >
                Manage
              </button>
              <button
                type="button"
                onClick={onCloseDisplayModal}
                className="px-2 py-1 rounded-md text-[10px] font-bold bg-amber-100 text-amber-800 hover:bg-amber-200"
              >
                Close Modal
              </button>
              <button
                type="button"
                disabled={sessionLocked}
                onClick={onAddCourt}
                className="px-2 py-1 rounded-md text-[10px] font-bold bg-pt-teal text-white hover:bg-pt-teal/90 disabled:opacity-40"
              >
                + Court
              </button>
            </div>
          </div>
        ) : (
          <DisplayControlsPanel
            displayRotation={displayRotation}
            onUpdate={onUpdateDisplayRotation}
            onResumeRotation={onResumeDisplayRotation}
            disabled={sessionLocked}
          />
        )}
      </div>
    </div>
  );
}
