import React, { useMemo } from "react";
import TeamBadge, { resolveTeamBadgeDisplay } from "./TeamBadge";

const levelEmoji = {
  Newbie: "⚪",
  Beginner: "🟡",
  "L.Inter": "🟢",
  "H.Inter": "🔵",
  Advance: "🟣",
};

const statusStyle = {
  pass: "text-emerald-700 bg-emerald-50 border-emerald-100",
  warn: "text-amber-700 bg-amber-50 border-amber-100",
  fail: "text-red-700 bg-red-50 border-red-100",
};

const statusIcon = { pass: "✓", warn: "⚠", fail: "✕" };

const confidenceLabel = (pct, success) => {
  if (!success) return "Conflicted fallback";
  if (pct >= 80) return "Excellent match";
  if (pct >= 50) return "Good match";
  if (pct >= 25) return "Acceptable match";
  return "Poor match - waiting recommended";
};

const confidenceColor = (pct) => {
  if (pct >= 75) return "bg-emerald-500";
  if (pct >= 50) return "bg-amber-500";
  if (pct >= 25) return "bg-orange-500";
  return "bg-red-500";
};

const PlayerCard = ({ p, partnerName, teamBadge, flagged, onRefresh, isRegenerating }) => (
  <div
    className={`rounded-lg border p-3 bg-white ${
      flagged
        ? "border-amber-300 ring-1 ring-amber-200"
        : partnerName
          ? "border-sky-200 ring-1 ring-sky-100"
          : "border-slate-200"
    }`}
  >
    <div className="flex items-start justify-between gap-2">
      <div className="min-w-0">
        <div className="flex items-center gap-2">
          {teamBadge && (
            <TeamBadge letter={teamBadge.letter} color={teamBadge.color} title={teamBadge.title} />
          )}
          <div className="text-sm font-semibold text-slate-800 truncate">{p.name}</div>
          {flagged && (
            <span className="text-[9px] font-bold uppercase tracking-wide text-amber-700 bg-amber-100 px-1.5 py-0.5 rounded shrink-0">
              Issue
            </span>
          )}
        </div>
        <div className="text-[11px] text-slate-500">
          {levelEmoji[p.level] || "⚪"} {p.level || "Unknown"}
        </div>
        {partnerName && (
          <div className="mt-1 inline-flex items-center gap-1.5 rounded-full bg-sky-50 text-sky-700 border border-sky-100 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide">
            <span>🤝</span>
            <span>Paired with {partnerName}</span>
          </div>
        )}
      </div>
      <div className="flex flex-col items-end gap-1 shrink-0">
        <div className="text-[11px] font-medium text-slate-600">{p.gender}</div>
        {onRefresh && (
          <button
            type="button"
            disabled={isRegenerating}
            onClick={() => onRefresh(p.id)}
            className="text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-md border border-slate-200 text-slate-600 hover:bg-slate-50 hover:border-pt-teal/40 hover:text-pt-teal disabled:opacity-40"
            title="Exclude this player and regenerate"
          >
            Refresh
          </button>
        )}
      </div>
    </div>
    <div className="mt-2 flex items-center gap-2 flex-wrap text-[10px]">
      {p._wait >= 13 && (
        <span className="px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 font-semibold">🔥 Priority</span>
      )}
      {p._lateHandicap > 0 && (
        <span className="px-2 py-0.5 rounded-full bg-slate-100 text-slate-700 font-semibold">
          +{p._lateHandicap} late
        </span>
      )}
    </div>
    <div className="mt-2 text-[11px] text-slate-500">
      {p._wait || 0}m wait • {p._matches || 0} played
    </div>
  </div>
);

const CheckRow = ({ check }) => (
  <div className={`rounded-lg border px-3 py-2 ${statusStyle[check.status] || statusStyle.pass}`}>
    <div className="text-xs font-semibold uppercase tracking-wide">
      {statusIcon[check.status] || "•"} {check.label}
    </div>
    <div className="text-xs mt-1">{check.reason}</div>
    {Array.isArray(check.violatingPlayers) && check.violatingPlayers.length > 0 && (
      <div className="text-xs mt-1">Players: {check.violatingPlayers.join(", ")}</div>
    )}
    {Array.isArray(check.violatingPair) && check.violatingPair.length > 0 && (
      <div className="text-xs mt-1">Pair: {check.violatingPair.join(" + ")}</div>
    )}
    {Array.isArray(check.pairWarnings) && check.pairWarnings.length > 0 && (
      <div className="text-xs mt-1">
        {check.pairWarnings
          .map((w) => `${w.nameA}/${w.nameB} (${w.matchesAgo} ago, met ${w.encounterCount || 0}x)`)
          .join(" • ")}
      </div>
    )}
    {Array.isArray(check.pairEncounters) && check.pairEncounters.length > 0 && (
      <div className="text-xs mt-1">
        Encounters: {check.pairEncounters.map((w) => `${w.nameA}/${w.nameB} ${w.encounterCount}x`).join(" • ")}
      </div>
    )}
  </div>
);

function collectFlaggedNames(checks = []) {
  const names = new Set();
  checks.forEach((check) => {
    if (check.status !== "fail" && check.status !== "warn") return;
    (check.violatingPlayers || []).forEach((n) => names.add(String(n).toLowerCase()));
    (check.violatingPair || []).forEach((n) => names.add(String(n).toLowerCase()));
    (check.pairWarnings || []).forEach((w) => {
      if (w.nameA) names.add(String(w.nameA).toLowerCase());
      if (w.nameB) names.add(String(w.nameB).toLowerCase());
    });
  });
  return names;
}

export default function MatchProposalModal({
  isOpen,
  proposal,
  partners = [],
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
  onConfirm,
  onReGenerate,
  onRefreshPlayer,
  onClose,
  isRegenerating = false,
}) {
  const flaggedNames = useMemo(
    () => collectFlaggedNames(proposal?.checks || []),
    [proposal?.checks]
  );

  if (!isOpen || !proposal) return null;

  const { success, usedPlayers = [], confidencePct = 0, checks = [], reason, diagnostics = {} } = proposal;
  const men = usedPlayers.filter((p) => p.gender === "M").length;
  const women = usedPlayers.filter((p) => p.gender === "F").length;
  const genderLabel =
    men === 4
      ? "All Male (4M)"
      : women === 4
        ? "All Female (4F)"
        : men === 2 && women === 2
          ? "Mixed (2M + 2F)"
          : "";
  const failCount = checks.filter((c) => c.status === "fail").length;
  const warnCount = checks.filter((c) => c.status === "warn").length;
  const playersById = new Map(usedPlayers.map((p) => [String(p.id), p]));
  const partnerByPlayerId = new Map();
  partners
    .filter((rel) => rel?.isActive)
    .forEach((rel) => {
      const p1 = playersById.get(String(rel.player1Id));
      const p2 = playersById.get(String(rel.player2Id));
      if (!p1 || !p2) return;
      partnerByPlayerId.set(String(p1.id), p2.name);
      partnerByPlayerId.set(String(p2.id), p1.name);
    });

  return (
    <div
      className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={onClose}
    >
      <div
        className="w-full max-w-3xl max-h-[90vh] overflow-y-auto rounded-xl border border-pt-teal/20 bg-white shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div
          className={`px-5 py-4 text-white ${
            success
              ? "bg-gradient-to-r from-pt-teal to-emerald-600"
              : "bg-gradient-to-r from-amber-600 to-orange-600"
          }`}
        >
          <div className="flex items-center justify-between">
            <div>
              <div className="text-lg font-semibold">
                {success ? "Match Proposal" : "No Clean Match Found"}
              </div>
              <div className="text-xs opacity-90">
                {success
                  ? "AI analysis complete - review before queuing"
                  : "Refresh a problem player or queue anyway"}
              </div>
            </div>
            <button type="button" onClick={onClose} className="text-white/90 hover:text-white">
              ✕
            </button>
          </div>
        </div>

        <div className="p-5 space-y-4">
          <div className="flex items-center justify-between">
            <div className="text-sm font-semibold text-slate-700">
              {success ? "Proposed Group" : "Best Available (Conflicted)"}
            </div>
            {genderLabel && (
              <span className="text-xs px-2 py-0.5 rounded-full bg-slate-100 text-slate-700">
                {genderLabel}
              </span>
            )}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {usedPlayers.map((p) => (
              <PlayerCard
                key={p.id}
                p={p}
                partnerName={partnerByPlayerId.get(String(p.id))}
                flagged={flaggedNames.has(String(p.name).toLowerCase())}
                onRefresh={onRefreshPlayer}
                isRegenerating={isRegenerating}
                teamBadge={resolveTeamBadgeDisplay(
                  p,
                  proposal?.teamMeta || null,
                  teamsModeEnabled,
                  teams,
                  teamsSettings?.unassignedLabel
                )}
              />
            ))}
          </div>

          {success && (
            <div className="rounded-lg border border-slate-200 p-3">
              <div className="flex items-center justify-between text-xs font-semibold">
                <span>{confidenceLabel(confidencePct, success)}</span>
                <span>{confidencePct}%</span>
              </div>
              <div className="mt-2 h-2 w-full rounded-full bg-slate-100 overflow-hidden">
                <div
                  className={`h-full ${confidenceColor(confidencePct)}`}
                  style={{ width: `${confidencePct}%` }}
                />
              </div>
            </div>
          )}

          <div className="text-xs text-slate-500">
            Checked {diagnostics.totalCombinationsChecked ?? 0} combinations • Valid found{" "}
            {diagnostics.validCombinationsFound ?? 0}
          </div>
          <div className="text-xs text-slate-600">
            {success
              ? "This is the highest-scoring valid group from all checked combinations."
              : "This is the highest-scoring conflicted fallback from all checked combinations."}
          </div>
          {reason && <div className="text-xs text-slate-600">{reason}</div>}

          <div className="space-y-2">
            <div className="text-sm font-semibold text-slate-700">
              Match Quality Checks{" "}
              {!success && (
                <span className="text-xs font-normal text-slate-500">
                  ({failCount} failed • {warnCount} warning)
                </span>
              )}
            </div>
            {checks.map((check) => (
              <CheckRow key={check.id} check={check} />
            ))}
          </div>

          {!success && (
            <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800">
              <div className="font-semibold">What to do</div>
              <div className="mt-1">
                Tap Refresh on a flagged player to swap them out, wait for a court to finish, or
                Queue anyway if you accept the conflicts.
              </div>
            </div>
          )}
        </div>

        <div className="sticky bottom-0 bg-white border-t border-slate-200 px-5 py-3 flex justify-end gap-2 flex-wrap">
          <button
            type="button"
            onClick={onReGenerate}
            disabled={isRegenerating}
            className="px-3 py-1.5 rounded-lg border border-slate-200 text-slate-700 text-xs font-semibold disabled:opacity-40"
          >
            {isRegenerating ? "Searching..." : "🔄 Try Different"}
          </button>
          {success ? (
            <button
              type="button"
              onClick={onConfirm}
              className="px-3 py-1.5 rounded-lg bg-pt-teal text-white text-xs font-semibold"
            >
              ✅ Queue This Match
            </button>
          ) : (
            <>
              <button
                type="button"
                onClick={onClose}
                className="px-3 py-1.5 rounded-lg border border-slate-200 text-slate-700 text-xs font-semibold"
              >
                Close
              </button>
              <button
                type="button"
                onClick={onConfirm}
                disabled={!(proposal.groupIds?.length || proposal.usedPlayers?.length === 4)}
                className="px-3 py-1.5 rounded-lg bg-amber-600 text-white text-xs font-semibold disabled:opacity-40"
              >
                Queue anyway
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
