import React, { useEffect, useMemo, useState } from "react";
import { Maximize2 } from "lucide-react";
import TeamBadge, { resolvePlayerTeamBadge } from "./TeamBadge";
import { isPlayerUnpaid } from "../../../common/utils/paymentStatus";

const LEVEL_COLUMNS = [
  { key: "Beginner", label: "Beginner", levels: ["Newbie", "Beginner"] },
  { key: "L.Inter", label: "Low Intermediate", levels: ["L.Inter"] },
  { key: "H.Inter", label: "High Intermediate", levels: ["H.Inter", "Intermediate"] },
  { key: "Advance", label: "Advance", levels: ["Advance"] },
];

const LEVEL_COLORS = {
  Newbie: "#94A3B8",
  Beginner: "#F59E0B",
  "L.Inter": "#22C55E",
  "H.Inter": "#3B82F6",
  Advance: "#8B5CF6",
  Intermediate: "#3B82F6",
};

const LEVEL_LETTERS = {
  Newbie: "N",
  Beginner: "B",
  "L.Inter": "L",
  "H.Inter": "H",
  Advance: "A",
  Intermediate: "H",
};

function formatWait(ms) {
  if (!ms || ms <= 0) return "00:00";
  const totalSeconds = Math.floor(ms / 1000);
  const m = Math.floor(totalSeconds / 60).toString().padStart(2, "0");
  const s = (totalSeconds % 60).toString().padStart(2, "0");
  return `${m}:${s}`;
}

function PlayerPoolCard({
  player,
  staged,
  onClick,
  teamsModeEnabled,
  teams,
  teamsSettings,
  clickable = true,
}) {
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const waitMs =
    (player.status === "waiting" || player.status === "queued") && player.waitStart
      ? Math.max(0, Date.now() - player.waitStart + tick * 0)
      : 0;

  const unpaid = isPlayerUnpaid(player.paymentStatus, player.paymentMethod);
  const notArrived = !player.arrivalTime;
  const tb = resolvePlayerTeamBadge(player, teams, teamsModeEnabled, teamsSettings?.unassignedLabel);

  return (
    <button
      type="button"
      disabled={!clickable || staged}
      onClick={() => clickable && !staged && onClick?.(player)}
      className={`w-full text-left rounded-lg border px-2 py-1.5 transition-all ${
        staged
          ? "opacity-40 bg-slate-100 border-slate-200 cursor-not-allowed"
          : clickable
            ? "bg-white border-slate-200 hover:border-pt-teal/40 hover:shadow-sm cursor-pointer"
            : "bg-slate-50 border-slate-100 cursor-default"
      } ${player.gender === "F" && !staged && clickable ? "bg-pink-50/70 border-pink-100" : ""}`}
    >
      <div className="flex items-center gap-1.5">
        {tb ? (
          <TeamBadge display={tb} size="sm" />
        ) : (
          <span
            className="w-5 h-5 rounded-md text-[9px] font-black text-white inline-flex items-center justify-center shrink-0"
            style={{ backgroundColor: LEVEL_COLORS[player.level] || "#94A3B8" }}
          >
            {LEVEL_LETTERS[player.level] || "?"}
          </span>
        )}
        <span className="text-[11px] font-semibold text-slate-800 truncate flex-1">
          {player.name}
        </span>
      </div>
      <div className="flex items-center gap-1.5 mt-0.5 text-[9px] text-slate-500 font-medium">
        <span className="font-mono tabular-nums">{formatWait(waitMs)}</span>
        <span>·</span>
        <span>{player.matches ?? 0}g</span>
        {unpaid && (
          <span className="ml-auto text-amber-700 bg-amber-100 px-1 rounded uppercase font-bold">
            Unpaid
          </span>
        )}
        {notArrived && (
          <span
            className={`${unpaid ? "" : "ml-auto"} text-slate-500 bg-slate-100 px-1 rounded uppercase font-bold`}
          >
            NA
          </span>
        )}
      </div>
    </button>
  );
}

export default function WaitingPool({
  players = [],
  stagedIds = [],
  recentHeldPlayerIds = new Set(),
  onStagePlayer,
  onMaximize,
  unpaidCount = 0,
  notArrivedCount = 0,
  disabled = false,
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
}) {
  const stagedSet = useMemo(() => new Set(stagedIds.map(String)), [stagedIds]);
  const heldSet = useMemo(
    () =>
      recentHeldPlayerIds instanceof Set
        ? recentHeldPlayerIds
        : new Set([...(recentHeldPlayerIds || [])].map(String)),
    [recentHeldPlayerIds]
  );

  const columns = useMemo(() => {
    return LEVEL_COLUMNS.map((col) => {
      const list = players.filter((p) => {
        if (p.status !== "waiting") return false;
        if (!col.levels.includes(p.level)) return false;
        if (heldSet.has(String(p.id))) return false;
        return true;
      });
      const stagedInCol = players.filter(
        (p) =>
          stagedSet.has(String(p.id)) &&
          col.levels.includes(p.level) &&
          !list.some((x) => x.id === p.id)
      );
      const display = [
        ...list,
        ...stagedInCol.filter((p) => p.status === "waiting" || stagedSet.has(String(p.id))),
      ];
      const uniq = [];
      const seen = new Set();
      display.forEach((p) => {
        const k = String(p.id);
        if (seen.has(k)) return;
        seen.add(k);
        uniq.push(p);
      });
      return { ...col, players: uniq };
    }).filter((col) => {
      if (col.players.length > 0) return true;
      return players.some(
        (p) => stagedSet.has(String(p.id)) && col.levels.includes(p.level)
      );
    });
  }, [players, heldSet, stagedSet]);

  const poolEmpty = columns.every((c) => c.players.length === 0);

  return (
    <div className="h-full flex flex-col min-h-0 rounded-xl border border-pt-teal/10 bg-white shadow-sm overflow-hidden">
      <div className="flex items-center justify-between gap-2 px-3 py-2 border-b border-slate-100 shrink-0">
        <div className="text-[10px] font-bold text-pt-teal/70 uppercase tracking-widest">
          Waiting Pool
        </div>
        <button
          type="button"
          onClick={onMaximize}
          className="inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-[10px] font-bold text-pt-teal hover:bg-pt-teal/10"
          title="Open player management"
        >
          {(unpaidCount > 0 || notArrivedCount > 0) && (
            <span className="flex items-center gap-1">
              {unpaidCount > 0 && (
                <span className="bg-amber-100 text-amber-800 px-1.5 py-0.5 rounded-full">
                  {unpaidCount} unpaid
                </span>
              )}
              {notArrivedCount > 0 && (
                <span className="bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded-full">
                  {notArrivedCount} NA
                </span>
              )}
            </span>
          )}
          <Maximize2 className="h-3.5 w-3.5" />
          Manage
        </button>
      </div>

      <div className="flex-1 min-h-0 p-2 overflow-hidden">
        {poolEmpty ? (
          <div className="h-full flex items-center justify-center text-sm text-slate-400 italic border border-dashed border-slate-200 rounded-lg">
            No waiting players. Add players via Manage or session quick-add.
          </div>
        ) : (
          <div className="h-full flex gap-2 min-h-0">
            {columns.map((col) => (
              <div
                key={col.key}
                className="flex-1 min-w-0 flex flex-col rounded-lg border border-slate-100 bg-slate-50/50 overflow-hidden"
              >
                <div className="px-2 py-1.5 border-b border-slate-100 shrink-0">
                  <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wide truncate">
                    {col.label}
                  </div>
                  <div className="text-[9px] text-slate-400">{col.players.length}</div>
                </div>
                <div className="flex-1 min-h-0 overflow-y-auto p-1.5 space-y-1.5 custom-scrollbar">
                  {col.players.map((p) => (
                    <PlayerPoolCard
                      key={p.id}
                      player={p}
                      staged={stagedSet.has(String(p.id))}
                      onClick={() => !disabled && onStagePlayer?.(p)}
                      teamsModeEnabled={teamsModeEnabled}
                      teams={teams}
                      teamsSettings={teamsSettings}
                      clickable={!disabled}
                    />
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
