import React, { useEffect, useMemo, useState } from "react";
import toast from "react-hot-toast";
import TeamBadge, { resolvePlayerTeamBadge } from "./TeamBadge";
import { getRecentUnscoredMatches, matchHasSavedScore } from "../utils/recentPool";

const LEVEL_COLORS = {
  Newbie: "#94A3B8",
  Beginner: "#F59E0B",
  "L.Inter": "#22C55E",
  "H.Inter": "#3B82F6",
  Advance: "#8B5CF6",
};

const LEVEL_LETTERS = {
  Newbie: "N",
  Beginner: "B",
  "L.Inter": "L",
  "H.Inter": "H",
  Advance: "A",
};

function formatAgo(ms) {
  const totalSeconds = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(totalSeconds / 60);
  const s = totalSeconds % 60;
  if (m <= 0) return `${s}s ago`;
  return `${m}m ${s.toString().padStart(2, "0")}s ago`;
}

/** After score save: which side this player was on (uses teams + winner). */
function playerOutcomeForScoredMatch(match, playerId) {
  if (!matchHasSavedScore(match)) return null;
  const key = String(playerId);
  const green = new Set((match?.teams?.green || []).map(String));
  const blue = new Set((match?.teams?.blue || []).map(String));
  const side = green.has(key) ? "green" : blue.has(key) ? "blue" : null;
  if (!side) return null;
  const w = match?.winner;
  if (w === "tie") return "tie";
  if (w === "green") return side === "green" ? "win" : "loss";
  if (w === "blue") return side === "blue" ? "win" : "loss";
  // Score saved but winner not set — green is winning side from recent-match flow
  return side === "green" ? "win" : "loss";
}

/** Queue-style 2×2 player chip with optional winner select + release × */
function RecentPlayerCell({
  player,
  selected,
  selectionLabel,
  outcome,
  onSelect,
  onRelease,
  teamsModeEnabled,
  teams,
  teamsSettings,
  disabled,
  scoringMode,
}) {
  const tb = resolvePlayerTeamBadge(player, teams, teamsModeEnabled, teamsSettings?.unassignedLabel);
  const letter = LEVEL_LETTERS[player.level] || "?";
  const color = LEVEL_COLORS[player.level] || "#94A3B8";

  let cellClass =
    player.gender === "F"
      ? "bg-pink-50 border-pink-100"
      : "bg-amber-50/80 border-amber-100";
  if (outcome === "win") {
    cellClass = "bg-emerald-50/90 border-emerald-300/80 ring-1 ring-emerald-200/60";
  } else if (outcome === "loss") {
    cellClass = "bg-slate-100/90 border-slate-300/70 ring-1 ring-slate-200/50";
  } else if (selected) {
    cellClass = "bg-emerald-50 border-emerald-400";
  }

  return (
    <li
      className={`flex items-center gap-1 rounded-md border px-1.5 py-1 text-[10px] min-w-0 ${cellClass}`}
    >
      <button
        type="button"
        disabled={disabled || !onSelect}
        onClick={() => onSelect?.(player)}
        className="flex-1 min-w-0 flex items-center gap-1 text-left disabled:cursor-default"
        title={scoringMode ? "Tap to mark winner" : undefined}
      >
        {tb ? (
          <TeamBadge letter={tb.letter} color={tb.color} title={tb.title} />
        ) : (
          <span
            className="w-3.5 h-3.5 rounded-full shrink-0 inline-flex items-center justify-center text-white font-black"
            style={{ fontSize: "0.45rem", backgroundColor: color }}
          >
            {letter}
          </span>
        )}
        <span className="truncate font-medium flex-1 text-slate-800">{player.name}</span>
        {selectionLabel && (
          <span className="text-[8px] font-bold uppercase text-emerald-700 bg-emerald-100 px-1 rounded shrink-0">
            {selectionLabel}
          </span>
        )}
        {outcome === "win" && (
          <span className="text-[8px] font-bold uppercase text-emerald-800 bg-emerald-100/90 px-1 rounded shrink-0">
            Win
          </span>
        )}
        {outcome === "loss" && (
          <span className="text-[8px] font-bold uppercase text-slate-600 bg-slate-200/80 px-1 rounded shrink-0">
            Loss
          </span>
        )}
      </button>
      {onRelease && (
        <button
          type="button"
          disabled={disabled}
          className="text-red-400 hover:text-red-600 shrink-0 leading-none disabled:opacity-40"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            onRelease(player);
          }}
          title="Release player"
        >
          ×
        </button>
      )}
    </li>
  );
}

function AgoLabel({ endTime }) {
  const [nowTick, setNowTick] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNowTick(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  return (
    <span className="text-[9px] text-amber-600 font-mono">{formatAgo(nowTick - endTime)}</span>
  );
}

function RecentMatchCard({
  group,
  onReleasePlayer,
  onReleaseAll,
  onUpdateMatch,
  teamsModeEnabled,
  teams,
  teamsSettings,
  disabled,
}) {
  const [winnerIds, setWinnerIds] = useState([]);
  const [scoring, setScoring] = useState(false);
  const [winnerScore, setWinnerScore] = useState("");
  const [loserScore, setLoserScore] = useState("");
  const winnerSet = useMemo(() => new Set(winnerIds.map(String)), [winnerIds]);
  const isScored = group.isScored || matchHasSavedScore(group.match);
  const players = group.players || [];

  const toggleWinner = (player) => {
    if (disabled || isScored) return;
    if (!scoring) setScoring(true);
    const key = String(player.id);
    setWinnerIds((prev) => {
      const exists = prev.some((id) => String(id) === key);
      if (exists) return prev.filter((id) => String(id) !== key);
      if (prev.length >= 2) return prev;
      return [...prev, player.id];
    });
  };

  const handleSaveScore = () => {
    if (!onUpdateMatch) return;
    if (winnerIds.length !== 2) {
      toast.error("Select exactly 2 winners");
      return;
    }
    const w = parseInt(winnerScore, 10);
    const l = parseInt(loserScore, 10);
    if (!Number.isFinite(w) || !Number.isFinite(l)) {
      toast.error("Enter both scores");
      return;
    }
    if (w <= l) {
      toast.error("Winner score must be higher than loser score");
      return;
    }
    const green = [...winnerIds];
    const greenKeys = new Set(green.map(String));
    const blue = players.filter((p) => !greenKeys.has(String(p.id))).map((p) => p.id);
    if (blue.length === 0) {
      toast.error("Need at least one loser in the group");
      return;
    }
    onUpdateMatch(group.matchId, {
      teams: { green, blue },
      score: { green: w, blue: l },
    });
    setScoring(false);
    setWinnerScore("");
    setLoserScore("");
    setWinnerIds([]);
    toast.success("Score saved");
  };

  const scoreLabel = isScored
    ? `${group.match?.score?.green ?? "?"}–${group.match?.score?.blue ?? "?"}`
    : null;

  return (
    <div className="shrink-0 w-[280px] h-full min-h-0 rounded-xl border border-amber-200 bg-white shadow-sm flex flex-col gap-2 p-2.5 overflow-hidden">
      <div className="flex items-center justify-between gap-2 shrink-0">
        <div className="flex items-center gap-1.5 min-w-0">
          <span className="w-5 h-5 rounded-md text-[10px] font-black inline-flex items-center justify-center bg-amber-100 text-amber-800 shrink-0">
            R
          </span>
          <span className="text-[10px] font-bold uppercase tracking-wide text-amber-800 truncate">
            {group.courtName}
          </span>
        </div>
        <div className="flex items-center gap-1.5 shrink-0">
          {isScored && (
            <span className="text-[8px] font-bold uppercase tracking-wide text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded">
              {scoreLabel || "Scored"}
            </span>
          )}
          <AgoLabel endTime={group.endTime} />
        </div>
      </div>

      {!isScored && !scoring && (
        <div className="text-[9px] text-amber-700/70 shrink-0 leading-none">
          Tap 2 winners ({winnerIds.length}/2)
        </div>
      )}

      <ul className="grid grid-cols-2 gap-1 shrink-0">
        {players.map((p) => (
          <RecentPlayerCell
            key={String(p.id)}
            player={p}
            selected={!isScored && winnerSet.has(String(p.id))}
            selectionLabel={!isScored && winnerSet.has(String(p.id)) ? "W" : null}
            outcome={isScored ? playerOutcomeForScoredMatch(group.match, p.id) : null}
            onSelect={!isScored ? toggleWinner : null}
            onRelease={
              onReleasePlayer ? () => onReleasePlayer(p.id, group) : null
            }
            teamsModeEnabled={teamsModeEnabled}
            teams={teams}
            teamsSettings={teamsSettings}
            disabled={disabled}
            scoringMode={!isScored}
          />
        ))}
        {Array.from({ length: Math.max(0, 4 - players.length) }).map((_, i) => (
          <li key={`e-${i}`} className="rounded-md border border-dashed border-amber-100 h-7" />
        ))}
      </ul>

      <div className="flex items-center gap-1.5 mt-auto pt-1 border-t border-amber-50 shrink-0">
        {!isScored && scoring ? (
          <>
            <input
              type="number"
              min={0}
              inputMode="numeric"
              value={winnerScore}
              onChange={(e) => setWinnerScore(e.target.value)}
              className="w-10 rounded border border-emerald-300 bg-white px-1 py-1 text-[10px] font-bold tabular-nums"
              placeholder="W"
              title="Winner score"
            />
            <span className="text-[9px] text-slate-400">–</span>
            <input
              type="number"
              min={0}
              inputMode="numeric"
              value={loserScore}
              onChange={(e) => setLoserScore(e.target.value)}
              className="w-10 rounded border border-slate-300 bg-white px-1 py-1 text-[10px] font-bold tabular-nums"
              placeholder="L"
              title="Loser score"
            />
            <button
              type="button"
              onClick={() => {
                setScoring(false);
                setWinnerScore("");
                setLoserScore("");
                setWinnerIds([]);
              }}
              className="text-[9px] text-slate-500 underline"
            >
              Back
            </button>
            <button
              type="button"
              onClick={handleSaveScore}
              disabled={winnerIds.length !== 2}
              className="ml-auto px-2 py-1 rounded-md text-[10px] font-bold bg-emerald-600 text-white disabled:opacity-40"
            >
              Save
            </button>
          </>
        ) : (
          <>
            {!isScored && (
              <button
                type="button"
                disabled={disabled || winnerIds.length !== 2}
                onClick={() => setScoring(true)}
                className="flex-1 px-2 py-1 rounded-md text-[10px] font-bold bg-emerald-600 text-white disabled:opacity-40"
              >
                Set score
              </button>
            )}
            {isScored && onReleaseAll && players.length > 0 && (
              <button
                type="button"
                disabled={disabled}
                onClick={() => onReleaseAll(group)}
                title="Release all players"
                className="flex-1 px-2 py-1 rounded-md text-[10px] font-bold bg-amber-100 text-amber-900 border border-amber-200 hover:bg-amber-200 disabled:opacity-40"
              >
                Release all
              </button>
            )}
          </>
        )}
      </div>
    </div>
  );
}

export default function RecentGamesStrip({
  players = [],
  matches = [],
  dismissedRecentMatchIds = new Set(),
  releasedByMatch = {},
  onReleasePlayer,
  onReleaseAll,
  onUpdateMatch,
  disabled = false,
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
}) {
  // Do NOT tick every second here — that rebuilt the whole strip and made × clicks feel sticky.
  const recentGroups = useMemo(
    () =>
      getRecentUnscoredMatches({
        matches,
        players,
        dismissedRecentMatchIds,
        releasedByMatch,
      }),
    [matches, players, dismissedRecentMatchIds, releasedByMatch]
  );

  return (
    <div className="h-full min-h-0 flex flex-col rounded-xl border border-amber-200/60 bg-amber-50/30 shadow-sm overflow-hidden p-2.5 gap-2">
      <div className="flex items-center justify-between gap-2 px-1 shrink-0">
        <div className="flex items-center gap-2 min-w-0">
          <span className="text-[10px] font-bold text-amber-800 uppercase tracking-widest shrink-0">
            Recently Played
          </span>
          <span className="text-[10px] text-amber-700/70 truncate hidden sm:inline">
            Score first · then × / Release all
          </span>
        </div>
        <span className="text-[10px] text-amber-700/70 font-medium shrink-0">
          {recentGroups.length} game{recentGroups.length === 1 ? "" : "s"}
        </span>
      </div>

      <div className="flex-1 min-h-0 overflow-x-auto overflow-y-hidden pb-1 custom-scrollbar">
        {recentGroups.length === 0 ? (
          <div className="h-full flex items-center justify-center text-sm text-amber-700/50 italic border border-dashed border-amber-200 rounded-lg px-4">
            No recent matches
          </div>
        ) : (
          <div className="h-full flex gap-2 items-stretch">
            {recentGroups.map((group) => (
              <RecentMatchCard
                key={group.matchId}
                group={group}
                onReleasePlayer={onReleasePlayer}
                onReleaseAll={onReleaseAll}
                onUpdateMatch={onUpdateMatch}
                teamsModeEnabled={teamsModeEnabled}
                teams={teams}
                teamsSettings={teamsSettings}
                disabled={disabled}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
