import { formatPaymentMethodLabel } from '../../../common/utils/paymentStatus';
import { formatMinutesAmpm } from './calendarUtils';

export { resolveInvoiceGcash };

async function waitForImages(root) {
    const imgs = Array.from(root.querySelectorAll('img'));
    return Promise.all(
        imgs.map(
            (img) =>
                new Promise((resolve) => {
                    if (img.complete && img.naturalWidth > 0) {
                        resolve();
                        return;
                    }
                    img.onload = () => resolve();
                    img.onerror = () => resolve();
                })
        )
    );
}

async function captureInvoicePng(source) {
    await waitForImages(source);

    const scrollParent = source.parentElement;
    const prev = {
        padding: source.style.padding,
        overflow: source.style.overflow,
        parentOverflow: scrollParent?.style.overflow ?? '',
    };

    // Extra margin so the PNG isn't edge-tight; unlock overflow so text isn't clipped.
    source.style.padding = '28px';
    source.style.overflow = 'visible';
    if (scrollParent) scrollParent.style.overflow = 'visible';

    try {
        await new Promise((resolve) => {
            requestAnimationFrame(() => requestAnimationFrame(resolve));
        });

        const width = Math.ceil(source.scrollWidth);
        const height = Math.ceil(source.scrollHeight);
        const canvas = await html2canvas(source, {
            backgroundColor: '#ffffff',
            scale: 2,
            useCORS: true,
            logging: false,
            width,
            height,
            windowWidth: width,
            windowHeight: height,
            scrollX: 0,
            scrollY: 0,
            onclone: (_doc, cloned) => {
                cloned.style.padding = '28px';
                cloned.style.boxSizing = 'border-box';
                cloned.style.overflow = 'visible';
                // html2canvas often clips italic / tight line-boxes — relax for export.
                cloned.querySelectorAll('p, span').forEach((node) => {
                    node.style.lineHeight = '1.35';
                    node.style.overflow = 'visible';
                });
                cloned.querySelectorAll('[class*="drop-shadow"]').forEach((node) => {
                    node.style.filter = 'none';
                    node.style.textShadow = 'none';
                });
            },
        });
        return canvas.toDataURL('image/png');
    } finally {
        source.style.padding = prev.padding;
        source.style.overflow = prev.overflow;
        if (scrollParent) scrollParent.style.overflow = prev.parentOverflow;
    }
}

function formatBrandName(name) {
    const parts = String(name || "").trim().split(/\s+/).filter(Boolean);
    if (parts.length < 3) return name;
    // Keep the last two words together so "Club" (etc.) never wraps alone
    return [...parts.slice(0, -2), parts.slice(-2).join("\u00A0")].join(" ");
}

function BrandHeader() {
    return (
        <div className="flex items-center justify-center gap-3 mb-5 print:mb-4">
            <img
                src={config.assetPath('logo.png')}
                alt={config.name}
                className="w-14 h-14 object-cover rounded-full shadow-md border-2 border-pt-orange print:w-12 print:h-12 shrink-0"
            />
            <div className="flex flex-col justify-center text-left min-w-0 gap-1">
                <span className="text-2xl md:text-3xl text-pt-navy font-display font-extrabold italic print:text-2xl leading-snug">
                    {formatBrandName(config.name)}
                </span>
                <span className="text-[10px] text-pt-navy/60 uppercase tracking-[0.25em] font-medium font-body not-italic leading-normal">
                    {config.tagline || 'Pickleball Facility'}
                </span>
                {config.address && (
                    <span className="text-[10px] text-pt-navy/50 max-w-[220px] leading-normal">
                        {config.address}
                    </span>
                )}
            </div>
        </div>
    );
}

function FinancialBlock({
    discountPct,
    subtotal,
    total,
    discountAmount,
    pickleCamFee = 0,
    pickleCamHours = 0,
    pickleCamCourtCount = 1,
    pickleCamRate = 0,
    pickleCamPricingMode = "flat",
    ballSalesTotal = 0,
    ballQty = 0,
    ballUnitFee = 78,
    titanFee = 0,
    paid,
    balance,
    compact = false,
}) {
    const pickleCamLabel = pickleCamPricingMode === "hourly" && pickleCamHours > 0
        ? `PickleCam (${pickleCamHours}h × ${pickleCamCourtCount} court${pickleCamCourtCount !== 1 ? 's' : ''} × ₱${pickleCamRate})`
        : "PickleCam";

    return (
        <div
            className="bg-slate-50 rounded-lg px-3 py-2.5 space-y-1.5 print:bg-transparent print:p-0 print:border-t-2 print:border-slate-900 print:rounded-none"
        >
            {pickleCamFee > 0 && (
                <div className="flex justify-between items-center">
                    <span className="text-xs text-slate-600">{pickleCamLabel}</span>
                    <span className="text-xs font-semibold text-slate-900">₱{pickleCamFee.toLocaleString()}</span>
                </div>
            )}
            {ballSalesTotal > 0 && (
                <div className="flex justify-between items-center">
                    <span className="text-xs text-slate-600">
                        Ball sales{ballQty > 0 ? ` (${ballQty} × ₱${ballUnitFee})` : ''}
                    </span>
                    <span className="text-xs font-semibold text-slate-900">₱{ballSalesTotal.toLocaleString()}</span>
                </div>
            )}
            {titanFee > 0 && (
                <div className="flex justify-between items-center">
                    <span className="text-xs text-slate-600">Titan Machine</span>
                    <span className="text-xs font-semibold text-slate-900">₱{titanFee.toLocaleString()}</span>
                </div>
            )}
            {discountPct > 0 && (
                <>
                    <div className="flex justify-between items-center">
                        <span className="text-xs text-slate-600">Subtotal</span>
                        <span className="text-xs text-slate-600">₱{(subtotal ?? total + discountAmount).toLocaleString()}</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-xs text-emerald-600 font-medium">Discount on court ({discountPct}%)</span>
                        <span className="text-xs font-semibold text-emerald-600">-₱{discountAmount.toLocaleString()}</span>
                    </div>
                </>
            )}
            <div className="flex justify-between items-center">
                <span className="text-xs text-slate-600">Amount Paid</span>
                <span className="text-xs font-semibold text-slate-900">₱{paid.toLocaleString()}</span>
            </div>
            <div className={`flex justify-between items-center ${discountPct > 0 ? 'border-t border-slate-200 pt-1' : ''}`}>
                <span className="text-xs text-slate-600">Total Due</span>
                <span className="text-xs font-semibold text-slate-900">₱{total.toLocaleString()}</span>
            </div>
            <div
                className={`flex justify-between items-center border-t border-slate-200 ${compact ? 'pt-1.5' : 'pt-1.5 mt-0.5'} print:border-slate-900`}
            >
                <span className={`${compact ? 'text-xs' : 'text-sm'} font-bold text-slate-700`}>
                    {balance < 0 ? 'Overpaid' : 'Current Balance'}
                </span>
                <span
                    className={`${compact ? 'text-xs' : 'text-sm'} font-bold ${
                        balance > 0 ? 'text-rose-600' : balance < 0 ? 'text-amber-700' : 'text-emerald-600'
                    } print:text-black`}
                >
                    ₱{Math.abs(balance).toLocaleString()}
                    {balance < 0 ? ' (refundable)' : ''}
                </span>
            </div>
        </div>
    );
}

