import React, { useMemo } from "react";
import {
  computeSessionPlayerStats,
  rankSessionPlayers,
} from "../utils/sessionPlayerStats";
import {
  DISPLAY_PODIUM_NAME_FIRST,
  DISPLAY_PODIUM_NAME_SIDE,
  DISPLAY_RANK_NAME,
  DISPLAY_RANK_NAME_COMPACT,
} from "../../../common/utils/displayTypography";

const EMOJIS = ["😎", "🏓", "⚡", "🌟", "🔥", "🎯", "💪", "🏆", "😄", "🤩"];

function playerPhoto(player) {
  return player?.imageUrl || player?.photo || player?.avatarUrl || null;
}

function emojiForId(id) {
  const s = String(id || "0");
  let hash = 0;
  for (let i = 0; i < s.length; i += 1) hash = (hash * 31 + s.charCodeAt(i)) >>> 0;
  return EMOJIS[hash % EMOJIS.length];
}

function Avatar({ player, size = "md", onFire = false }) {
  const src = playerPhoto(player?.player || player);
  const dim =
    size === "xl"
      ? "h-[clamp(4.5rem,14vmin,8.5rem)] w-[clamp(4.5rem,14vmin,8.5rem)]"
      : size === "lg"
        ? "h-[clamp(3.75rem,11vmin,6.5rem)] w-[clamp(3.75rem,11vmin,6.5rem)]"
        : "h-[clamp(2.75rem,7vmin,4.25rem)] w-[clamp(2.75rem,7vmin,4.25rem)]";
  const dimSm = "h-[clamp(2rem,5vmin,3rem)] w-[clamp(2rem,5vmin,3rem)]";
  const resolvedDim = size === "sm" ? dimSm : dim;
  const emojiSize =
    size === "xl"
      ? "text-[clamp(1.75rem,5vmin,3.5rem)]"
      : size === "lg"
        ? "text-[clamp(1.35rem,4vmin,2.75rem)]"
        : "text-[clamp(1rem,2.8vmin,1.75rem)]";
  const emojiSm = "text-[clamp(0.85rem,2.2vmin,1.25rem)]";
  const resolvedEmoji = size === "sm" ? emojiSm : emojiSize;
  return (
    <div className={`relative ${resolvedDim} shrink-0`}>
      {src ? (
        <img
          src={src}
          alt={player?.name || ""}
          className={`h-full w-full object-cover rounded-full border-[3px] md:border-4 ${
            onFire ? "border-orange-400" : "border-white/30"
          }`}
        />
      ) : (
        <div
          className={`h-full w-full rounded-full flex items-center justify-center border-[3px] md:border-4 ${
            onFire ? "border-orange-400 bg-orange-500/20" : "border-white/20 bg-white/10"
          } ${resolvedEmoji}`}
        >
          {emojiForId(player?.id)}
        </div>
      )}
    </div>
  );
}

/** Trading-card style portrait for podium top 3. */
function PodiumPortraitCard({ entry, rank, isFirst, fillRow = false }) {
  const src = playerPhoto(entry?.player || entry);
  const tilt =
    rank === 2 ? "-rotate-2" : rank === 3 ? "rotate-2" : "";
  const frame = isFirst
    ? "border-orange-400/70 shadow-[0_0_28px_rgba(251,146,60,0.35)]"
    : rank === 2
      ? "border-white/35 shadow-[0_8px_24px_rgba(0,0,0,0.45)]"
      : "border-amber-600/40 shadow-[0_8px_24px_rgba(0,0,0,0.45)]";

  // Side ranks: ~10% shorter than #1 and bottom-aligned so #1 sits higher (podium).
  const sizeClass = fillRow
    ? isFirst
      ? "h-full max-h-full w-auto max-w-full aspect-[3/4]"
      : "h-[76%] max-h-[76%] w-auto max-w-full aspect-[3/4]"
    : isFirst
      ? "w-[clamp(7.5rem,17vmin,13.5rem)] aspect-[3/4]"
      : "w-[clamp(6.25rem,13.5vmin,10.5rem)] aspect-[3/4]";

  return (
    <div
      className={`relative shrink-0 ${sizeClass} rounded-2xl border-[3px] md:border-4 overflow-hidden bg-gradient-to-b from-white/15 to-white/5 ${frame} ${tilt} transform transition-transform`}
    >
      {src ? (
        <img src={src} alt={entry?.name || ""} className="absolute inset-0 h-full w-full object-cover" />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-br from-slate-700/80 to-slate-900/90 text-[clamp(2rem,6vmin,4rem)]">
          {emojiForId(entry?.id)}
        </div>
      )}
      <div className="absolute inset-0 bg-gradient-to-t from-black/75 via-black/15 to-transparent pointer-events-none" />
      <div
        className={`absolute top-2 left-2 rounded-full font-black uppercase tracking-wide px-2 py-0.5 ${
          isFirst
            ? "bg-orange-500/90 text-white text-[clamp(0.55rem,1.2vmin,0.75rem)]"
            : "bg-black/55 text-white/90 text-[clamp(0.5rem,1.1vmin,0.7rem)] border border-white/20"
        }`}
      >
        {isFirst ? "1st" : rank === 2 ? "2nd" : "3rd"}
      </div>
      <div className="absolute inset-0 ring-1 ring-inset ring-white/10 pointer-events-none rounded-2xl" />
    </div>
  );
}

function StatChip({ label, value, accent = "slate", compact = false }) {
  const accents = {
    sky: "bg-sky-500/20 text-sky-100 border-sky-400/30",
    green: "bg-emerald-500/20 text-emerald-100 border-emerald-400/30",
    orange: "bg-orange-500/20 text-orange-100 border-orange-400/30",
    slate: "bg-white/10 text-white/90 border-white/20",
  };
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-md border font-semibold ${
        compact ? "px-1.5 py-0.5" : "px-2 py-0.5"
      } ${accents[accent] || accents.slate}`}
    >
      <span
        className={`uppercase tracking-wide font-bold opacity-90 ${
          compact
            ? "text-[clamp(0.6rem,1.35vmin,0.78rem)]"
            : "text-[clamp(0.68rem,1.55vmin,0.9rem)]"
        }`}
      >
        {label}
      </span>
      <span
        className={`font-display font-extrabold italic tabular-nums leading-none ${
          compact
            ? "text-[clamp(0.72rem,1.7vmin,0.95rem)]"
            : "text-[clamp(0.8rem,1.9vmin,1.1rem)]"
        }`}
      >
        {value}
      </span>
    </span>
  );
}

/** All stats equal size — wins first (primary ranking key). */
function PlayerStatsInline({ entry, align = "center", compact = false }) {
  const pd = entry.pointDifferential;
  const pdStr = `${pd > 0 ? "+" : ""}${Number(pd).toFixed(1)}`;
  const avgStr = entry.avgPointDiff > 0 ? `+${entry.avgPointDiff}` : String(entry.avgPointDiff);
  const justify = align === "left" ? "justify-start" : "justify-center";
  const gap = compact ? "gap-0.5" : "gap-1";

  return (
    <div className={`flex flex-wrap items-center ${gap} w-full ${justify}`}>
      <StatChip label="W" value={entry.wins} accent="green" compact={compact} />
      <StatChip label="PD" value={pdStr} accent="sky" compact={compact} />
      <StatChip label="TP" value={entry.totalPoints} accent="orange" compact={compact} />
      <StatChip label="WR" value={`${entry.winRate}%`} accent="green" compact={compact} />
      <StatChip label="AVG" value={avgStr} accent="sky" compact={compact} />
      <StatChip label="L" value={entry.losses} compact={compact} />
      <StatChip label="M" value={entry.matches} compact={compact} />
    </div>
  );
}

function PodiumPortraitSlot({ entry, rank, isFirst }) {
  if (!entry) return <div className="min-h-0 h-full" />;
  return (
    <div className="h-full min-h-0 w-full flex justify-center items-end">
      <PodiumPortraitCard entry={entry} rank={rank} isFirst={isFirst} fillRow />
    </div>
  );
}

/** Full-width info box for ranks 1–3 (row below portraits). */
function PodiumInfoBox({ entry, rank, isFirst }) {
  if (!entry) return <div className="min-h-0 h-full" />;
  const rankLabel = isFirst ? "#1 TOP RANK" : `#${rank}`;

  return (
    <div
      className={`min-h-0 w-full rounded-xl border px-2 py-2 md:px-3 md:py-2.5 flex flex-col items-center justify-center gap-1 overflow-hidden ${
        isFirst
          ? "h-full border-orange-400/40 bg-orange-500/10"
          : "h-[90%] self-end border-white/10 bg-white/[0.04]"
      }`}
    >
      <div
        className={`font-black uppercase tracking-widest leading-snug shrink-0 w-full text-center ${
          isFirst
            ? "text-orange-300 text-[clamp(0.65rem,1.6vmin,1rem)]"
            : "text-white/65 text-[clamp(0.6rem,1.4vmin,0.9rem)]"
        }`}
      >
        {rankLabel}
      </div>
      <div className="w-full text-center min-w-0 flex-1 flex flex-col justify-center px-1">
        <div
          className="!text-white font-display font-extrabold italic uppercase w-full leading-[1.08] break-words"
          style={{ fontSize: isFirst ? DISPLAY_PODIUM_NAME_FIRST : DISPLAY_PODIUM_NAME_SIDE }}
        >
          {entry.name}
        </div>
      </div>
      <div className="w-full min-w-0 shrink-0">
        <PlayerStatsInline entry={entry} />
      </div>
    </div>
  );
}

function RankListCard({ entry, rank, compact = false }) {
  return (
    <div
      className={`rounded-lg border border-white/10 bg-white/5 flex flex-col justify-center min-w-0 h-full min-h-0 overflow-hidden ${
        compact ? "px-1.5 py-1.5 gap-1" : "px-2 py-2 md:px-2.5 md:py-2.5 gap-1.5"
      }`}
    >
      <div className="flex items-center gap-1.5 md:gap-2 min-w-0 shrink-0">
        <span
          className={`font-black text-white/45 shrink-0 text-center ${
            compact
              ? "text-[clamp(0.65rem,1.5vmin,0.85rem)] w-5"
              : "text-[clamp(0.75rem,1.8vmin,1.1rem)] w-7"
          }`}
        >
          #{rank}
        </span>
        <Avatar player={entry} size={compact ? "sm" : "md"} />
        <div className="min-w-0 flex-1">
          <div
            className="!text-white font-display font-extrabold italic uppercase truncate leading-tight"
            style={{ fontSize: compact ? DISPLAY_RANK_NAME_COMPACT : DISPLAY_RANK_NAME }}
          >
            {entry.name}
          </div>
        </div>
      </div>
      <PlayerStatsInline entry={entry} align="left" compact={compact} />
    </div>
  );
}

export default function LeaderboardPodiumView({
  players = [],
  matches = [],
  settings,
  teamsSettings = {},
  sessionTopTeams = [],
}) {
  const teamsMode =
    settings?.teamsModeEnabled &&
    teamsSettings.showTopTeamsOnDisplay !== false &&
    sessionTopTeams.length > 0;

  const ranked = useMemo(() => {
    const stats = computeSessionPlayerStats(players, matches);
    return rankSessionPlayers(stats).slice(0, 10);
  }, [players, matches]);

  const isNight = new Date().getHours() >= 18;
  const title = teamsMode
    ? isNight
      ? "Team of the Night"
      : "Team of the Day"
    : "Leaderboards";

  if (teamsMode) {
    const podium = sessionTopTeams.slice(0, 3).map((t, idx) => ({
      ...t,
      rank: idx + 1,
      displayName: t.displayName,
      wins: t.wins,
      points: Math.round((t.winPct || 0) * 100),
    }));
    const first = podium[0];
    const second = podium[1];
    const third = podium[2];
    return (
      <div className="h-full flex flex-col min-h-0 items-center justify-center px-6">
        <h2 className="!text-white text-3xl md:text-5xl font-display font-extrabold italic uppercase tracking-widest mb-8">
          {title}
        </h2>
        {!first ? (
          <p className="text-white/40 uppercase tracking-widest text-sm">No winners yet</p>
        ) : (
          <div className="flex items-end justify-center gap-6 md:gap-10 w-full max-w-5xl">
            {second && (
              <div className="flex flex-col items-center gap-2 flex-1 max-w-[220px]">
                <div className="text-white/70 text-sm font-bold">#2</div>
                <div className="!text-white text-xl font-display font-extrabold italic uppercase text-center truncate w-full">
                  {second.displayName}
                </div>
                <div className="text-white/50 text-xs">{second.wins}W · {second.points}%</div>
              </div>
            )}
            {first && (
              <div className="flex flex-col items-center gap-2 flex-1 max-w-[280px]">
                <div className="text-orange-300 text-lg font-black">#1</div>
                <div className="!text-white text-2xl font-display font-extrabold italic uppercase text-center truncate w-full">
                  {first.displayName}
                </div>
                <div className="text-orange-200/80 text-sm">{first.wins}W · {first.points}%</div>
              </div>
            )}
            {third && (
              <div className="flex flex-col items-center gap-2 flex-1 max-w-[220px]">
                <div className="text-white/70 text-sm font-bold">#3</div>
                <div className="!text-white text-xl font-display font-extrabold italic uppercase text-center truncate w-full">
                  {third.displayName}
                </div>
                <div className="text-white/50 text-xs">{third.wins}W · {third.points}%</div>
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  const top3 = ranked.slice(0, 3);
  const row46 = ranked.slice(3, 6);
  const row710 = ranked.slice(6, 10);
  const first = top3[0];
  const second = top3[1];
  const third = top3[2];

  return (
    <div className="h-full flex flex-col min-h-0 px-2 md:px-3 lg:px-4 py-0.5 overflow-hidden w-full">
      <h2 className="!text-white text-[clamp(1.5rem,4vmin,3rem)] font-display font-extrabold italic uppercase tracking-widest mb-1 shrink-0 text-center leading-none">
        {title}
      </h2>

      {ranked.length === 0 ? (
        <p className="text-white/40 uppercase tracking-widest text-base text-center">No winners yet</p>
      ) : (
        <div className="flex-1 min-h-0 flex flex-col gap-2 w-full">
          {/* Row 1: portrait cards 2 | 1 | 3 — #1 tallest, #2/#3 shorter & bottom-aligned */}
          <div className="min-h-0 flex-[1.15] grid grid-cols-3 gap-2 md:gap-3 lg:gap-4 items-end">
            <PodiumPortraitSlot entry={second} rank={2} isFirst={false} />
            <PodiumPortraitSlot entry={first} rank={1} isFirst />
            <PodiumPortraitSlot entry={third} rank={3} isFirst={false} />
          </div>

          {/* Row 2: large info boxes 2 | 1 | 3 — #2/#3 10% shorter, sit on bottom */}
          <div className="min-h-0 flex-[1.15] grid grid-cols-3 gap-2 md:gap-3 lg:gap-4 items-end">
            <PodiumInfoBox entry={second} rank={2} isFirst={false} />
            <PodiumInfoBox entry={first} rank={1} isFirst />
            <PodiumInfoBox entry={third} rank={3} isFirst={false} />
          </div>

          {/* Row 3: ranks 4–6 — same height band as 7–10 */}
          {row46.length > 0 && (
            <div className="min-h-0 flex-[0.72] grid grid-cols-3 gap-2 md:gap-3 lg:gap-4">
              {row46.map((entry, i) => (
                <RankListCard key={entry.id} entry={entry} rank={i + 4} compact />
              ))}
            </div>
          )}

          {/* Row 4: ranks 7–10 */}
          {row710.length > 0 && (
            <div className="min-h-0 flex-[0.72] grid grid-cols-4 gap-2 md:gap-2.5">
              {row710.map((entry, i) => (
                <RankListCard key={entry.id} entry={entry} rank={i + 7} compact />
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
