/**
 * Sponsor images are http(s) URLs only (no local asset paths).
 */
export function resolveSponsorImageUrl(imageUrl) {
  if (!imageUrl || typeof imageUrl !== "string") return "";
  const trimmed = imageUrl.trim();
  if (!trimmed) return "";
  if (/^https?:\/\//i.test(trimmed)) return trimmed;
  return "";
}

/** Heuristic: direct image file vs a gallery/page URL. */
export function looksLikeDirectImageUrl(url) {
  if (!url) return false;
  if (/\.(png|jpe?g|gif|webp|svg|avif|bmp)(\?.*)?$/i.test(url)) return true;
  return false;
}
