import React, { useMemo } from "react";
import TeamBadge, { resolvePlayerTeamBadge } from "../../queue/components/TeamBadge";
import {
  DISPLAY_NEXTUP_COMPACT_NAME,
  DISPLAY_NEXTUP_HERO_NAME,
} from "../../../common/utils/displayTypography";

const EMOJIS = ["😎", "🏓", "⚡", "🌟", "🔥", "🎯", "💪", "🏆", "😄", "🤩"];

function emojiForId(id) {
  const s = String(id || "0");
  let hash = 0;
  for (let i = 0; i < s.length; i += 1) hash = (hash * 31 + s.charCodeAt(i)) >>> 0;
  return EMOJIS[hash % EMOJIS.length];
}

function playerPhoto(player) {
  return player?.imageUrl || player?.photo || player?.avatarUrl || null;
}

function resolveMatchSides(queueItem, players) {
  const ids = queueItem?.playerIds || [];
  const resolved = ids
    .map((id) => players.find((p) => String(p.id) === String(id)))
    .filter(Boolean);
  if (resolved.length === 0) return { green: [], blue: [] };
  const half = Math.ceil(resolved.length / 2);
  return {
    green: resolved.slice(0, half),
    blue: resolved.slice(half),
  };
}

/** Trading-card portrait — same language as leaderboard podium. */
function HeroPlayerCard({ player, side = "green" }) {
  const src = playerPhoto(player);
  const frame =
    side === "green"
      ? "border-emerald-400/55 shadow-[0_8px_28px_rgba(16,185,129,0.22)]"
      : "border-sky-400/55 shadow-[0_8px_28px_rgba(56,189,248,0.22)]";

  return (
    <div
      className={`relative h-full min-h-0 w-full max-w-full aspect-[3/4] max-h-full rounded-2xl border-[3px] md:border-4 overflow-hidden bg-gradient-to-b from-white/15 to-white/5 ${frame}`}
    >
      {src ? (
        <img
          src={src}
          alt={player?.name || ""}
          className="absolute inset-0 h-full w-full object-cover"
        />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-br from-slate-700/80 to-slate-900/90 text-[clamp(2.5rem,8vmin,5rem)]">
          {emojiForId(player?.id)}
        </div>
      )}
      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent pointer-events-none" />
      <div className="absolute inset-x-0 bottom-0 p-2 md:p-2.5 pt-8 pointer-events-none">
        <div
          className="!text-white font-display font-extrabold italic uppercase text-center leading-[1.05] break-words drop-shadow-md"
          style={{ fontSize: DISPLAY_NEXTUP_HERO_NAME }}
        >
          {player.name}
        </div>
      </div>
      <div className="absolute inset-0 ring-1 ring-inset ring-white/10 pointer-events-none rounded-2xl" />
    </div>
  );
}

function SideColumn({ players, label, compact, hero, teamsModeEnabled, teams, teamsSettings }) {
  const playersRow = hero && players.length <= 2;
  const side = String(label || "").toLowerCase() === "blue" ? "blue" : "green";
  const teamLabelClass = compact
    ? "text-[10px] md:text-xs text-white/45"
    : hero
      ? "text-sm md:text-base text-emerald-300/85"
      : "text-xs md:text-sm text-emerald-300/80";

  return (
    <div className="flex flex-col gap-1 md:gap-1.5 flex-1 min-w-0 min-h-0">
      <div
        className={`text-center font-bold uppercase tracking-widest shrink-0 ${teamLabelClass} ${
          side === "blue" && hero ? "!text-sky-300/85" : ""
        }`}
      >
        {label}
      </div>
      <div
        className={`flex flex-1 min-h-0 gap-2 md:gap-3 ${
          playersRow ? "flex-row items-stretch justify-center" : "flex-col"
        }`}
      >
        {players.map((p) => {
          const src = playerPhoto(p);
          const tb = teamsModeEnabled
            ? resolvePlayerTeamBadge(p, teams, true, teamsSettings?.unassignedLabel)
            : null;

          if (hero) {
            return (
              <div key={p.id} className="flex-1 min-w-0 min-h-0 flex items-stretch justify-center">
                <HeroPlayerCard player={p} side={side} />
              </div>
            );
          }

          return (
            <div
              key={p.id}
              className={`rounded-lg border border-white/10 bg-white/5 flex flex-col items-center justify-center min-w-0 flex-1 min-h-0 ${
                compact ? "px-1.5 py-2 gap-1" : "px-2 py-3 md:py-4 gap-2"
              }`}
            >
              {src ? (
                <img
                  src={src}
                  alt={p.name}
                  className={`rounded-full object-cover border-2 border-white/30 shrink-0 ${
                    compact ? "h-11 w-11 md:h-14 md:w-14" : "h-16 w-16 md:h-24 md:w-24"
                  }`}
                />
              ) : (
                <div
                  className={`rounded-full bg-white/10 flex items-center justify-center border-2 border-white/20 shrink-0 ${
                    compact
                      ? "h-11 w-11 md:h-14 md:w-14 text-lg md:text-2xl"
                      : "h-16 w-16 md:h-24 md:w-24 text-2xl md:text-4xl"
                  }`}
                >
                  {emojiForId(p.id)}
                </div>
              )}
              <div
                className="!text-white font-display font-extrabold italic uppercase text-center truncate w-full leading-tight"
                style={{ fontSize: DISPLAY_NEXTUP_COMPACT_NAME }}
              >
                {p.name}
              </div>
              {tb && !compact && (
                <TeamBadge letter={tb.letter} color={tb.color} title={tb.title} />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function MatchCard({
  queueItem,
  players,
  variant,
  label,
  teamsModeEnabled,
  teams,
  teamsSettings,
}) {
  const { green, blue } = useMemo(
    () => resolveMatchSides(queueItem, players),
    [queueItem, players]
  );
  const compact = variant === "compact";
  const hero = variant === "hero";

  if (!queueItem || green.length + blue.length === 0) return null;

  return (
    <div
      className={`h-full min-h-0 flex flex-col rounded-xl border border-white/15 bg-white/[0.04] overflow-hidden ${
        compact ? "p-2" : "p-2.5 md:p-4"
      }`}
    >
      <div
        className={`shrink-0 font-display font-extrabold italic uppercase tracking-widest text-white/50 ${
          compact ? "text-xs mb-1" : "text-base md:text-lg mb-2"
        }`}
      >
        {label}
      </div>
      <div className={`flex-1 min-h-0 flex items-stretch ${hero ? "gap-3 md:gap-5" : "gap-2 md:gap-3"}`}>
        <SideColumn
          players={green}
          label="Green"
          compact={compact}
          hero={hero}
          teamsModeEnabled={teamsModeEnabled}
          teams={teams}
          teamsSettings={teamsSettings}
        />
        <SideColumn
          players={blue}
          label="Blue"
          compact={compact}
          hero={hero}
          teamsModeEnabled={teamsModeEnabled}
          teams={teams}
          teamsSettings={teamsSettings}
        />
      </div>
    </div>
  );
}

function UpcomingPlaceholder({ label }) {
  return (
    <div className="h-full min-h-0 flex flex-col rounded-xl border border-dashed border-white/25 bg-white/[0.02] p-2 overflow-hidden">
      <div className="shrink-0 text-xs font-display font-extrabold italic uppercase tracking-widest text-white/35 mb-1">
        {label}
      </div>
      <div className="flex-1 min-h-0 flex items-stretch gap-2">
        <PlaceholderTeamSide teamLabel="Green" />
        <PlaceholderTeamSide teamLabel="Blue" />
      </div>
    </div>
  );
}

function PlaceholderTeamSide({ teamLabel }) {
  return (
    <div className="flex-1 min-w-0 min-h-0 flex flex-col gap-1">
      <div className="text-center text-[10px] font-bold uppercase tracking-widest text-white/30">
        {teamLabel}
      </div>
      <div className="flex-1 min-h-0 flex flex-row gap-1">
        {[0, 1].map((i) => (
          <div
            key={i}
            className="flex-1 min-w-0 rounded-lg border border-white/10 bg-white/[0.03] flex flex-col items-center justify-center gap-1 py-2"
          >
            <div className="h-11 w-11 rounded-full border-2 border-dashed border-white/20 bg-white/[0.04]" />
            <span className="text-[10px] uppercase tracking-wider text-white/25 font-display italic">TBD</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function HeroEmptyPlaceholder() {
  return (
    <div className="h-full min-h-0 flex flex-col rounded-xl border border-dashed border-white/20 bg-white/[0.02] p-3 overflow-hidden items-center justify-center">
      <div className="text-base md:text-lg font-display font-extrabold italic uppercase tracking-widest text-white/35 mb-2">
        ★ Next Match
      </div>
      <p className="text-white/40 uppercase tracking-widest text-base md:text-lg font-display font-extrabold italic text-center">
        No match queued
      </p>
    </div>
  );
}

export default function NextUpView({
  matchQueue = [],
  players = [],
  settings,
  teams = [],
  teamsSettings = {},
}) {
  const upcoming = useMemo(() => (matchQueue || []).slice(0, 3), [matchQueue]);

  if (settings?.displayQueueVisible === false) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="font-display font-extrabold italic uppercase tracking-widest text-3xl md:text-5xl text-white/35 text-center leading-snug px-8">
          Queueing in Progress
        </div>
      </div>
    );
  }

  const hero = upcoming[0] || null;
  const second = upcoming[1] || null;
  const third = upcoming[2] || null;
  const cardProps = {
    players,
    teamsModeEnabled: settings?.teamsModeEnabled,
    teams,
    teamsSettings,
  };

  return (
    <div className="h-full min-h-0 flex flex-col px-2 md:px-4 pb-1 overflow-hidden">
      <div className="text-center shrink-0 mb-1">
        <p className="text-[11px] text-white/45 uppercase tracking-[0.35em] mb-0.5">Up Next</p>
        <h2 className="!text-white text-2xl md:text-4xl font-display font-extrabold italic uppercase tracking-widest leading-none">
          Next Up
        </h2>
      </div>

      <div className="flex-1 min-h-0 flex flex-col gap-2 md:gap-2.5 overflow-hidden">
        <div className="flex-[1.35] min-h-0 overflow-hidden">
          {hero ? (
            <MatchCard
              queueItem={hero}
              variant="hero"
              label="★ Next Match"
              {...cardProps}
            />
          ) : (
            <HeroEmptyPlaceholder />
          )}
        </div>

        <div className="flex-[0.48] min-h-0 max-h-[32%] grid grid-cols-2 gap-2 md:gap-3 overflow-hidden">
          <div className="min-h-0 h-full">
            {second ? (
              <MatchCard queueItem={second} variant="compact" label="#2 Upcoming" {...cardProps} />
            ) : (
              <UpcomingPlaceholder label="#2 Upcoming" />
            )}
          </div>
          <div className="min-h-0 h-full">
            {third ? (
              <MatchCard queueItem={third} variant="compact" label="#3 Upcoming" {...cardProps} />
            ) : (
              <UpcomingPlaceholder label="#3 Upcoming" />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
